INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-maker', 'SNES', 'Super Mario Bros. Maker', '2024', 'Platform/Hack', 'Homebrew', '1', 'Level Creation Platformer', 'Level creation tool for the Super Nintendo.', 'Design and play your own 16-bit Mario stages.', 'Try the fan-made Super Mario Maker on the SNES.', 'A technical 16-bit marvel. A fan-developed tool that allows players to place blocks, enemies, and pipes in real-time to create custom levels on original hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---64-reverse-remake', 'SNES', 'Super Mario Kart - 64 Reverse Remake', '2020', 'Racing/Hack', 'Homebrew', '2', 'Reverse Track Racing', 'Nintendo 64 track recreation in 16-bit.', 'Race the N64 circuits in the original 16-bit engine.', 'Try Mario Kart: 64 Reverse Remake on the SNES.', 'A creative 16-bit mod that translates Mario Kart 64''s track layouts into the Mode 7 world of the SNES, featuring "Reverse" mode for extra challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---deaths-courses', 'SNES', 'Super Mario Kart - Death''s Courses', '2019', 'Racing/Hack', 'Homebrew', '2', 'Challenge Track Racing', 'High-difficulty racing modification.', 'Survive the most dangerous tracks in Mario Kart history.', 'Play Super Mario Kart: Death''s Courses on SNES.', 'A 16-bit hack designed for experts. Features tracks with thin paths, no railings, and extreme hazard placement that requires pixel-perfect driving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---double-dash-reverse-remake', 'SNES', 'Super Mario Kart - Double Dash Reverse Remake', '2021', 'Racing/Hack', 'Homebrew', '2', 'Crossover Reverse Racing', 'GameCube track recreation in 16-bit.', 'Experience Double Dash tracks in classic Mode 7.', 'Try Mario Kart: Double Dash Reverse Remake on SNES.', 'A technical 16-bit mod. Translates the iconic layouts of the GameCube classic into the SNES engine, including the "mirrored" reverse versions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---expert-quest', 'SNES', 'Super Mario Kart - Expert Quest', '2018', 'Racing/Hack', 'Homebrew', '2', 'High Difficulty Racing', 'Veteran-level racing challenge modification.', 'Prove your skill in the "Expert" 16-bit cups.', 'Play Super Mario Kart: Expert Quest on the SNES.', 'A 16-bit romhack featuring brand new, highly technical track designs that push the game''s AI and the player''s drifting abilities to the limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---f1-tracks', 'SNES', 'Super Mario Kart - F1 Tracks', '2019', 'Racing/Hack', 'Homebrew', '2', 'Formula-Style Racing', 'Real-world racing circuit recreation.', 'Race on the world''s most famous F1 tracks in 16-bit.', 'Play Super Mario Kart: F1 Tracks on the SNES.', 'A creative 16-bit mod that replaces the Mushroom Kingdom tracks with digital recreations of Monaco, Silverstone, and Suzuka using the Mode 7 engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---horizons-13', 'SNES', 'Super Mario Kart - Horizons 1.3', '2020', 'Racing/Hack', 'Homebrew', '2', 'Custom Track Racing', 'Thematic racing world overhaul (v1.3).', 'Discover new horizons in this polished 16-bit hack.', 'Experience Super Mario Kart: Horizons on the SNES.', 'A massive 16-bit overhaul. Features new track themes, custom palettes, and a rebalanced item system for a fresh take on the classic racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---mirror-mode', 'SNES', 'Super Mario Kart - Mirror Mode', '2017', 'Racing/Hack', 'Homebrew', '2', 'Mirror Track Racing', 'Horizontal track flipping modification.', 'Master the mirrored 16-bit circuits in Mirror Mode.', 'Try Super Mario Kart Mirror Mode on the SNES.', 'A technical 16-bit hack that flips the track data horizontally. It forces players to relearn every turn in a mirrored perspective.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---pure-racing-edition', 'SNES', 'Super Mario Kart - Pure Racing Edition', '2021', 'Racing/Hack', 'Homebrew', '2', 'Simulation-Oriented Kart Racing', 'Competitive-focused racing modification.', 'Race on tracks designed for pure 16-bit skill.', 'Try Super Mario Kart: Pure Racing Edition on SNES.', 'A 16-bit mod that removes some of the "unfair" RNG elements and redesigns tracks to emphasize drifting lines and speed maintenance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---reverse-and-reverse-mirror-mode', 'SNES', 'Super Mario Kart - Reverse and Reverse Mirror Mode', '2020', 'Racing/Hack', 'Homebrew', '2', 'Reverse Mirror Racing', 'Double perspective challenge modification.', 'Race backwards and mirrored in the ultimate 16-bit test.', 'Try SMK Reverse and Mirror Mode on the SNES.', 'A 16-bit hack that combines two challenges in one. Tracks are both mirrored and driven in the opposite direction, testing the ultimate memory of the player.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---shelfall-series-1', 'SNES', 'Super Mario Kart - Shelfall Series 1', '2019', 'Racing/Hack', 'Homebrew', '2', 'Custom Cup Racing', 'Creative track design series (Part 1).', 'Explore the first set of Shelfall''s custom 16-bit tracks.', 'Play SMK: Shelfall Series 1 on the SNES.', 'A 16-bit romhack featuring highly creative and aesthetically pleasing new tracks that utilize the SNES''s color palette in unique ways.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---shelfall-series-2', 'SNES', 'Super Mario Kart - Shelfall Series 2', '2019', 'Racing/Hack', 'Homebrew', '2', 'Custom Cup Racing', 'Creative track design series (Part 2).', 'Master the second wave of Shelfall''s 16-bit racing.', 'Play SMK: Shelfall Series 2 on the SNES.', 'The sequel to the popular hack series. Includes more complex elevation-style illusions using Mode 7 and increased technical difficulty in the Star Cup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---shelfall-series-3', 'SNES', 'Super Mario Kart - Shelfall Series 3', '2019', 'Racing/Hack', 'Homebrew', '2', 'Custom Cup Racing', 'Creative track design series (Part 3).', 'Survive the third series of technical 16-bit racing.', 'Play SMK: Shelfall Series 3 on the SNES.', 'Expands on the Shelfall formula with more aggressive AI and tracks that feature multiple paths and shortcuts for skilled 16-bit racers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---shelfall-series-4', 'SNES', 'Super Mario Kart - Shelfall Series 4', '2019', 'Racing/Hack', 'Homebrew', '2', 'Custom Cup Racing', 'Creative track design series (Part 4).', 'Complete the Shelfall 16-bit racing legacy.', 'Play SMK: Shelfall Series 4 on the SNES.', 'The final entry in the series. Features the most polished track designs and a custom "Special Cup" that serves as the ultimate 16-bit racing test.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart---sylvain-kart-custom-tracks', 'SNES', 'Super Mario Kart - Sylvain Kart Custom Tracks', '2020', 'Racing/Hack', 'Homebrew', '2', 'Community Track Pack', 'Custom track pack by Sylvain.', 'Race through Sylvain''s unique 16-bit track creations.', 'Try Sylvain Kart Custom Tracks on the SNES.', 'A 16-bit romhack featuring a collection of tracks with unique themes and obstacle placements not seen in the original retail game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart-20xx-ntsc', 'SNES', 'Super Mario Kart 20XX NTSC', '2016', 'Racing/Hack', 'Homebrew', '2', 'Expanded Vanilla Racing', 'Competitively balanced 16-bit racing (NTSC).', 'Experience the frame-perfect 20XX competitive standard.', 'Play Super Mario Kart 20XX (NTSC) on the SNES.', 'A 16-bit mod designed for the competitive community. Fixes specific bugs, balances character stats, and optimizes the engine for high-level tournament play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart-20xx-pal', 'SNES', 'Super Mario Kart 20XX PAL', '2016', 'Racing/Hack', 'Homebrew', '2', 'Expanded Vanilla Racing', 'Competitively balanced 16-bit racing (PAL).', 'Master the competitive 50Hz standard in 20XX.', 'Play Super Mario Kart 20XX (PAL) on the SNES.', 'The European-standard version of the competitive mod. Ensures all 20XX balance changes are perfectly adapted to the PAL frame rate.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart-deluxe', 'SNES', 'Super Mario Kart Deluxe', '2021', 'Racing/Hack', 'Homebrew', '2', 'Enhanced Kart Racing', 'Ultimate 16-bit racing compilation.', 'Play the "Deluxe" version of the SNES classic.', 'Experience Super Mario Kart Deluxe on the SNES.', 'A massive 16-bit mod that combines new tracks, character swaps (like Wario), and various quality-of-life improvements into one definitive package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart-devanny-dark-edition', 'SNES', 'Super Mario Kart Devanny Dark Edition', '2022', 'Racing/Hack', 'Homebrew', '2', 'Dark-Themed Racing', 'Dark-themed racing world overhaul.', 'Survive the "Dark Edition" of the 16-bit circuits.', 'Try SMK Devanny Dark Edition on the SNES.', 'A visual and difficulty 16-bit hack. Features a dark, night-time aesthetic for all tracks and a significantly increased difficulty for the CPU racers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart-featuring-retro-hd-&-friends', 'SNES', 'Super Mario Kart Featuring Retro HD & Friends', '2021', 'Racing/Hack', 'Homebrew', '2', 'Crossover Kart Racing', 'HD-inspired retro racing world.', 'Race with Retro HD and friends in this 16-bit overhaul.', 'Try SMK Featuring Retro HD on the SNES.', 'A 16-bit mod that updates the game''s visuals with high-contrast palettes and adds new characters from various retro franchises to the roster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart-reversed-n-remixed', 'SNES', 'Super Mario Kart Reversed n'' Remixed', '2020', 'Racing/Hack', 'Homebrew', '2', 'Remixed Track Racing', 'Remixed and reversed racing challenge.', 'Experience a fresh take on the classic 16-bit tracks.', 'Play SMK Reversed n'' Remixed on the SNES.', 'A 16-bit mod that takes the original layouts and modifies them with new obstacles, item box placements, and a reversed driving direction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart-world', 'SNES', 'Super Mario Kart World', '2023', 'Racing/Hack', 'Homebrew', '2', 'Global Track Expansion', 'Global-themed racing world overhaul.', 'Race around the world in this massive 16-bit mod.', 'Experience Super Mario Kart World on the SNES.', 'A complete 16-bit total conversion. Replaces all 20 tracks with new designs based on real-world locations and other Nintendo franchises.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-kart:-pro-edition', 'SNES', 'Super Mario Kart: Pro Edition', '2022', 'Racing/Hack', 'Homebrew', '2', 'Competitive Kart Racing', 'The "Professional" competitive racing standard.', 'Test your 16-bit skills in the ultimate Pro edition.', 'Play Super Mario Kart: Pro Edition on the SNES.', 'A 16-bit hack tailored for veterans. Features redesigned tracks that eliminate luck-based elements and reward perfect racing lines and drift control.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-land-3---tatangas-return-v21', 'SNES', 'Super Mario Land 3 - Tatanga''s Return (V2.1)', '2019', 'Platform/Hack', 'Homebrew', '1', 'Mario-Style Platformer', 'Side-scrolling platformer (Fan-recreation).', 'Defeat Tatanga and rescue the kingdom in this SNES remake.', 'Play Super Mario Land 3: Tatanga''s Return on SNES.', 'A stunning 16-bit reimagining of the Game Boy classic. Features completely new levels, updated Super Mario World-style physics, and a full 16-bit color palette and soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-rpg---master-quest', 'SNES', 'Super Mario RPG - Master Quest', '2018', 'RPG/Hack', 'Homebrew', '1', 'Challenge-Based RPG', 'Turn-based RPG (Balance & Content Hack).', 'Experience a tougher, more strategic Smithy saga.', 'Try Super Mario RPG: Master Quest on the SNES.', 'A 16-bit overhaul of the RPG classic. Rebalances all character stats, introduces new enemy behaviors, and adds hidden endgame content for veterans seeking a fresh challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-rpg-armageddon-v10-hard', 'SNES', 'Super Mario RPG Armageddon v10 (Hard)', '2020', 'RPG/Hack', 'Homebrew', '1', 'Hardcore RPG Remix', 'Ultra-hard turn-based RPG (V10 Hard).', 'Survive the most brutal version of Mario''s RPG world.', 'Play Super Mario RPG Armageddon (Hard) on SNES.', 'A technical 16-bit modification designed for extreme difficulty. Features new bosses, a revised magic system, and encounters that require perfect timing and deep strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-rpg-armageddon-v10-normal', 'SNES', 'Super Mario RPG Armageddon v10 (Normal)', '2020', 'RPG/Hack', 'Homebrew', '1', 'Story RPG Remix', 'Turn-based RPG (V10 Normal).', 'Enjoy expanded RPG content with balanced difficulty.', 'Try Super Mario RPG Armageddon (Normal) on SNES.', 'The more accessible version of the massive Armageddon mod. Adds dozens of new items, side quests, and playable character tweaks while maintaining a fair 16-bit challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-rpg-enhanced', 'SNES', 'Super Mario RPG Enhanced', '2017', 'RPG/Hack', 'Homebrew', '1', 'Quality-of-Life RPG', 'Polished turn-based RPG (Quality of Life).', 'Experience Mario''s RPG debut with modern refinements.', 'Play Super Mario RPG Enhanced on the SNES.', 'A 16-bit improvement hack. Adds a dash button, fixes original bugs, and clarifies item descriptions without altering the core gameplay of the 1996 masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-rpg-revolution', 'SNES', 'Super Mario RPG Revolution', '2019', 'RPG/Hack', 'Homebrew', '1', 'Rebalanced RPG', 'Turn-based RPG (Content Overhaul).', 'Rediscover the Seven Stars in this creative revolution.', 'Explore Super Mario RPG Revolution on the SNES.', 'A 16-bit total overhaul featuring new dialogue, modified dungeons, and unique enemy palettes, giving the original adventure a vibrant new identity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-vs-zombies', 'SNES', 'Super Mario Vs Zombies', '2021', 'Action/Hack', 'Homebrew', '1', 'Action Survival Platformer', 'Side-scrolling survival platformer.', 'Survive the undead apocalypse in the Mushroom Kingdom.', 'Experience Super Mario Vs Zombies on the SNES.', 'A 16-bit horror-themed hack of Mario World. Fight through dark, decaying environments where traditional enemies are replaced by relentless zombie hordes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---30th-anniversary-edition-1-3-24', 'SNES', 'Super Mario World - 30th Anniversary Edition (1-3-24)', '2024', 'Platform/Hack', 'Homebrew', '1', 'Anniversary Enhanced Platformer', 'Polished side-scrolling platformer (2024).', 'Celebrate 30 years with the ultimate Mario World fix.', 'Play SMW: 30th Anniversary Edition on SNES.', 'The definitive 16-bit "vanilla" update. Incorporates modern bug fixes, restored content, and subtle graphical improvements into the original 1990 masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---burning-in-hell', 'SNES', 'Super Mario World - Burning in Hell', '2019', 'Platform/Hack', 'Homebrew', '1', 'Dark Difficulty Platformer', 'High-difficulty survival platformer.', 'Escape the underworld in this hell-themed Mario hack.', 'Play Super Mario World: Burning in Hell on SNES.', 'A 16-bit "Kaizo" style hack featuring lava-filled levels, custom fire-based obstacles, and a punishing difficulty curve designed for professional speedrunners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---chaos-edition', 'SNES', 'Super Mario World - Chaos Edition', '2018', 'Platform/Hack', 'Homebrew', '1', 'Randomized Chaos Platformer', 'Randomized chaotic platformer.', 'Survive the unpredictable glitches of the Chaos Edition.', 'Try Super Mario World: Chaos Edition on the SNES.', 'A bizarre and hilarious 16-bit experience. The game''s code is intentionally randomized, causing unpredictable sprite swaps, gravity shifts, and visual glitches every few seconds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---dlrow-oiram-repus!!-smw-inverted', 'SNES', 'Super Mario World - dlroW oiraM repuS!! (SMW Inverted)', '2017', 'Platform/Hack', 'Homebrew', '1', 'Inverted Gameplay Platformer', 'Inverted side-scrolling platformer.', 'Master the Mushroom Kingdom in reverse and upside down.', 'Try SMW: Inverted (dlroW oiraM repuS) on SNES.', 'A technical 16-bit flip. Every level is mirrored and inverted, forcing players to re-learn their muscle memory for one of the most famous games in history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---hack-4', 'SNES', 'Super Mario World - Hack 4', '2016', 'Platform/Hack', 'Homebrew', '1', 'Experimental Platformer', 'Traditional fan-made expansion (Hack 4).', 'Explore 80 brand new levels in this classic expansion.', 'Play Super Mario World: Hack 4 on the SNES.', 'A massive 16-bit fan sequel. Features original level designs that follow the classic Nintendo "design language" while introducing creative new puzzles and secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---one-mind', 'SNES', 'Super Mario World - One Mind', '2020', 'Platform/Hack', 'Homebrew', '1', 'Puzzle-Oriented Platformer', 'Experimental shared-control platformer.', 'Control Mario with a friend in this unique "One Mind" test.', 'Try Super Mario World: One Mind on the SNES.', 'A unique 16-bit social experiment. Two players share control of different aspects of Mario''s movement (e.g., one jumps, one runs), requiring perfect coordination to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---super-mario-bros-1-style-hack-2022-update', 'SNES', 'Super Mario World - Super Mario Bros. 1 Style Hack (2022 Update)', '2022', 'Platform/Hack', 'Homebrew', '1', 'Classic SMB1-Style Platformer', 'Retro-style side-scrolling platformer (2022).', 'Experience Mario World with original NES aesthetics.', 'Play the SMB1 Style Hack (2022) on the SNES.', 'A 16-bit total conversion. Replaces all graphics, sound effects, and music with assets from the original 1985 Super Mario Bros., creating a fascinating 16-bit "demake."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---super-mario-bros-1-style-hack-beta-test', 'SNES', 'Super Mario World - Super Mario Bros. 1 Style Hack (Beta Test)', '2021', 'Platform/Hack', 'Homebrew', '1', 'Classic SMB1-Style Platformer', 'Retro-style platformer (Technical Beta).', 'Test the early implementation of the NES style in SMW.', 'Check out the SMB1 Style Hack Beta on the SNES.', 'A rare 16-bit development look at the total conversion project. Showcases the initial sprite work and physics tuning of the NES-to-SNES transition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---super-mario-bros-3-style-hack', 'SNES', 'Super Mario World - Super Mario Bros. 3 Style Hack', '2020', 'Platform/Hack', 'Homebrew', '1', 'Classic SMB3-Style Platformer', 'Hybrid side-scrolling platformer.', 'Enjoy the best of Mario 3 within the Mario World engine.', 'Play the SMB3 Style Hack on the Super Nintendo.', 'A 16-bit masterpiece that brings the world map, items, and visual style of Super Mario Bros. 3 into the fluid 16-bit engine of Super Mario World.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---super-mario-bros-3-style-hack-luigi-version', 'SNES', 'Super Mario World - Super Mario Bros. 3 Style Hack Luigi Version', '2020', 'Platform/Hack', 'Homebrew', '1', 'SMB3-Style Platformer (Luigi)', 'Hybrid platformer (Luigi Edition).', 'Play the Mario 3-style adventure as the green brother.', 'Try SMB3 Style Hack: Luigi Version on the SNES.', 'A specialized 16-bit mod that adjusts the physics to match Luigi''s traditional high-jump and slippery movement, set within the SMB3-styled 16-bit worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---theoretical-1989-playable-demo', 'SNES', 'Super Mario World - Theoretical 1989 Playable Demo', '2019', 'Prototype/Hack', 'Homebrew', '1', 'Historical Concept Demo', 'Historical reconstruction (1989 Demo).', 'Play through the hypothetical first build of Mario World.', 'Explore the Theoretical 1989 Demo on the SNES.', 'A 16-bit fan recreation of the earliest known build of SMW. Features prototype-style sprites and level layouts based on historical design documents and sketches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-u-prototype', 'SNES', 'Super Mario World (U) (Prototype)', '1990', 'Prototype', 'Nintendo', '2', 'Unfinished Official Platformer', 'Unreleased development build (Prototype).', 'Discover the unfinished secrets of the 16-bit legend.', 'Play the Super Mario World Prototype on the SNES.', 'An authentic 16-bit historical artifact. Features "work-in-progress" level designs, different enemy behaviors, and debug tools left in by the original Nintendo developers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-2-player-co-op---the-return', 'SNES', 'Super Mario World 2 Player Co-op - The Return', '2021', 'Platform/Hack', 'Homebrew', '2', 'Co-op Platformer', 'Simultaneous 2-player cooperative platformer.', 'Rescue Peach with a partner in real-time co-op.', 'Play SMW 2-Player Co-op: The Return on SNES.', 'A technical breakthrough for the SNES. Allows two players to play through the entire game simultaneously on the same screen, rather than taking turns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-3---a-whole-new-world', 'SNES', 'Super Mario World 3 - A whole new world', '2018', 'Platform/Hack', 'Homebrew', '1', 'Expanded Adventure Platformer', 'Fan-made massive sequel project.', 'Journey through a "whole new world" of 16-bit levels.', 'Experience Super Mario World 3 on the SNES.', 'A full-scale 16-bit total conversion. Features entirely new map systems, custom bosses, and a difficulty level that picks up right where the original game left off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-4-player', 'SNES', 'Super Mario World 4-Player', '2022', 'Platform/Hack', 'Homebrew', '4', 'Multiplayer Party Platformer', 'Multiplayer arena and platforming (4-Player).', 'Play with three friends in the ultimate Mario chaos.', 'Try Super Mario World 4-Player on the SNES.', 'An incredible 16-bit technical feat. Uses specialized code to allow four players to interact simultaneously on a single console, redefining the 16-bit platforming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-beta-edit-beta', 'SNES', 'Super Mario World Beta Edit (Beta)', '2017', 'Platform/Hack', 'Homebrew', '1', 'Beta Restoration Platformer', 'Beta reconstruction and edit (v5.0).', 'Explore the "lost" features of Mario World''s beta.', 'Play the Super Mario World Beta Edit on the SNES.', 'A creative 16-bit mod that restores unused sprites (like the original Iggy Koopa) and beta level concepts found in the Nintendo source code leaks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-central-production-2', 'SNES', 'Super Mario World Central Production 2', '2019', 'Platform/Hack', 'Homebrew', '1', 'Large-Scale Community Hack', 'Collaborative fan-made level collection.', 'Play the best levels from the world''s top SMW hackers.', 'Try SMW Central Production 2 on the SNES.', 'A 16-bit showcase of talent. A massive, high-quality collaboration featuring professional-grade level design, custom music, and advanced 16-bit coding techniques.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-co-op-english-v50', 'SNES', 'Super Mario World Co-op English V5.0', '2020', 'Platform/Hack', 'Homebrew', '2', 'Co-op Platformer', 'Simultaneous co-op (English V5.0).', 'Coordinate with a partner in this polished co-op hack.', 'Play SMW Co-op English v5.0 on the SNES.', 'The definitive 16-bit simultaneous 2-player experience. Optimized for minimal lag and full compatibility with the original game''s secrets and world map.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-co-op-hack', 'SNES', 'Super Mario World Co-op Hack', '2019', 'Platform/Hack', 'Homebrew', '2', 'Co-op Platformer', 'Simultaneous co-op (Early Hack).', 'Test the foundational co-op mechanics in Mario World.', 'Try the Super Mario World Co-op Hack on SNES.', 'One of the first 16-bit attempts to bridge the gap between players. A technical milestone that paved the way for more stable simultaneous multiplayer mods.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-co-op-v50', 'SNES', 'Super Mario World Co-op V5.0', '2020', 'Platform/Hack', 'Homebrew', '2', 'Co-op Platformer', 'Simultaneous co-op (Version 5.0).', 'Team up in the final stable 16-bit co-op build.', 'Experience SMW Co-op v5.0 on the Super Nintendo.', 'Features perfect synchronization between Mario and Luigi. This 16-bit mod allows for unique cooperative strategies, such as jumping off a partner''s head to reach secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-feat-marisa-kirisame', 'SNES', 'Super Mario World feat. Marisa Kirisame', '2021', 'Platform/Hack', 'Homebrew', '1', 'Crossover Character Platformer', 'Character swap platformer (Touhou Project).', 'Navigate the Mushroom Kingdom as the witch Marisa.', 'Play SMW feat. Marisa Kirisame on the SNES.', 'A 16-bit crossover mod. Replaces Mario with the famous Touhou character, featuring custom sprites, unique flight mechanics, and a specialized 16-bit soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-hack-6', 'SNES', 'Super Mario World Hack 6', '2016', 'Platform/Hack', 'Homebrew', '1', 'Experimental Platformer', 'Traditional expansion (Hack 6).', 'Conquer the sixth chapter of this legendary hack series.', 'Experience Super Mario World: Hack 6 on the SNES.', 'Known for its creative use of the 16-bit color palette and complex puzzle-solving. Features some of the most inventive level gimmicks in the SMW hacking scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-random-revolution-x-v10', 'SNES', 'Super Mario World Random Revolution X V1.0', '2020', 'Platform/Hack', 'Homebrew', '1', 'Randomized Gameplay Platformer', 'Procedural/Randomized platformer (v1.0).', 'Survive a completely randomized 16-bit world.', 'Try SMW: Random Revolution X on the SNES.', 'A high-replayability 16-bit mod. Every time you play, the items, enemies, and even level exits are shuffled, requiring total mastery of the 16-bit physics to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world-redrawn', 'SNES', 'Super Mario World Redrawn', '2019', 'Platform/Hack', 'Homebrew', '1', 'Visual Redesign Platformer', 'High-fidelity graphical overhaul.', 'Play Mario World with stunning, hand-drawn graphics.', 'Experience Super Mario World Redrawn on the SNES.', 'A visual masterpiece. Every single 16-bit sprite and background tile has been replaced with detailed, cartoon-quality art, making the classic look like a modern title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario+luigi-world-co-op-v41', 'SNES', 'Super Mario+Luigi World Co-op (V4.1)', '2021', 'Platform/Hack', 'Homebrew', '2', 'Mario & Luigi Co-op Platformer', 'Simultaneous 2-player cooperative platformer.', 'Rescue Peach with Mario and Luigi at the same time.', 'Play Super Mario+Luigi World Co-op (V4.1) on SNES.', 'A technical 16-bit breakthrough. Allows two players to play simultaneously on screen. This version fixes desync issues and optimizes sprite handling for a smooth cooperative experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-marisa-adventure-world', 'SNES', 'Super Marisa Adventure World', '2020', 'Platform/Hack', 'Homebrew', '1', 'Touhou-Themed Platformer', 'Action-platformer crossover (Touhou Project).', 'Explore the Mushroom Kingdom as Marisa Kirisame.', 'Play Super Marisa Adventure World on the SNES.', 'A 16-bit total conversion of SMW. Replaces Mario with the Touhou witch, featuring custom magic-based attacks, unique flight physics, and a specialized 16-bit soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-marisa-adventure-world-2---mari-mari-back-forward-around-world-6-demo', 'SNES', 'Super Marisa Adventure World 2 - Mari Mari Back Forward Around (World-6 Demo)', '2018', 'Platformer', 'Doujin Soft', '1', '2D side-scrolling', 'Action-platformer crossover (World-6 Demo).', 'Test the advanced mechanics of the Marisa sequel.', 'Try Super Marisa Adventure World 2 Demo on SNES.', 'An ambitious 16-bit sequel demo. Features a non-linear level structure and "Back Forward Around" mechanics that allow for complex 16-bit exploration and hidden secret paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid---darkholme-hospital', 'SNES', 'Super Metroid - Darkholme Hospital', '2019', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Survival horror and exploration (Metroid Hack).', 'Escape the nightmare of the Darkholme medical facility.', 'Experience Super Metroid: Darkholme Hospital on SNES.', 'A dark 16-bit horror overhaul. Focuses on atmosphere, limited resources, and eerie environment design, transforming the classic exploration into a tense survival experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid---v-i-t-a-l-i-t-y', 'SNES', 'Super Metroid - V I T A L I T Y', '2019', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Atmospheric sci-fi exploration (Metroid Hack).', 'Uncover the secrets of a decaying research station.', 'Play Super Metroid: V I T A L I T Y on the SNES.', 'A cinematic 16-bit total conversion. Features a custom palette, haunting new music, and a completely original map that emphasizes environmental storytelling and discovery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid---x-fusion', 'SNES', 'Super Metroid - X-Fusion', '2019', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Action-exploration platformer (Metroid Fusion style).', 'Experience Metroid Fusion mechanics on the SNES engine.', 'Try Super Metroid: X-Fusion on the Super Nintendo.', 'A technical 16-bit hybrid. Implements the faster physics, ledge-grabbing, and ability-gate style of the GBA sequel into the high-resolution world of Super Metroid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-europe-enfrde', 'SNES', 'Super Metroid (Europe) (En,Fr,De)', '1994', 'Action-Adventure', 'Nintendo R&D1', '1', '2D exploration (Metroidvania)', 'The definitive 16-bit action-adventure.', 'Destroy Mother Brain and escape the planet Zebes.', 'Play the legendary Super Metroid on the SNES.', 'A 16-bit masterpiece. Features a massive interconnected world, iconic atmospheric music, and the "Metroidvania" design that defined an entire genre of video games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-europe-enfrde-graphic-hack-by-auximines-v099b-~super-metroid---justin-bailey', 'SNES', 'Super Metroid (Europe) (En,Fr,De) [Graphic Hack by Auximines v0.99b] (~Super Metroid - Justin Bailey)', '1994', 'Action-Adventure', 'Nintendo R&D1', '1', '2D exploration (Metroidvania)', 'Action-adventure (Justin Bailey Graphic Hack).', 'Explore Zebes as Samus without her Power Suit.', 'Try Super Metroid: Justin Bailey on the SNES.', 'A visual 16-bit fan modification. Inspired by the classic NES code, it replaces Samus''s armored sprites with her iconic leotard look while keeping the core 16-bit gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja', 'SNES', 'Super Metroid (Japan, USA) (En,Ja)', '1994', 'Action-Adventure', 'Nintendo R&D1', '1', '2D exploration (Metroidvania)', 'The definitive 16-bit action-adventure (Multi-region).', 'Stop the Space Pirates in the original 16-bit classic.', 'Experience Super Metroid (USA/Japan) on the SNES.', 'The gold standard of 16-bit exploration. Features cinematic storytelling without dialogue and a perfectly balanced progression of power-ups and hidden secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja-graphic-hack-by-auximines-v099b-~super-metroid---justin-bailey', 'SNES', 'Super Metroid (Japan, USA) (En,Ja) [Graphic Hack by Auximines v0.99b] (~Super Metroid - Justin Bailey)', '1994', 'Action-Adventure', 'Nintendo R&D1', '1', '2D exploration (Metroidvania)', 'Action-adventure (Samus Suitless Graphic Hack).', 'Play through the 16-bit epic with a new visual style.', 'Play Super Metroid (Justin Bailey) for the SNES.', 'Replaces the standard Varia and Gravity suit sprites with a detailed "suitless" Samus. A popular 16-bit aesthetic mod that pays homage to the original Metroid''s secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja-hack-by-banana-oyaji-v106-~metroid-legacy', 'SNES', 'Super Metroid (Japan, USA) (En,Ja) [Hack by Banana Oyaji v1.06] (~Metroid Legacy)', '2008', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Massive action-exploration overhaul (Metroid Legacy).', 'Re-explore a vastly expanded and modified Zebes.', 'Experience Metroid Legacy on the Super Nintendo.', 'A comprehensive 16-bit modification. Features redesigned rooms, rebalanced boss health, and a more challenging item placement to test the knowledge of Metroid veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja-hack-by-black-telomeres-v187-~super-metroid---dependence', 'SNES', 'Super Metroid (Japan, USA) (En,Ja) [Hack by Black Telomeres v1.87] (~Super Metroid - Dependence)', '2016', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'High-difficulty exploration overhaul (Dependence).', 'Navigate a complex and unforgiving 16-bit world.', 'Play Super Metroid: Dependence on the SNES.', 'A technical 16-bit hack that emphasizes sequence breaking and advanced movement. Features a tighter map layout that requires mastery of Samus''s hidden abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja-hack-by-black-telomeres-v266-~super-metroid---golden-dawn', 'SNES', 'Super Metroid (Japan, USA) (En,Ja) [Hack by Black Telomeres v2.66] (~Super Metroid - Golden Dawn)', '2017', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Gothic-themed exploration overhaul (Golden Dawn).', 'Survive the "Golden Dawn" in this massive Metroid mod.', 'Explore Super Metroid: Golden Dawn on the SNES.', 'A visually stunning 16-bit total conversion. Features a vibrant custom color palette, entirely new room structures, and a non-linear path that redefines the 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja-hack-by-crocomire-v30-~super-metroid---zebes-returns', 'SNES', 'Super Metroid (Japan, USA) (En,Ja) [Hack by Crocomire v3.0] (~Super Metroid - Zebes Returns)', '2015', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Nostalgic exploration overhaul (Zebes Returns).', 'Return to a redesigned Zebes with new surprises.', 'Try Super Metroid: Zebes Returns on the SNES.', 'A 16-bit love letter to the original. Features a map that bridges the gap between the NES original and the SNES sequel, with updated 16-bit graphics and puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja-hack-by-drewseph-v21-~super-metroid---redesign', 'SNES', 'Super Metroid (Japan, USA) (En,Ja) [Hack by Drewseph v2.1] (~Super Metroid - Redesign)', '2007', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Massive mechanical and world overhaul (Redesign).', 'Master the expanded physics and enormous world of Zebes.', 'Play Super Metroid: Redesign on the Super Nintendo.', 'One of the most famous 16-bit hacks. Features a 50% larger map, completely overhauled physics for higher jumps and faster runs, and incredibly complex new puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja-hack-by-kejardon-v11-control-freak', 'SNES', 'Super Metroid (Japan, USA) (En,Ja) [Hack by Kejardon v1.1] (Control Freak)', '2011', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Technical control modification (Control Freak).', 'Customize Samus''s 16-bit movement and button layout.', 'Try Super Metroid: Control Freak on the SNES.', 'A QoL 16-bit hack. Allows for modern control schemes, including a dedicated "aim up" and "aim down" logic and faster item switching for a more fluid experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-japan-usa-enja-hack-by-saturn-v15-~super-metroid---impossible', 'SNES', 'Super Metroid (Japan, USA) (En,Ja) [Hack by Saturn v1.5] (~Super Metroid - Impossible)', '2014', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Ultra-hard professional-grade hack (Impossible).', 'Survive the most difficult 16-bit challenge ever made.', 'Play Super Metroid: Impossible on the SNES.', 'Designed for elite players. Requires frame-perfect wall jumps, bomb jumps, and expert resource management. This 16-bit mod is a true test of human endurance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-kaizo-possible', 'SNES', 'Super Metroid Kaizo Possible', '2013', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Expert-level platforming challenge (Kaizo).', 'Master the impossible jumps in this 16-bit trial.', 'Try Super Metroid Kaizo Possible on the SNES.', 'A "Kaizo" style hack that, while extremely difficult, is designed to be completed without tools. Features precision platforming that pushes the 16-bit engine to its limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-lost-world-20', 'SNES', 'Super Metroid Lost World 2.0', '2016', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Original story and world overhaul (Lost World).', 'Discover the secrets of a forgotten 16-bit world.', 'Explore Super Metroid: Lost World 2.0 on SNES.', 'A creative 16-bit total conversion. Features a completely new planet to explore with custom assets, new boss strategies, and a unique progression system for power-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-phazon-hack-03', 'SNES', 'Super Metroid Phazon Hack 0.3', '2012', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Phazon-themed world overhaul (v0.3).', 'Survive the corruption in this 16-bit Prime-style mod.', 'Try Super Metroid Phazon Hack on the SNES.', 'A visual and mechanical 16-bit overhaul. Introduces the "Phazon" aesthetic from the Prime series, with modified palettes and increased environmental damage for a tougher challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-phazon-hack-04', 'SNES', 'Super Metroid Phazon Hack 0.4', '2013', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Advanced Phazon overhaul (v0.4).', 'Navigate the corrupted sectors of a new 16-bit world.', 'Experience Super Metroid Phazon 0.4 on the SNES.', 'An expanded version of the Phazon mod. Features more refined room transitions and a deeper integration of the "corruption" theme within the 16-bit exploration mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid-redux-v15', 'SNES', 'Super Metroid Redux v1.5', '2013', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'The definitive Quality of Life overhaul (Redux).', 'Experience Super Metroid with modern 16-bit refinements.', 'Play Super Metroid Redux on the Super Nintendo.', 'The perfect way to play. Combines widescreen support (on emulators), faster door transitions, a GBA-style map, and various bug fixes into the ultimate 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid:-ascent', 'SNES', 'Super Metroid: Ascent', '2016', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'Vertical-focused exploration overhaul (Ascent).', 'Climb through a new, vertically-designed 16-bit world.', 'Try Super Metroid: Ascent on the Super Nintendo.', 'A unique 16-bit total conversion. Focuses on vertical room designs and unconventional item gating, forcing players to rethink how they navigate the world of Metroid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid:-kaizo-edition', 'SNES', 'Super Metroid: Kaizo Edition', '2021', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'High-precision "Kaizo" challenge.', 'Overcome the most notorious 16-bit traps and jumps.', 'Play Super Metroid: Kaizo Edition on the SNES.', 'A legendary 16-bit difficulty mod. Features invisible blocks, trap rooms, and extreme platforming that requires a deep understanding of the game''s internal mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid:-subversion', 'SNES', 'Super Metroid: Subversion', '2019', 'Action-Adventure', 'Fan Developer', '1', '2D exploration (Metroidvania)', 'The ultimate 16-bit total conversion (Subversion).', 'Embark on a professional-grade new adventure.', 'Experience Super Metroid: Subversion on the SNES.', 'Widely considered the best Metroid hack. Features a massive new world, custom soundtrack, achievements, and innovative new items, rivaling the quality of an official 16-bit release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-moero!!-pro-yakyuu-japan', 'SNES', 'Super Moero!! Pro Yakyuu (Japan)', '1994', 'Sports', 'Namco', '2', 'Sports simulation', 'Arcade-style baseball simulation.', 'Win the 16-bit professional league with high-energy plays.', 'Play Super Moero!! Pro Yakyuu on the Super Famicom.', 'The SNES entry in the "Bases Loaded" lineage. Known for its dramatic "TV-style" camera angles and expressive character sprites during home runs and strikeouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-momotarou-dentetsu-dx---jr-nishi-nihon-presents-japan', 'SNES', 'Super Momotarou Dentetsu DX - Jr Nishi-Nihon Presents (Japan)', '1995', 'Board Game', 'Hudson Soft', '4', 'Turn-based board game', 'Board game with train management (Special Edition).', 'Build a travel empire across Western Japan.', 'Explore Momotarou Dentetsu DX (Jr Nishi-Nihon) on SNES.', 'A rare promotional version sponsored by Japan Railways. Travel across a board representing Western Japan, buying properties and managing finances in a charming 16-bit competitive format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-momotarou-dentetsu-dx-japan', 'SNES', 'Super Momotarou Dentetsu DX (Japan)', '1995', 'Board Game', 'Hudson Soft', '4', 'Turn-based board game', 'Advanced board game and property management.', 'Become the wealthiest tycoon in this 16-bit classic.', 'Experience Super Momotarou Dentetsu DX on SNES.', 'The "Deluxe" edition of the hit franchise. Features expanded maps, more random events, and the infamous "God of Misfortune" who can ruin even the best strategic plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-momotarou-dentetsu-ii-japan', 'SNES', 'Super Momotarou Dentetsu II (Japan)', '1992', 'Board Game', 'Hudson Soft', '4', 'Turn-based board game', 'Board game with trading and transportation.', 'Outsmart your rivals in this digital 16-bit board game.', 'Play Super Momotarou Dentetsu II on Super Famicom.', 'A foundational 16-bit entry. Navigate the Japanese rail network, invest in local businesses, and use special cards to sabotage your opponents in a race for wealth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-momotarou-dentetsu-iii-japan', 'SNES', 'Super Momotarou Dentetsu III (Japan)', '1994', 'Board Game', 'Hudson Soft', '4', 'Turn-based board game', 'Strategic board game with expanded systems.', 'Conquer the 16-bit real estate market across Japan.', 'Experience Super Momotarou Dentetsu III on SNES.', 'Introduces new mechanical events and refined balance. A favorite for local multiplayer, blending luck-based dice rolls with long-term financial strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-momotarou-dentetsu-iii-japan-rev-a', 'SNES', 'Super Momotarou Dentetsu III (Japan) (Rev A)', '1994', 'Board Game', 'Hudson Soft', '4', 'Turn-based board game', 'Strategic board game (Updated Revision).', 'Experience the refined tycoon gameplay in Rev A.', 'Play Momotarou Dentetsu III (Rev A) on Super Famicom.', 'The updated 16-bit retail version. Fixes minor balance issues with specific property values and optimizes the event-trigger frequency for a smoother experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-momotarou-dentetsu-iii-japan-rev-b', 'SNES', 'Super Momotarou Dentetsu III (Japan) (Rev B)', '1994', 'Board Game', 'Hudson Soft', '4', 'Turn-based board game', 'Strategic board game (Final Revision).', 'Master the ultimate version of the third 16-bit entry.', 'Play Momotarou Dentetsu III (Rev B) on Super Famicom.', 'The definitive 16-bit patch. Includes final bug fixes for the save system and minor text corrections, ensuring the most stable competitive board game play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-morph-europe', 'SNES', 'Super Morph (Europe)', '1993', 'Platformer', 'Millennium Interactive', '2', '2D side-scrolling', 'Shape-shifting puzzle platformer.', 'Navigate complex environments by changing your physical state.', 'Play the unique Super Morph on the Super Nintendo.', 'A creative 16-bit puzzler. Transform into gas, liquid, or solid forms to solve environmental challenges and reach the exit in a series of increasingly difficult levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-naxat-open---golf-de-shoubu-da-dorabot-chan-japan', 'SNES', 'Super Naxat Open - Golf de Shoubu da Dorabot-chan (Japan)', '1993', 'Sports', 'Naxat Soft', '2', 'Golf simulation', 'Whimsical golf simulation featuring robots.', 'Win the 16-bit robot golf tournament.', 'Experience Super Naxat Open on the Super Famicom.', 'Features a quirky cast of mechanical characters. Blends traditional golf mechanics with specialized power-ups and vibrant, imaginative course designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nazo-puyo---lulu-no-lu-japan', 'SNES', 'Super Nazo Puyo - Lulu no Lu (Japan)', '1995', 'Puzzle', 'Compile', '2', 'Tile-based puzzle', 'Puzzle game based on the Puyo Puyo series.', 'Solve the challenging logic puzzles with Puyo blocks.', 'Play Super Nazo Puyo on the Super Famicom.', 'A "Mission Mode" focused Puyo game. Instead of endless clearing, players must solve specific scenarios within a limited number of moves or under certain conditions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nazo-puyo---rulue-no-roux', 'SNES', 'Super Nazo Puyo - Rulue no Roux', '1995', 'Puzzle', 'Compile', '2', 'Tile-based puzzle', 'Puyo-based logic and puzzle adventure.', 'Clear the mission boards to help Rulue.', 'Experience Super Nazo Puyo: Rulue no Roux on SNES.', 'Features a charming story mode centered on Rulue. Combines classic 16-bit Puyo matching with brain-teasing puzzles that require deep knowledge of chain reactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nazo-puyo-tsuu---lulu-no-tetsuwan-hanjouki-japan', 'SNES', 'Super Nazo Puyo Tsuu - Lulu no Tetsuwan Hanjouki (Japan)', '1996', 'Puzzle', 'Compile', '2', 'Tile-based puzzle', 'Enhanced mission-based puzzle sequel.', 'Master the technical Puyo puzzles in this 16-bit sequel.', 'Play Super Nazo Puyo Tsuu on the Super Famicom.', 'Based on the Puyo Puyo 2 engine. Features refined physics, "offsetting" mechanics for mission clears, and a significantly larger variety of logic challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nichibutsu-mahjong-japan', 'SNES', 'Super Nichibutsu Mahjong (Japan)', '1993', 'Mahjong', 'Nichibutsu', '2', 'Mahjong simulation', 'Traditional Mahjong simulation with diverse AI.', 'Win the 16-bit Mahjong circuit.', 'Experience Super Nichibutsu Mahjong on Super Famicom.', 'A classic 16-bit simulation of the four-player game. Features clean visuals and a helpful interface for tracking discards and potential winning hands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nichibutsu-mahjong-2---zenkoku-seiha-hen-japan', 'SNES', 'Super Nichibutsu Mahjong 2 - Zenkoku Seiha Hen (Japan)', '1994', 'Mahjong', 'Nichibutsu', '2', 'Mahjong simulation', 'Mahjong simulation with a travel theme.', 'Defeat opponents across Japan to become the national champ.', 'Play Super Nichibutsu Mahjong 2 on Super Famicom.', 'Features a story mode where the player travels to different regions of Japan, each with unique AI styles and specialized 16-bit Mahjong rules.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nichibutsu-mahjong-3---yoshimoto-gekijou-hen-japan', 'SNES', 'Super Nichibutsu Mahjong 3 - Yoshimoto Gekijou Hen (Japan)', '1995', 'Mahjong', 'Nichibutsu', '2', 'Mahjong simulation', 'Comedy-themed Mahjong simulation.', 'Play Mahjong against famous Yoshimoto Kogyo comedians.', 'Experience Super Nichibutsu Mahjong 3 on SNES.', 'A unique 16-bit crossover. Features digitized voices and caricatures of real Japanese comedians, adding a layer of humor to the traditional strategic gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nichibutsu-mahjong-4---kisokenkyuu-hen-japan', 'SNES', 'Super Nichibutsu Mahjong 4 - Kisokenkyuu Hen (Japan)', '1996', 'Mahjong', 'Nichibutsu', '2', 'Mahjong simulation', 'Technical Mahjong study and simulation tool.', 'Master the fundamentals of Mahjong in 16-bit.', 'Play Super Nichibutsu Mahjong 4 on Super Famicom.', 'Focuses on the "Basic Research" of the game. Includes specialized tutorials and a deep analysis of hand efficiency, perfect for improving your 16-bit tactical play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nikoniko-kart', 'SNES', 'Super NikoNiko Kart', '2019', 'Racing', 'Fan Developer', '4', 'Top-down kart racing', 'Fan-made Mario Kart modification.', 'Race in a "NikoNiko" themed 16-bit world.', 'Try Super NikoNiko Kart on the Super Nintendo.', 'A creative 16-bit romhack of Super Mario Kart. Features custom track textures, modified palettes, and character swaps inspired by Japanese internet culture.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ninja-boy-usa', 'SNES', 'Super Ninja Boy (USA)', '1992', 'Action-Platformer', 'Culture Brain', '2', '2D side-scrolling', 'Action-RPG with side-scrolling combat.', 'Save Chinaland from the invaders in 16-bit.', 'Play the classic Super Ninja Boy on the SNES.', 'A charming hybrid of top-down RPG exploration and real-time side-scrolling action. Level up your ninjas and defeat massive bosses in this unique 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ninja-kun-japan', 'SNES', 'Super Ninja-kun (Japan)', '1992', 'Action-Platformer', 'Culture Brain', '2', '2D side-scrolling', 'Traditional 2D action-platformer.', 'Defeat the mechanical shogun in this ninja classic.', 'Experience Super Ninja-kun on the Super Famicom.', 'Features vibrant sprites and fast-paced platforming. Use shurikens and specialized ninja tools to navigate levels filled with folklore-inspired enemies and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nobunaga-no-yabou---bushou-fuuunroku-japan', 'SNES', 'Super Nobunaga no Yabou - Bushou Fuuunroku (Japan)', '1995', 'Strategy', 'Koei', '1', 'Turn-based grand strategy', 'Grand strategy and conquest in feudal Japan.', 'Unify the warring states as a legendary Daimyo.', 'Play Super Nobunaga no Yabou on the Super Famicom.', 'The 16-bit entry of "Nobunaga''s Ambition". Manage taxes, agriculture, and military forces in a deep, turn-based historical simulation of the Sengoku era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nobunaga-no-yabou---bushou-fuuunroku-japan-rev-a', 'SNES', 'Super Nobunaga no Yabou - Bushou Fuuunroku (Japan) (Rev A)', '1995', 'Strategy', 'Koei', '1', 'Turn-based grand strategy', 'Grand strategy (Updated Revision).', 'Conquer Japan in this refined 16-bit strategy classic.', 'Play Nobunaga no Yabou (Rev A) on the Super Famicom.', 'The updated 16-bit version featuring minor AI improvements and bug fixes for the troop deployment menus, providing a more stable path to unification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nobunaga-no-yabou---zenkoku-ban-japan', 'SNES', 'Super Nobunaga no Yabou - Zenkoku Ban (Japan)', '1993', 'Strategy', 'Koei', '1', 'Turn-based grand strategy', 'Historical strategy simulation (National Edition).', 'Master the art of 16-bit war across all of Japan.', 'Experience Nobunaga no Yabou: Zenkoku Ban on SNES.', 'A massive strategic undertaking. Features the entire map of Japan with dozens of rival factions to conquer through diplomacy, trade, or brute military force.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-nova-usa', 'SNES', 'Super Nova (USA)', '1992', 'Shooter', 'Hudson Soft', '2', 'Top-down shooter', 'Side-scrolling shoot ''em up (USA release).', 'Protect the galaxy in this technical 16-bit shooter.', 'Play the intense Super Nova on the Super Nintendo.', 'The sequel to Darius Force. Features branching paths, massive aquatic-themed bosses, and a customizable weapon system that rewards strategic power-up management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-off-road---the-baja-usa', 'SNES', 'Super Off Road - The Baja (USA)', '1991', 'Racing', 'Leland Interactive Media', '2', 'Top-down off-road racing', 'Off-road racing with Mode 7 terrain.', 'Conquer the Baja desert in your custom 4x4.', 'Experience Super Off Road: The Baja on the SNES.', 'Uses advanced 16-bit sprite scaling and rotation to simulate a first-person-style off-road race. Manage vehicle damage while jumping dunes at high speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-off-road---the-baja-usa-beta', 'SNES', 'Super Off Road - The Baja (USA) (Beta)', '1991', 'Racing', 'Leland Interactive Media', '2', 'Top-down off-road racing', 'Off-road racing (Pre-release build).', 'Test the early terrain physics and vehicle scaling.', 'Check out the Super Off Road: The Baja Beta on SNES.', 'A rare 16-bit development slice. Shows the initial implementation of the engine''s "3D" perspective and the tuning of the suspension physics for the trucks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-off-road-europe', 'SNES', 'Super Off Road (Europe)', '1991', 'Racing', 'Leland Interactive Media', '2', 'Top-down off-road racing', 'Top-down arena-style off-road racing.', 'Win the 16-bit championship and upgrade your truck.', 'Play the classic Super Off Road on the Super Nintendo.', 'The legendary Ivan "Ironman" Stewart''s racing game. Use nitrous boosts to overtake rivals and collect money on the track to upgrade your acceleration and tires.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-off-road-japan', 'SNES', 'Super Off Road (Japan)', '1991', 'Racing', 'Leland Interactive Media', '2', 'Top-down off-road racing', 'Arena-style off-road racing (Japanese release).', 'Master the 16-bit circuit in the official Japanese version.', 'Experience Super Off Road on the Super Famicom.', 'Features the same addictive loop of racing and upgrading. A high-energy 16-bit sports title that rewards quick reflexes and smart nitro management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-off-road-usa', 'SNES', 'Super Off Road (USA)', '1991', 'Racing', 'Leland Interactive Media', '2', 'Top-down off-road racing', 'Arena-style off-road racing (USA release).', 'Crush the competition in this 16-bit arcade port.', 'Play Super Off Road for the Super Nintendo.', 'Compete against AI or friends in muddy tracks. A timeless 16-bit racer that focuses on tight turns, explosive speed, and car customization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-okumanchouja-game-japan', 'SNES', 'Super Okumanchouja Game (Japan)', '1995', 'Board Game', 'Enix', '1', 'Turn-based board game', 'Board game with a "millionaire" theme.', 'Become the richest player through property and stock.', 'Experience Super Okumanchouja Game on SNES.', 'A high-stakes 16-bit board game. Navigate the board to acquire wealth, manage luck-based events, and bankrupt your opponents to claim the ultimate fortune.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-oozumou---nessen-daiichiban-japan', 'SNES', 'Super Oozumou - Nessen Daiichiban (Japan)', '1994', 'Sports', 'Taito', '2', 'Sumo wrestling', 'Professional Sumo wrestling simulation.', 'Rise to the rank of Yokozuna in 16-bit.', 'Play Super Oozumou on the Super Famicom.', 'A respectful and technical 16-bit sim. Master the timing of slaps, throws, and pushes to force your opponent out of the ring in authentic Sumo matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pachi-slot-mahjong-japan', 'SNES', 'Super Pachi-Slot Mahjong (Japan)', '1995', 'Gambling', 'Nichibutsu', '2', 'Pachislot simulation', 'Mahjong simulation with Pachi-Slot elements.', 'Win big by combining Mahjong skill and slot luck.', 'Play Super Pachi-Slot Mahjong on the Super Famicom.', 'A unique 16-bit hybrid. Features traditional Mahjong gameplay paired with slot machine mini-games that provide power-ups and score multipliers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pachinko-japan', 'SNES', 'Super Pachinko (Japan)', '1994', 'Gambling', 'Banpresto', '2', 'Pachinko simulation', 'Traditional Pachinko simulation.', 'Master the pins and collect the silver balls in 16-bit.', 'Experience Super Pachinko on the Super Famicom.', 'A detailed recreation of the Japanese gambling halls. Features multiple 16-bit machines with varying physics and bonus modes for a relaxing digital experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pachinko-taisen-japan', 'SNES', 'Super Pachinko Taisen (Japan)', '1995', 'Gambling', 'Compile', '2', 'Pachinko simulation', 'Action-based Pachinko hybrid game.', 'Complete the 16-bit Pachinko challenges and missions.', 'Play Super Pachinko Taisen on the Super Famicom.', 'Adds a "Battle" twist to the standard Pachinko formula. Use your ball-launching skills to defeat opponents and trigger specialized 16-bit cinematic events.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pang-europe', 'SNES', 'Super Pang (Europe)', '1992', 'Arcade', 'Action', 'System 3', '2', 'Balloon-popping puzzle action (Pang).', 'Clear the screens of bouncing bubbles across the world.', 'Play the addictive Super Pang on the Super Nintendo.', 'A pixel-perfect 16-bit arcade port. Use your harpoon to split bubbles into smaller pieces until they disappear. Features a tense "Panic Mode" for expert players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pang-japan', 'SNES', 'Super Pang (Japan)', '1992', 'Arcade', 'Action', 'System 3', '2', 'Balloon-popping puzzle action (Pang).', 'Clear the screens of bouncing bubbles in the Japanese version.', 'Play Super Pang on the Super Famicom.', 'The authentic 16-bit Japanese arcade port. Features the classic "Tour" and "Panic" modes, with precise harpoon physics and challenging bubble-splitting puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-parigo-kart', 'SNES', 'Super Parigo Kart', '2018', 'Racing', 'Fan Developer', '4', 'Top-down kart racing', 'Fan-made Mario Kart modification (Parigo).', 'Race through custom Parisian-themed 16-bit tracks.', 'Try Super Parigo Kart on the SNES.', 'A creative 16-bit romhack of Super Mario Kart. Features redesigned tracks with unique obstacles and a fresh color palette inspired by the Parigo fan community.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-parigo-kart-2', 'SNES', 'Super Parigo Kart 2', '2019', 'Racing', 'Fan Developer', '4', 'Top-down kart racing', 'Enhanced Mario Kart modification sequel.', 'Master even more complex custom tracks in the Parigo sequel.', 'Play Super Parigo Kart 2 on the SNES.', 'An expanded 16-bit racing mod. Includes more technical track designs, custom item probability, and refined Mode 7 backgrounds for a superior racing challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-peach-world-dx', 'SNES', 'Super Peach World DX', '2020', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Side-scrolling platformer starring Princess Peach.', 'Rescue Mario and the kingdom as a powerful Peach.', 'Experience Super Peach World DX on the SNES.', 'A high-quality 16-bit total conversion hack of Super Mario World. Play as Peach with unique float mechanics and explore entirely new, vibrant 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pinball---behind-the-mask-europe', 'SNES', 'Super Pinball - Behind the Mask (Europe)', '1994', 'Pinball', 'Kaze', '1', 'Virtual pinball', 'Realistic 3D-perspective pinball simulation.', 'Achieve the high score across three themed tables.', 'Play Super Pinball: Behind the Mask on SNES.', 'Features impressive 16-bit tilt and rotation effects. Play on the "Jolly Joker," "Blackbeard," and "Wizard" tables with realistic ball physics and hidden bonus modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pinball---behind-the-mask-japan', 'SNES', 'Super Pinball - Behind the Mask (Japan)', '1994', 'Pinball', 'Kaze', '1', 'Virtual pinball', '3D-perspective pinball (Japanese release).', 'Master the three 16-bit tables in the Japanese original.', 'Experience Super Pinball: Behind the Mask on SNES.', 'The Japanese 16-bit edition. Known for its high-quality sound effects and the use of the DSP-1 chip to handle complex ball physics and table scaling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pinball---behind-the-mask-japan-beta', 'SNES', 'Super Pinball - Behind the Mask (Japan) (Beta)', '1994', 'Pinball', 'Kaze', '1', 'Virtual pinball', '3D-perspective pinball (Pre-release build).', 'Test the early table physics and bumper reactions.', 'Check out Super Pinball Behind the Mask Beta on SNES.', 'A rare 16-bit development look. Witness the initial implementation of the table''s digital displays and the fine-tuning of the flipper response times.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pinball---behind-the-mask-usa', 'SNES', 'Super Pinball - Behind the Mask (USA)', '1994', 'Pinball', 'Kaze', '1', 'Virtual pinball', '3D-perspective pinball (USA release).', 'Master the 16-bit flippers in the official USA version.', 'Play Super Pinball: Behind the Mask on the SNES.', 'A solid 16-bit arcade-style pinball title. Includes multiple camera angles and challenging multi-ball sequences across three distinct, highly detailed themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pinball---behind-the-mask-usa-rev-a', 'SNES', 'Super Pinball - Behind the Mask (USA) (Rev A)', '1994', 'Pinball', 'Kaze', '1', 'Virtual pinball', '3D-perspective pinball (USA Revision).', 'Experience the refined pinball action in Rev A.', 'Play Super Pinball (Rev A) on the Super Nintendo.', 'The updated 16-bit retail version. Fixes minor graphical glitches in the "Wizard" table and optimizes the ball''s collision detection for a more accurate experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pinball-ii---the-amazing-odyssey-japan', 'SNES', 'Super Pinball II - The Amazing Odyssey (Japan)', '1995', 'Pinball', 'Kaze', '1', 'Virtual pinball', 'Advanced pinball simulation sequel.', 'Conquer the mythical odyssey tables in 16-bit.', 'Experience Super Pinball II on the Super Famicom.', 'Features much more complex table designs and improved physics. Navigate through mythological themes with fast-paced 16-bit action and more interactive table elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-play-action-football-usa', 'SNES', 'Super Play Action Football (USA)', '1991', 'Sports', 'TOSE', '2', 'American football', 'American Football simulation with isometric view.', 'Win the championship in this 16-bit gridiron sim.', 'Play Super Play Action Football on the SNES.', 'Includes college, high school, and pro teams. Features a unique isometric field perspective and a diverse playbook that emphasizes tactical 16-bit play-calling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-power-league-japan', 'SNES', 'Super Power League (Japan)', '1994', 'Sports', 'Hudson Soft', '2', 'Baseball simulation', 'Professional baseball simulation (Hudson Soft).', 'Lead your team to the pennant in 16-bit.', 'Play Super Power League on the Super Famicom.', 'Known for its fast-paced gameplay and fluid pitcher/batter duel mechanics. A mainstay of the 16-bit sports library in Japan with detailed stats and rosters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-power-league-2-japan', 'SNES', 'Super Power League 2 (Japan)', '1995', 'Sports', 'Hudson Soft', '2', 'Baseball simulation', 'Enhanced baseball simulation sequel.', 'Master the field in this refined 16-bit sports sequel.', 'Experience Super Power League 2 on the Super Famicom.', 'Features improved player sprites and more realistic stadium acoustics. A solid 16-bit baseball title that balances arcade accessibility with deep season management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-power-league-2-japan-rev-a', 'SNES', 'Super Power League 2 (Japan) (Rev A)', '1995', 'Sports', 'Hudson Soft', '2', 'Baseball simulation', 'Baseball simulation sequel (Updated Revision).', 'Win the series in the most stable version of the sequel.', 'Play Super Power League 2 (Rev A) on SNES.', 'The refined 16-bit Japanese release. Fixes minor roster bugs and optimizes the save system for long-term season play and statistical tracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-power-league-3-japan', 'SNES', 'Super Power League 3 (Japan)', '1996', 'Sports', 'Hudson Soft', '2', 'Baseball simulation', 'The third entry in the Power League series.', 'Achieve baseball glory in this expanded 16-bit sim.', 'Play Super Power League 3 on the Super Famicom.', 'Introduces more refined batting controls and specialized "super" plays. Features high-quality 16-bit graphics and a more cinematic presentation of the Japan Series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-power-league-4-japan', 'SNES', 'Super Power League 4 (Japan)', '1997', 'Sports', 'Hudson Soft', '2', 'Baseball simulation', 'The final SNES entry in the Power League series.', 'Conquer the professional league in the 16-bit finale.', 'Experience Super Power League 4 on Super Famicom.', 'The pinnacle of the series on 16-bit hardware. Includes the most comprehensive rosters, improved AI, and the most fluid animations in the entire franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-probotector---alien-rebels-europe', 'SNES', 'Super Probotector - Alien Rebels (Europe)', '1992', 'Run and Gun', 'Rare', '2', '2D side-scrolling shooter', 'Side-scrolling run and gun action (Contra III).', 'Defeat the alien invaders as the heroic Probotectors.', 'Play Super Probotector: Alien Rebels on the SNES.', 'The European version of Contra III. Replaces the human protagonists with cool robotic soldiers. Features intense 16-bit action, Mode 7 stages, and massive boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-professional-baseball-japan', 'SNES', 'Super Professional Baseball (Japan)', '1991', 'Sports', 'Jaleco', '2', 'Baseball simulation', 'Arcade-style baseball simulation (Jaleco).', 'Hit home runs in this professional 16-bit baseball sim.', 'Play Super Professional Baseball on Super Famicom.', 'Features a clean, accessible interface and fast-paced gameplay. A solid 16-bit sports title that focuses on the core mechanics of batting, pitching, and fielding.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-professional-baseball-ii-japan', 'SNES', 'Super Professional Baseball II (Japan)', '1992', 'Sports', 'Jaleco', '2', 'Baseball simulation', 'Enhanced arcade-style baseball sequel.', 'Win the championship in this polished 16-bit sequel.', 'Experience Super Professional Baseball II on SNES.', 'Features improved animations and more detailed player statistics. A faster and more responsive 16-bit baseball experience compared to the original installment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-punch-out!!-europe', 'SNES', 'Super Punch-Out!! (Europe)', '1994', 'Fighting', 'Nintendo R&D3', '2', 'Boxing', 'Rhythmic arcade boxing simulation.', 'Defeat the world circuit champions and claim the belt.', 'Play the legendary Super Punch-Out!! on the SNES.', 'A 16-bit masterpiece. Features massive, detailed opponents and a deep system of ducks, dodges, and "KO" punches. Master the patterns to become the ultimate champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-punch-out!!-japan-np', 'SNES', 'Super Punch-Out!! (Japan) (NP)', '1994', 'Fighting', 'Nintendo R&D3', '2', 'Boxing', 'Rhythmic arcade boxing (Nintendo Power).', 'Master the 16-bit ring in the official Japanese version.', 'Play Super Punch-Out!! on the Super Famicom.', 'Originally released in Japan via the Nintendo Power service. Features the same intense, high-speed boxing action and memorable cast of colorful international opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-punch-out!!-usa', 'SNES', 'Super Punch-Out!! (USA)', '1994', 'Fighting', 'Nintendo R&D3', '2', 'Boxing', 'Rhythmic arcade boxing (USA release).', 'Climb the ranks and defeat Nick Bruiser in 16-bit.', 'Experience Super Punch-Out!! for the SNES.', 'One of the most polished games on the system. Uses the SNES''s power to deliver large, expressive characters and incredibly tight, rewarding gameplay mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-putty-europe', 'SNES', 'Super Putty (Europe)', '1993', 'Platformer', 'System 3', '2', '2D side-scrolling', 'Squishy side-scrolling platformer.', 'Navigate through bizarre worlds as the elastic Putty.', 'Play the unique Super Putty on the Super Nintendo.', 'Features a creative protagonist who can stretch, squash, and absorb enemies. A 16-bit platformer that emphasizes environmental puzzle-solving and fluid character movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-putty-usa', 'SNES', 'Super Putty (USA)', '1993', 'Platformer', 'System 3', '2', '2D side-scrolling', 'Squishy side-scrolling platformer (USA release).', 'Rescue the captured Putties in this 16-bit adventure.', 'Experience Super Putty for the Super Nintendo.', 'Guide the blue protagonist through surreal levels. Use your unique shape-shifting abilities to bypass traps and navigate the imaginative 16-bit landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puyo-puyo-japan', 'SNES', 'Super Puyo Puyo (Japan)', '1993', 'Puzzle', 'Compile', '2', 'Falling-block puzzle', 'Falling-block puzzle game (Debut).', 'Chain together Puyos to defeat your opponents.', 'Play the original Super Puyo Puyo on the Super Famicom.', 'The 16-bit phenomenon that started the craze. Features a deep "chaining" system and a colorful cast of characters. Simple to learn, but incredibly difficult to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puyo-puyo-japan-rev-a', 'SNES', 'Super Puyo Puyo (Japan) (Rev A)', '1993', 'Puzzle', 'Compile', '2', 'Falling-block puzzle', 'Falling-block puzzle (Updated Revision A).', 'Master the chains in this refined 16-bit classic.', 'Play Super Puyo Puyo (Rev A) on the Super Famicom.', 'The updated 16-bit retail version. Fixes minor graphical glitches in the story mode and optimizes the AI''s response time during high-speed matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puyo-puyo-japan-rev-b', 'SNES', 'Super Puyo Puyo (Japan) (Rev B)', '1993', 'Puzzle', 'Compile', '2', 'Falling-block puzzle', 'Falling-block puzzle (Revision B).', 'Experience the most stable version of the Puyo debut.', 'Play Super Puyo Puyo (Rev B) on the Super Famicom.', 'The final 16-bit retail revision in Japan. Includes all previous bug fixes and ensures the most balanced competitive puzzle experience on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puyo-puyo-2-usa-europe-ja', 'SNES', 'Super Puyo Puyo 2 (USA, Europe) (Ja)', '1996', 'Puzzle', 'Compile', '2', 'Falling-block puzzle', 'Falling-block puzzle (International/Japanese mix).', 'Challenge the world in this 16-bit puzzle classic.', 'Experience Super Puyo Puyo 2 on the SNES.', 'The international release of the legendary sequel. Introduces the "offsetting" mechanic, allowing players to counter incoming garbage Puyos, revolutionizing competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puyo-puyo-tsuu-japan', 'SNES', 'Super Puyo Puyo Tsuu (Japan)', '1994', 'Puzzle', 'Compile', '2', 'Falling-block puzzle', 'Advanced falling-block puzzle sequel.', 'Become the Puyo master in the definitive 16-bit sequel.', 'Play Super Puyo Puyo Tsuu on the Super Famicom.', 'Widely considered the best in the series. Features a branching story path, a massive roster of opponents, and the most refined 16-bit competitive puzzle mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puyo-puyo-tsuu-japan-en-by-j2e-v11-~super-puyo-puyo-2', 'SNES', 'Super Puyo Puyo Tsuu (Japan) [En by J2e v1.1] (~Super Puyo Puyo 2)', '1994', 'Puzzle', 'Compile', '2', 'Falling-block puzzle', 'Advanced falling-block puzzle (English).', 'Enjoy the ultimate 16-bit Puyo sequel in English.', 'Play Super Puyo Puyo Tsuu in English on the SNES.', 'The J2e 16-bit fan translation. Fully translates the humorous character interactions and menus, making this competitive masterpiece accessible to Western fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puyo-puyo-tsuu-remix-japan', 'SNES', 'Super Puyo Puyo Tsuu Remix (Japan)', '1995', 'Puzzle', 'Compile', '2', 'Falling-block puzzle', 'Enhanced falling-block puzzle (Remix version).', 'Master the new modes in this 16-bit Puyo expansion.', 'Experience Super Puyo Puyo Tsuu Remix on SNES.', 'An updated version of the sequel. Features a new "Expert" mode and more 4-player options, offering the most comprehensive 16-bit Puyo Puyo package available.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-r-type-europe', 'SNES', 'Super R-Type (Europe)', '1991', 'Shooter', 'Irem', '2', 'Side-scrolling shooter', 'Horizontal-scrolling shoot ''em up (Shmup).', 'Defeat the Bydo Empire in this challenging 16-bit shooter.', 'Play the legendary Super R-Type on the SNES.', 'A launch-window classic. Features massive bosses, the iconic "Force" orb mechanic, and several new levels exclusive to this version of the legendary arcade franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-r-type-japan', 'SNES', 'Super R-Type (Japan)', '1991', 'Shooter', 'Irem', '2', 'Side-scrolling shooter', 'Horizontal-scrolling shoot ''em up (Japanese release).', 'Master the R-9 fighter in the original 16-bit version.', 'Experience Super R-Type on the Super Famicom.', 'Known for its intense difficulty and atmospheric soundtrack. Utilize the beam charging system to clear screens of biomechanical alien threats in this 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-r-type-usa', 'SNES', 'Super R-Type (USA)', '1991', 'Shooter', 'Irem', '2', 'Side-scrolling shooter', 'Horizontal-scrolling shoot ''em up (USA release).', 'Blast through the alien armada in this 16-bit shmup.', 'Play Super R-Type for the Super Nintendo.', 'Features impressive sprite scaling and diverse weaponry. Navigate through hazardous industrial landscapes and organic alien nests to save humanity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-rbi-baseball-usa', 'SNES', 'Super R.B.I. Baseball (USA)', '1989', 'Sports', 'Tengen', '2', 'Baseball simulation', 'Arcade-style baseball simulation.', 'Hit home runs and win the 16-bit world series.', 'Play Super R.B.I. Baseball on the Super Nintendo.', 'The 16-bit evolution of the classic franchise. Features real MLB players and statistics from the early 90s, with fast-paced gameplay and easy-to-learn controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-real-mahjong-piv-japan', 'SNES', 'Super Real Mahjong PIV (Japan)', '1994', 'Mahjong', 'Seta', '1', 'Mahjong simulation', 'Mahjong simulation with anime-style characters.', 'Win the mahjong tournament to unlock character scenes.', 'Experience Super Real Mahjong PIV on Super Famicom.', 'A polished 16-bit port of the popular arcade series. Features high-quality character art and a competitive AI that challenges even experienced mahjong players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-real-mahjong-pv-paradise---all-star-4-nin-uchi-japan', 'SNES', 'Super Real Mahjong PV Paradise - All-Star 4 Nin Uchi (Japan)', '1995', 'Mahjong', 'Seta', '1', 'Mahjong simulation', 'All-star mahjong simulation with a large roster.', 'Master the tiles against a variety of anime opponents.', 'Play Super Real Mahjong PV Paradise on SNES.', 'The ultimate 16-bit entry in the series. Features a four-player mode and an extensive collection of characters with unique personalities and playstyles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-reimu-world-return-to-hack', 'SNES', 'Super Reimu World Return To Hack', '2019', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made total conversion of Mario World (Touhou).', 'Navigate the Mushroom Kingdom as the shrine maiden Reimu.', 'Explore Super Reimu World Return To Hack on SNES.', 'A creative 16-bit crossover. Replaces Mario with Reimu Hakurei, featuring custom projectiles, unique flight mechanics, and entirely redesigned levels inspired by Touhou Project.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-ex-japan', 'SNES', 'Super Robot Taisen EX (Japan)', '1994', 'Strategy', 'Banpresto', '1', 'Tactical RPG', 'Turn-based tactical RPG with giant robots.', 'Command a crossover team of mechas to save the Earth.', 'Play Super Robot Taisen EX on the Super Famicom.', 'A deep 16-bit tactical experience. Features iconic robots from various anime series, with branching storylines and impressive combat animations for each unit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-gaiden---masou-kishin---the-lord-of-elemental-japan', 'SNES', 'Super Robot Taisen Gaiden - Masou Kishin - The Lord of Elemental (Japan)', '1996', 'Strategy', 'Banpresto', '1', 'Tactical RPG', 'Tactical RPG spin-off (Original Story).', 'Master the elemental mechas in this 16-bit epic.', 'Experience Super Robot Taisen Gaiden on SNES.', 'The first entry to feature the original "Lord of Elemental" storyline. Boasts some of the best 16-bit sprite work on the system and a sophisticated verticality mechanic in combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-royal-blood-japan', 'SNES', 'Super Royal Blood (Japan)', '1995', 'Strategy', 'Koei', '1', 'Turn-based strategy', 'Strategy and fantasy conquest simulation (Koei).', 'Unify the kingdom of Ishmeria through war and magic.', 'Play Super Royal Blood on the Super Famicom.', 'Known as "Gemfire" in the West. A unique 16-bit hybrid of grand strategy and fantasy, featuring magical advisors and monster units to turn the tide of battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-rugby-japan', 'SNES', 'Super Rugby (Japan)', '1994', 'Sports', 'Tonkin House', '2', 'Rugby simulation', 'Realistic rugby simulation (Japanese release).', 'Lead your national team to the 16-bit rugby cup.', 'Experience Super Rugby on the Super Famicom.', 'A rare 16-bit sports title focusing on the intensity of rugby. Features complex tactical formations, realistic set-pieces, and smooth player animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sanae-world', 'SNES', 'Super Sanae World', '2018', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made platformer starring Sanae Kochiya.', 'Explore a new 16-bit world as the miracle worker Sanae.', 'Play the unique Super Sanae World on the SNES.', 'A creative 16-bit ROM hack. Replaces the protagonist with the Touhou character Sanae, featuring custom palettes and redesigned levels that focus on precision platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sangokushi-japan', 'SNES', 'Super Sangokushi (Japan)', '1992', 'Strategy', 'Koei', '1', 'Turn-based strategy', 'Grand strategy set in the Three Kingdoms era.', 'Unify ancient China through diplomacy and warfare.', 'Play Super Sangokushi on the Super Famicom.', 'Koei''s legendary "Romance of the Three Kingdoms" in 16-bit. Manage hundreds of officers, local economies, and massive armies in a deep historical simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sangokushi-ii-japan', 'SNES', 'Super Sangokushi II (Japan)', '1994', 'Strategy', 'Koei', '1', 'Turn-based strategy', 'Grand strategy sequel (Three Kingdoms).', 'Conquer China in this refined 16-bit strategy sequel.', 'Experience Super Sangokushi II on the Super Famicom.', 'Features improved UI and deeper diplomatic options. A complex 16-bit sim that rewards long-term planning and clever manipulation of rival warlords.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sangokushi-ii-japan-rev-a', 'SNES', 'Super Sangokushi II (Japan) (Rev A)', '1994', 'Strategy', 'Koei', '1', 'Turn-based strategy', 'Grand strategy sequel (Updated Revision).', 'Experience the most stable version of Sangokushi II.', 'Play Super Sangokushi II (Rev A) on the SNES.', 'The refined 16-bit Japanese release. Fixes minor bugs in the officer management menus and optimizes the AI''s tactical decision-making during sieges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-scope-6-japan', 'SNES', 'Super Scope 6 (Japan)', '1992', 'Shooter', 'Nintendo R&D1', '1', 'Light gun shooter', 'Light-gun shooter mini-game collection.', 'Master the six games included for the Super Scope.', 'Experience Super Scope 6 on the Super Famicom.', 'The pack-in title for the 16-bit light-gun. Includes "Blast Risky" and "LazerBlazer," offering a variety of arcade-style shooting challenges using the infrared accessory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-scope-6-usa', 'SNES', 'Super Scope 6 (USA)', '1992', 'Shooter', 'Nintendo R&D1', '1', 'Light gun shooter', 'Light-gun shooter collection (USA release).', 'Blast targets with the iconic 16-bit bazooka.', 'Play Super Scope 6 for the Super Nintendo.', 'Showcases the accuracy of the Super Scope hardware. Includes games ranging from puzzle-based shooting to high-speed interceptor missions against alien ships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-shadow-of-the-beast-usa-proto', 'SNES', 'Super Shadow of the Beast (USA) (Proto)', '1991', 'Platformer', 'Psygnosis', '1', '2D cinematic platformer', 'Side-scrolling action-adventure (Unreleased Proto).', 'Navigate the dark fantasy world of the Beast.', 'Try the Super Shadow of the Beast Proto on SNES.', 'A rare 16-bit look at a cancelled project. Based on the Amiga classic, featuring atmospheric backgrounds, bizarre creatures, and a notably high difficulty level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-shanghai---dragons-eye-japan', 'SNES', 'Super Shanghai - Dragon''s Eye (Japan)', '1994', 'Puzzle', 'Hudson Soft', '2', 'Tile-matching puzzle', 'Traditional board game (Mahjong solitaire).', 'Clear the tile formations in this technical puzzle game.', 'Play Super Shanghai: Dragon''s Eye on Super Famicom.', 'A 16-bit update to the classic puzzle formula. Features multiple tile sets, various layout challenges, and a competitive mode for two players to race against the clock.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-shougi-japan', 'SNES', 'Super Shougi (Japan)', '1992', 'Board Game', 'Nintendo', '2', 'Shogi board game', 'Traditional Japanese board game (Shougi).', 'Defeat the AI in the ancient game of Japanese chess.', 'Experience Super Shougi on the Super Famicom.', 'A polished 16-bit simulation. Features multiple AI levels and helpful move-prediction tools to help players learn and master the complex strategies of Shougi.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-shougi-2-japan', 'SNES', 'Super Shougi 2 (Japan)', '1994', 'Board Game', 'Nintendo', '2', 'Shogi board game', 'Enhanced Shougi simulation sequel.', 'Master the board in this refined 16-bit Shougi sequel.', 'Play Super Shougi 2 on the Super Famicom.', 'Includes improved graphical interfaces and more diverse AI personalities. Offers a more cinematic presentation of the traditional 16-bit tactical matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-shougi-3---kitaihei-japan', 'SNES', 'Super Shougi 3 - Kitaihei (Japan)', '1995', 'Board Game', 'Nintendo', '2', 'Shogi board game', 'Advanced Shougi simulation with story mode.', 'Win the Shougi championship in this 16-bit finale.', 'Experience Super Shougi 3 on the Super Famicom.', 'Features the most advanced AI in the series. Includes a narrative mode that follows the life of a professional player rising through the ranks of the 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-simple-kart', 'SNES', 'Super Simple Kart', '2017', 'Racing', 'Fan Developer', '4', 'Top-down kart racing', 'Minimalist fan-made racing modification.', 'Race through simplified 16-bit kart circuits.', 'Try the creative Super Simple Kart on the SNES.', 'A 16-bit romhack of Mario Kart that strips back the visuals to focus on pure racing lines and mechanics. Features entirely new, minimalist track designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-simple-kart-2', 'SNES', 'Super Simple Kart 2', '2018', 'Racing', 'Fan Developer', '4', 'Top-down kart racing', 'Minimalist racing modification sequel.', 'Master the next set of simple tracks in 16-bit.', 'Play Super Simple Kart 2 on the Super Nintendo.', 'An expansion of the "simple" concept. Includes more technical layouts and custom item placements designed to test the player''s 16-bit drifting precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-simple-kart-3', 'SNES', 'Super Simple Kart 3', '2019', 'Racing', 'Fan Developer', '4', 'Top-down kart racing', 'Final minimalist racing modification entry.', 'Complete the 16-bit "Simple" racing legacy.', 'Experience Super Simple Kart 3 on the SNES.', 'The final entry in the minimalist hack trilogy. Features the most polished track layouts and a balanced difficulty curve for veteran 16-bit racers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-slam-dunk-usa', 'SNES', 'Super Slam Dunk (USA)', '1994', 'Sports', 'Virgin Interactive', '2', 'Basketball', 'Arcade-style basketball simulation.', 'Win the championship with high-flying 16-bit dunks.', 'Play Super Slam Dunk on the Super Nintendo.', 'Features an emphasis on spectacular moves and fast-paced action. Includes 16-bit rosters of pro-style teams and an energetic soundtrack to match the court intensity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-slapshot-japan', 'SNES', 'Super Slapshot (Japan)', '1993', 'Sports', 'Taito', '2', 'Ice hockey', 'Arcade-style ice hockey simulation.', 'Score the winning goal in this fast-paced hockey sim.', 'Play Super Slapshot on the Super Famicom.', 'A high-energy 16-bit sports title. Features smooth skating, hard-hitting checks, and a variety of international teams for competitive arcade-style hockey matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-slapshot-usa', 'SNES', 'Super Slapshot (USA)', '1993', 'Sports', 'Taito', '2', 'Ice hockey', 'Arcade-style ice hockey (USA release).', 'Crush the competition on the 16-bit ice rink.', 'Experience Super Slapshot for the Super Nintendo.', 'Master the slap-shot mechanics and defensive positioning. A fun 16-bit sports game that prioritizes action and goal-scoring over strict simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-tv-europe', 'SNES', 'Super Smash T.V. (Europe)', '1992', 'Shooter', 'Eugene Jarvis', '2', 'Top-down arcade shooter', 'Top-down twin-stick style shooter.', 'Survive the lethal game show and win big prizes.', 'Play the intense Super Smash T.V. on the SNES.', 'A pixel-perfect 16-bit arcade port. Face waves of enemies in a series of deadly rooms. Features "Good luck! You''ll need it!" and incredible 16-bit carnage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-tv-usa', 'SNES', 'Super Smash T.V. (USA)', '1992', 'Shooter', 'Eugene Jarvis', '2', 'Top-down arcade shooter', 'Top-down twin-stick style shooter (USA).', 'Survive the futuristic game show in 16-bit.', 'Play Super Smash T.V. on the Super Nintendo.', 'A frantic 16-bit arcade port. Face endless waves of enemies and massive bosses to win cash, toasters, and your life in this high-octane 16-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-snakey-japan', 'SNES', 'Super Snakey (Japan)', '1994', 'Puzzle', 'Namco', '2', 'Arcade puzzle', 'Unique hybrid of Snake and puzzle-matching.', 'Grow your snake and clear the 16-bit board.', 'Experience Super Snakey on the Super Famicom.', 'A colorful 16-bit puzzler. Navigate your snake to collect matching orbs, requiring quick reflexes and spatial planning to avoid crashing as your length increases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-soccer-europe', 'SNES', 'Super Soccer (Europe)', '1991', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Forward-perspective soccer simulation (Europe).', 'Win the 16-bit World Cup in the European edition.', 'Play Super Soccer for the Super Nintendo.', 'Features the iconic vertical "behind-the-player" camera. Master the 16-bit pitch with smooth scaling and a hidden final match against a secret team.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-soccer-usa', 'SNES', 'Super Soccer (USA)', '1991', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Forward-perspective soccer simulation (USA).', 'Lead your national team to 16-bit glory.', 'Experience Super Soccer on the Super Nintendo.', 'The North American release of the Mode 7 classic. Includes diverse national teams and an accessible but deep 16-bit arcade-style football experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-soccer-champ-usa', 'SNES', 'Super Soccer Champ (USA)', '1995', 'Sports', 'Human Entertainment', '2', 'Soccer', 'Side-scrolling soccer action and strategy.', 'Score the winning goal in this 16-bit soccer sim.', 'Play Super Soccer Champ on the Super Nintendo.', 'Known for its large player sprites and cinematic "close-up" shots during shots on goal. A fast-paced 16-bit sports title with a heavy emphasis on arcade fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-solitaire-europe-enfrdeesit', 'SNES', 'Super Solitaire (Europe) (En,Fr,De,Es,It)', '1994', 'Card Game', 'Microprose', '1', 'Solitaire card game', 'Collection of card games (5 languages).', 'Master the art of Solitaire in this 16-bit collection.', 'Play Super Solitaire on the Super Nintendo.', 'Features various versions of the classic card game, including Klondike and FreeCell, with a clean 16-bit interface and multilingual support.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-solitaire-usa-enfrdeesit', 'SNES', 'Super Solitaire (USA) (En,Fr,De,Es,It)', '1994', 'Card Game', 'Microprose', '1', 'Solitaire card game', 'Collection of card games (USA release).', 'Relax with multiple 16-bit Solitaire variants.', 'Experience Super Solitaire on the SNES.', 'Offers a variety of card backs and backgrounds. A perfect 16-bit digital translation of the world''s most popular solo card games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sonic-world-co-op-v50', 'SNES', 'Super Sonic World Co-op V5.0', '2020', 'Platformer', 'Fan Developer', '2', '2D cooperative platformer', 'Cooperative platformer (Sonic crossover).', 'Race through the Mushroom Kingdom as Sonic in co-op.', 'Try Super Sonic World Co-op V5.0 on SNES.', 'A technical 16-bit fan hack. Replaces Mario with Sonic and allows two players to run at high speed simultaneously through redesigned 16-bit levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-soukoban-japan', 'SNES', 'Super Soukoban (Japan)', '1991', 'Puzzle', 'Thinking Rabbit', '1', 'Sokoban-style puzzle', 'Traditional warehouse-style logic puzzles.', 'Push the crates to their target spots to clear levels.', 'Experience Super Soukoban on the Super Famicom.', 'The definitive 16-bit version of the classic logic game. Features hundreds of brain-teasing levels and a polished interface for fans of tactical puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-special-world-v01', 'SNES', 'Super Special World (V01)', '2018', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made total conversion of Mario World.', 'Explore a "Special" take on the 16-bit Mushroom Kingdom.', 'Try the Super Special World V01 hack on SNES.', 'A creative 16-bit romhack featuring highly technical level design and unique custom assets, designed for veterans of the original Mario World engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-spongebob-kart', 'SNES', 'Super SpongeBob Kart', '2021', 'Racing', 'Fan Developer', '4', 'Top-down kart racing', 'SpongeBob-themed Mario Kart modification.', 'Race as SpongeBob and friends in 16-bit Bikini Bottom.', 'Play Super SpongeBob Kart on the Super Nintendo.', 'A fun 16-bit romhack of Mario Kart. Replaces the roster with SpongeBob characters and redesigns the tracks with underwater aesthetics and custom items.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-stadium-japan', 'SNES', 'Super Stadium (Japan)', '1991', 'Sports', 'Namco', '2', 'Baseball simulation', 'Arcade-style baseball simulation (Japan).', 'Win the pennant in this high-energy 16-bit baseball sim.', 'Experience Super Stadium on the Super Famicom.', 'Developed by Seta. Features a dynamic camera system and smooth 16-bit animations, capturing the excitement of Japanese professional baseball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---jedi-no-fukushuu-japan', 'SNES', 'Super Star Wars - Jedi no Fukushuu (Japan)', '1993', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode VI (Japan).', 'Defeat the Emperor and bring balance to the Force.', 'Play Super Star Wars: Jedi no Fukushuu on SNES.', 'The Japanese release of Return of the Jedi. Features intense 16-bit platforming, lightsaber combat, and incredible Mode 7 Speeder Bike sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---return-of-the-jedi-europe', 'SNES', 'Super Star Wars - Return of the Jedi (Europe)', '1994', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode VI (Europe).', 'Rescue Han Solo and destroy the Death Star in 16-bit.', 'Experience Return of the Jedi on the Super Nintendo.', 'The final chapter of the 16-bit trilogy. Play as Luke, Han, Leia, or Chewbacca across iconic locations from the film with cinematic 16-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---return-of-the-jedi-europe-rev-a', 'SNES', 'Super Star Wars - Return of the Jedi (Europe) (Rev A)', '1994', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode VI (Europe Rev A).', 'Master the Force in the refined European final chapter.', 'Play Return of the Jedi (Rev A) on the SNES.', 'The updated 16-bit European release. Fixes minor sprite glitches during the Ewok Village levels and optimizes the final Death Star escape sequence.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---return-of-the-jedi-usa', 'SNES', 'Super Star Wars - Return of the Jedi (USA)', '1994', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode VI (USA).', 'Overthrow the Galactic Empire in this 16-bit epic.', 'Play Super Star Wars: Return of the Jedi on SNES.', 'A technical powerhouse. Combines run-and-gun action with Mode 7 space combat and a soaring 16-bit rendition of the John Williams soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---return-of-the-jedi-usa-rev-a', 'SNES', 'Super Star Wars - Return of the Jedi (USA) (Rev A)', '1994', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode VI (USA Rev A).', 'Achieve victory in the refined 16-bit Jedi finale.', 'Play Return of the Jedi (Rev A) on the SNES.', 'The optimized 16-bit USA version. Includes minor balance tweaks to the boss health and fixes rare audio desync issues during the cinematic cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---teikoku-no-gyakushuu-japan', 'SNES', 'Super Star Wars - Teikoku no Gyakushuu (Japan)', '1992', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode V (Japan).', 'Survive the battle of Hoth in the Japanese edition.', 'Play Super Star Wars: Teikoku no Gyakushuu on SNES.', 'The 16-bit adaptation of Empire Strikes Back. Known for its high difficulty and incredible use of Mode 7 to simulate the 3D battle against AT-ATs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---the-empire-strikes-back-europe', 'SNES', 'Super Star Wars - The Empire Strikes Back (Europe)', '1993', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode V (Europe).', 'Face Darth Vader in this atmospheric 16-bit adventure.', 'Experience Empire Strikes Back on the Super Nintendo.', 'Considered the most challenging entry in the 16-bit trilogy. Features a deep Jedi power system and massive, detailed levels inspired by the film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---the-empire-strikes-back-europe-beta', 'SNES', 'Super Star Wars - The Empire Strikes Back (Europe) (Beta)', '1993', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode V (Europe Beta).', 'Test the early Jedi powers and Hoth levels.', 'Check out the Empire Strikes Back Beta on the SNES.', 'A rare 16-bit development slice. Witness the initial tuning of the lightsaber physics and early layout designs for the Dagobah swamp stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---the-empire-strikes-back-usa', 'SNES', 'Super Star Wars - The Empire Strikes Back (USA)', '1993', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode V (USA).', 'Escape the ice planet and train with Yoda in 16-bit.', 'Play Super Star Wars: Empire Strikes Back on SNES.', 'A 16-bit action classic. Introduces force powers and complex multi-phase boss fights, pushing the SNES hardware to its limit with cinematic effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars---the-empire-strikes-back-usa-rev-a', 'SNES', 'Super Star Wars - The Empire Strikes Back (USA) (Rev A)', '1993', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode V (USA Rev A).', 'Conquer the galaxy in the refined Empire sequel.', 'Play Empire Strikes Back (Rev A) on the SNES.', 'The updated 16-bit retail version. Fixes specific bugs in the AT-AT cockpit view and balances the force power recharge rates for a smoother experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars-europe', 'SNES', 'Super Star Wars (Europe)', '1992', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode IV (Europe).', 'Start your journey from Tatooine to the Death Star.', 'Experience the original Super Star Wars on the SNES.', 'The game that redefined licensed titles. Features intense 16-bit run-and-gun gameplay and revolutionary Mode 7 Landsteder sequences across the desert.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars-europe-rev-a', 'SNES', 'Super Star Wars (Europe) (Rev A)', '1992', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode IV (Europe Rev A).', 'Experience the refined 16-bit Star Wars debut.', 'Play Super Star Wars (Rev A) on the Super Nintendo.', 'The updated 16-bit European version. Optimizes the frame rate during the chaotic Cantina fight and fixes minor graphical errors on the sandcrawler stage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars-japan', 'SNES', 'Super Star Wars (Japan)', '1992', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode IV (Japan).', 'Experience the 16-bit Star Wars saga in Japan.', 'Play Super Star Wars on the Super Famicom.', 'The authentic Japanese release of the LucasArts hit. Delivers high-quality 16-bit action and a faithful recreation of the movie''s most iconic moments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars-usa', 'SNES', 'Super Star Wars (USA)', '1992', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode IV (USA).', 'Join the Rebellion in this 16-bit cinematic classic.', 'Play Super Star Wars on the Super Nintendo.', 'A landmark SNES title. Combines challenging platforming with diverse vehicle missions, all wrapped in high-fidelity 16-bit graphics and sound.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars-usa-beta', 'SNES', 'Super Star Wars (USA) (Beta)', '1992', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode IV (USA Beta).', 'Explore the early 16-bit Tatooine development.', 'Check out the Super Star Wars Beta on the SNES.', 'A fascinating look at the 16-bit design process. Features unfinished enemy placement and prototype sounds that differ from the final retail release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-wars-usa-rev-a', 'SNES', 'Super Star Wars (USA) (Rev A)', '1992', 'Action', 'Beam Software', '1', '2D action platformer', 'Action-platformer based on Episode IV (USA Rev A).', 'Master the 16-bit Force in the definitive debut.', 'Play Super Star Wars (Rev A) on the Super Nintendo.', 'The final polished 16-bit USA release. Includes all minor bug fixes and provides the most stable version of Luke Skywalker''s initial 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-street-fighter-ii---the-new-challengers-europe', 'SNES', 'Super Street Fighter II - The New Challengers (Europe)', '1992', 'Action', 'Beam Software', '1', '2D action platformer', 'One-on-one fighting game (Capcom).', 'Defeat M. Bison and the four new challengers in 16-bit.', 'Play Super Street Fighter II on the SNES.', 'The ultimate 16-bit evolution of the series. Features 16 playable characters, including Cammy and Fei Long, with refined balance, new moves, and vibrant updated graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-street-fighter-ii---the-new-challengers-japan', 'SNES', 'Super Street Fighter II - The New Challengers (Japan)', '1993', 'Fighting', 'Capcom', '2', '2D competitive fighting', 'One-on-one fighting game (Japanese release).', 'Master the "New Challengers" in the official Japanese version.', 'Experience Super Street Fighter II on Super Famicom.', 'Features the iconic arcade gameplay with pixel-perfect 16-bit ports of the new stages. Includes a variety of speed settings and a robust tournament mode for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-street-fighter-ii---the-new-challengers-usa', 'SNES', 'Super Street Fighter II - The New Challengers (USA)', '1993', 'Fighting', 'Capcom', '2', '2D competitive fighting', 'One-on-one fighting game (USA release).', 'Become the world warrior champion in 16-bit.', 'Play Super Street Fighter II for the Super Nintendo.', 'Delivers the complete 16-bit arcade experience at home. Master the new combo system and the specialized movesets of all 16 legendary fighters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-strike-eagle-europe-enfrdeesit', 'SNES', 'Super Strike Eagle (Europe) (En,Fr,De,Es,It)', '1991', 'Shooter', 'MicroProse', '1', 'Isometric shooter', 'Flight combat simulation (Multilingual).', 'Complete high-stakes aerial missions across the globe.', 'Experience Super Strike Eagle on the Super Nintendo.', 'A cockpit-view flight sim featuring Mode 7 ground effects. Engage in dogfights and carrier landings in various international conflict zones with multilingual support.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-strike-eagle-usa', 'SNES', 'Super Strike Eagle (USA)', '1991', 'Shooter', 'MicroProse', '1', 'Isometric shooter', 'Flight combat simulation (USA release).', 'Command the F-15 Strike Eagle in 16-bit air combat.', 'Play Super Strike Eagle on the Super Nintendo.', 'Features a mix of strategic planning and intense cockpit action. Navigate through 16-bit skies to destroy enemy targets while managing fuel and missile payloads.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-strike-gunner-europe', 'SNES', 'Super Strike Gunner (Europe)', '1992', 'Shooter', 'AIM', '2', 'Vertical scrolling shooter', 'Vertical-scrolling shoot ''em up (Shmup).', 'Save Earth from a mechanized alien invasion in 16-bit.', 'Play the action-packed Super Strike Gunner on SNES.', 'Known for its tactical weapon-selection system. Choose from massive beam cannons or homing missiles to clear waves of 16-bit enemies and colossal bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-swiv-europe', 'SNES', 'Super SWIV (Europe)', '1992', 'Shooter', 'The Sales Curve', '2', 'Top-down shooter', 'Top-down vehicle-based shooter (European release).', 'Destroy the enemy base as a helicopter or tank.', 'Experience Super SWIV on the Super Nintendo.', 'The spiritual successor to Silkworm. Offers high-octane 16-bit action with destructible environments and a challenging cooperative mode for two players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-swiv-japan', 'SNES', 'Super SWIV (Japan)', '1992', 'Shooter', 'The Sales Curve', '2', 'Top-down shooter', 'Top-down vehicle-based shooter (Japanese release).', 'Blast through the enemy lines in the official Japanese version.', 'Play Super SWIV on the Super Famicom.', 'Known as "Firepower 2000" in the West. Features impressive 16-bit sprite scaling and a diverse range of power-ups for both the jeep and the helicopter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tekkyuu-fight!-japan', 'SNES', 'Super Tekkyuu Fight! (Japan)', '1995', 'Action', 'Technos Japan', '2', 'Physics-based arena fighting', 'Unique top-down action and puzzle game.', 'Defeat your opponents in a 16-bit arena with ball physics.', 'Experience Super Tekkyuu Fight! on the Super Famicom.', 'A rare 16-bit gem featuring a mace-swinging mechanic. Battle enemies in vibrant arenas where momentum and physics are key to winning the 16-bit combat rounds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tennis---world-circuit-japan', 'SNES', 'Super Tennis - World Circuit (Japan)', '1991', 'Sports', 'Tose', '2', 'Tennis simulation', 'Polished tennis simulation (World Circuit).', 'Win the Grand Slam in this definitive 16-bit tennis sim.', 'Play Super Tennis: World Circuit on Super Famicom.', 'A masterpiece of 16-bit sports. Features simple controls but deep mechanics, allowing for precise lobs, slices, and powerful serves across various court surfaces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tennis-europe', 'SNES', 'Super Tennis (Europe)', '1991', 'Sports', 'Tose', '2', 'Tennis simulation', 'Polished tennis simulation (European release).', 'Lead your player to the top of the 16-bit rankings.', 'Experience Super Tennis for the Super Nintendo.', 'A Nintendo-published classic. Features a memorable cast of 16-bit players and a perfectly balanced AI that provides a fair challenge in both singles and doubles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tennis-europe-rev-a', 'SNES', 'Super Tennis (Europe) (Rev A)', '1991', 'Sports', 'Tose', '2', 'Tennis simulation', 'Tennis simulation (Updated Revision).', 'Master the courts in this refined 16-bit tennis version.', 'Play Super Tennis (Rev A) on the Super Nintendo.', 'The updated 16-bit retail version. Fixes minor graphical glitches on the grass courts and optimizes the AI''s net-play logic for a more realistic experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tennis-usa', 'SNES', 'Super Tennis (USA)', '1991', 'Sports', 'Tose', '2', 'Tennis simulation', 'Polished tennis simulation (USA release).', 'Become the world number one in 16-bit.', 'Play the classic Super Tennis on the Super Nintendo.', 'Widely considered one of the best sports games on the system. Features smooth Mode 7 camera pans and a rewarding career mode that tracks your tournament progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tetris-2-+-bombliss---genteiban-japan', 'SNES', 'Super Tetris 2 + Bombliss - Genteiban (Japan)', '1994', 'Puzzle', 'BPS', '2', 'Falling-block puzzle', 'Falling-block puzzle (Special Limited Edition).', 'Clear the Tetris and Bombliss stages in this rare version.', 'Experience Super Tetris 2 + Bombliss (Genteiban) on SNES.', 'A specialized 16-bit edition featuring exclusive stage layouts and background art. Combines traditional Tetris with the explosive "Bombliss" mechanic for deep puzzle play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tetris-2-+-bombliss-japan', 'SNES', 'Super Tetris 2 + Bombliss (Japan)', '1994', 'Puzzle', 'BPS', '2', 'Falling-block puzzle', 'Enhanced falling-block puzzle hybrid.', 'Master the explosive Bombliss puzzles in 16-bit.', 'Play Super Tetris 2 + Bombliss on the Super Famicom.', 'A 16-bit powerhouse for puzzle fans. Includes multiple game modes, a robust vs. mode, and the ability to clear entire rows using strategically placed bombs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tetris-2-+-bombliss-japan-rev-a', 'SNES', 'Super Tetris 2 + Bombliss (Japan) (Rev A)', '1994', 'Puzzle', 'BPS', '2', 'Falling-block puzzle', 'Enhanced puzzle hybrid (Updated Revision).', 'Clear the blocks in this refined 16-bit puzzle edition.', 'Play Super Tetris 2 (Rev A) on the Super Famicom.', 'The optimized 16-bit Japanese release. Fixes minor sound bugs and improves the save system for the high-score boards across all 16-bit puzzle modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tetris-3-japan', 'SNES', 'Super Tetris 3 (Japan)', '1996', 'Puzzle', 'BPS', '2', 'Falling-block puzzle', 'The final entry in the 16-bit Tetris series.', 'Solve the "Magical" puzzles in the ultimate Tetris 3.', 'Experience Super Tetris 3 on the Super Famicom.', 'Features the "Tetris Spark" mode and updated 16-bit visuals. Includes a four-player mode (with Multitap) and a wide variety of gameplay variations beyond the classic formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-toad-planet-by-jacko-price-2020-05-16', 'SNES', 'Super Toad Planet by Jacko Price [2020-05-16]', '2020', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made platformer starring Toad.', 'Explore a surreal 16-bit planet as the heroic Toad.', 'Try Super Toad Planet on the Super Nintendo.', 'A creative 2020 16-bit romhack of Super Mario World. Features entirely new level designs, custom music, and a focus on Toad''s unique 16-bit platforming physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-troll-islands-europe', 'SNES', 'Super Troll Islands (Europe)', '1993', 'Platformer', 'Zap', '2', '2D side-scrolling', 'Side-scrolling platformer with vibrant aesthetics.', 'Save the Troll Islands from the mechanical invaders.', 'Play Super Troll Islands on the Super Nintendo.', 'Based on the popular toy line. Features high-contrast 16-bit colors and a unique "coloring" mechanic where you restore the world''s beauty by moving through it.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-troll-islands-japan', 'SNES', 'Super Troll Islands (Japan)', '1993', 'Platformer', 'Zap', '2', '2D side-scrolling', 'Side-scrolling platformer (Japanese release).', 'Restore the color to the Troll Islands in 16-bit.', 'Experience Super Troll Islands on the Super Famicom.', 'Features multiple playable trolls, each with unique 16-bit abilities. Navigate surreal landscapes and use the "color power" to defeat bosses and clean the environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-troll-islands-usa', 'SNES', 'Super Troll Islands (USA)', '1993', 'Platformer', 'Zap', '2', '2D side-scrolling', 'Side-scrolling platformer (USA release).', 'Protect the magical islands in this 16-bit adventure.', 'Play Super Troll Islands for the Super Nintendo.', 'A quirky 16-bit platformer that emphasizes exploration and environmental restoration. Features a catchy soundtrack and smooth scrolling through large, vertical levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-troll-islands-usa-beta', 'SNES', 'Super Troll Islands (USA) (Beta)', '1993', 'Platformer', 'Zap', '2', '2D side-scrolling', 'Side-scrolling platformer (Pre-release Beta).', 'Explore the early level designs of the Troll islands.', 'Check out the Super Troll Islands Beta on SNES.', 'A rare 16-bit development look. Shows the initial implementation of the "coloring" physics and early versions of the Troll character sprites and animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-trump-collection-japan', 'SNES', 'Super Trump Collection (Japan)', '1992', 'Card Game', 'Use', '1', 'Card collection', 'Collection of card games (Trump/Western cards).', 'Win the 16-bit tournament across various card games.', 'Experience Super Trump Collection on Super Famicom.', 'Features a variety of classic western card games like Poker and Blackjack. Includes 16-bit AI opponents and a clean, easy-to-use interface for a relaxing digital experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-trump-collection-2-japan', 'SNES', 'Super Trump Collection 2 (Japan)', '1993', 'Card Game', 'Use', '1', 'Card collection', 'Enhanced card game collection sequel.', 'Master even more card variants in this 16-bit sequel.', 'Play Super Trump Collection 2 on the Super Famicom.', 'Expands the 16-bit roster of card games. Features improved graphics and more sophisticated AI routines, offering a comprehensive digital casino experience for 16-bit fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tsume-shougi-1000-japan', 'SNES', 'Super Tsume Shougi 1000 (Japan)', '1995', 'Board Game', 'Hudson Soft', '1', 'Shogi puzzle', 'Large collection of Shougi logic puzzles.', 'Solve 1000 unique Shougi scenarios in 16-bit.', 'Experience Super Tsume Shougi 1000 on Super Famicom.', 'A massive puzzle database for fans of Japanese chess. Features 1000 "Tsume" (endgame) puzzles designed to test and improve your 16-bit tactical thinking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-turrican-europe', 'SNES', 'Super Turrican (Europe)', '1993', 'Action', 'Factor 5', '1', '2D run and gun', 'Run and gun action-platformer (Europe).', 'Save the planet from the Machine in 16-bit glory.', 'Play the legendary Super Turrican on the SNES.', 'A 16-bit technical masterpiece. Features a massive arsenal, a freeze beam, and incredible music. Known for its atmospheric levels and huge, detailed bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-turrican-japan', 'SNES', 'Super Turrican (Japan)', '1993', 'Action', 'Factor 5', '1', '2D run and gun', 'Action-platformer (Japanese release).', 'Master the Turrican suit in the official Japanese version.', 'Experience Super Turrican on the Super Famicom.', 'Delivers intense 16-bit action with smooth scrolling and impressive parallax backgrounds. A must-play for fans of run-and-gun titles like Contra and Metroid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-turrican-usa', 'SNES', 'Super Turrican (USA)', '1993', 'Action', 'Factor 5', '1', '2D run and gun', 'Action-platformer (USA release).', 'Blast through the mechanized legions in 16-bit.', 'Play Super Turrican for the Super Nintendo.', 'Explore large, non-linear levels and collect powerful weapon upgrades. This 16-bit classic pushes the SNES audio chip to its limits with an iconic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-turrican-2-europe', 'SNES', 'Super Turrican 2 (Europe)', '1995', 'Action', 'Factor 5', '1', '2D run and gun', 'High-octane run and gun sequel (Europe).', 'Engage in cinematic 16-bit combat in this epic sequel.', 'Experience Super Turrican 2 on the Super Nintendo.', 'Pushes the SNES to the absolute limit. Features Mode 7 vehicle segments, a grappling hook mechanic, and some of the most impressive 16-bit explosions ever seen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-turrican-2-usa', 'SNES', 'Super Turrican 2 (USA)', '1995', 'Action', 'Factor 5', '1', '2D run and gun', 'High-octane run and gun sequel (USA).', 'Defeat the Machine once and for all in 16-bit.', 'Play Super Turrican 2 for the Super Nintendo.', 'A cinematic 16-bit tour de force. Features fast-paced action, incredible sprite work, and specialized levels that feel like a big-budget action movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-turrican-2-usa-beta1', 'SNES', 'Super Turrican 2 (USA) (Beta1)', '1995', 'Action', 'Factor 5', '1', '2D run and gun', 'Run and gun sequel (Early Beta 1).', 'Test the initial implementation of the grappling hook.', 'Check out Super Turrican 2 (Beta 1) on the SNES.', 'A rare early 16-bit development build. Features unfinished levels and prototype boss designs, offering a glimpse into the creation of this 16-bit technical marvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-turrican-2-usa-beta2', 'SNES', 'Super Turrican 2 (USA) (Beta2)', '1995', 'Action', 'Factor 5', '1', '2D run and gun', 'Run and gun sequel (Advanced Beta 2).', 'Explore the refined 16-bit mechanics of the Turrican sequel.', 'Check out Super Turrican 2 (Beta 2) on the SNES.', 'A late-stage 16-bit development build. Includes more polished sound effects and near-final level layouts, showcasing the technical optimization of the Turrican engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ultra-baseball-japan', 'SNES', 'Super Ultra Baseball (Japan)', '1994', 'Sports', 'Culture Brain', '2', 'Baseball arcade', 'Arcade-style baseball with super powers.', 'Hit impossible home runs in this 16-bit sports sim.', 'Experience Super Ultra Baseball on the Super Famicom.', 'Known as "Super Baseball Simulator 1.000" in the West. Features traditional baseball gameplay with a twist: specialized "Super" moves for pitchers and batters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ultra-baseball-2-japan', 'SNES', 'Super Ultra Baseball 2 (Japan)', '1995', 'Sports', 'Culture Brain', '2', 'Baseball arcade', 'Enhanced super-powered baseball sequel.', 'Win the series in this expanded 16-bit sports sequel.', 'Play Super Ultra Baseball 2 on the Super Famicom.', 'Features more specialized powers and refined 16-bit graphics. A cult classic sports title that rewards both traditional skill and the strategic use of energy-draining super abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ultra-baseball-2-japan-en-by-vx-v10', 'SNES', 'Super Ultra Baseball 2 (Japan) [En by VX v1.0]', '1995', 'Sports', 'Culture Brain', '2', 'Baseball arcade', 'Super-powered baseball (English Translation).', 'Enjoy the crazy 16-bit baseball sequel in English.', 'Play Super Ultra Baseball 2 in English on the SNES.', 'The VX 16-bit fan translation. Makes the complex super-move menus and stat screens fully accessible, allowing Western fans to enjoy this unique and chaotic sports sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-uno-japan', 'SNES', 'Super Uno (Japan)', '1993', 'Card Game', 'Takara', '2', 'UNO-style card game', 'Digital version of the classic card game.', 'Empty your hand first to win the 16-bit match.', 'Play Super Uno on the Super Famicom.', 'The official 16-bit digital version of the world-famous card game. Features vibrant colors, various AI difficulty levels, and the classic "Uno!" shout in a charming digital format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-uno-japan-rev-a', 'SNES', 'Super Uno (Japan) (Rev A)', '1993', 'Card Game', 'Takara', '2', 'UNO-style card game', 'Card game simulation (Updated Revision).', 'Master the 16-bit card table in this refined version.', 'Play Super Uno (Rev A) on the Super Famicom.', 'The updated 16-bit retail release. Fixes minor AI logic bugs and optimizes the animation speed for a faster, more fluid card-playing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-valis---akaki-tsuki-no-otome-japan', 'SNES', 'Super Valis - Akaki Tsuki no Otome (Japan)', '1992', 'Action', 'Telenet Japan', '1', 'Action RPG', 'Action-platformer with a female protagonist.', 'Defeat the dark god and save the 16-bit world.', 'Experience Super Valis IV on the Super Famicom.', 'Known for its cinematic cutscenes and atmospheric music. Control Lena as she uses her magical sword to battle through detailed 16-bit gothic environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-valis-iv-usa', 'SNES', 'Super Valis IV (USA)', '1993', 'Action', 'Telenet Japan', '1', 'Action RPG', 'Action-platformer (USA release).', 'Master the sword of Valis in this 16-bit epic.', 'Play Super Valis IV for the Super Nintendo.', 'A refined 16-bit action title. Features challenging boss fights, multiple magic spells, and the high-quality storytelling the Valis series is famous for.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-variable-geo-japan', 'SNES', 'Super Variable Geo (Japan)', '1995', 'Fighting', 'TGL', '2', '2D fighting', 'All-female 2D fighting game.', 'Win the V.G. tournament in this technical 16-bit fighter.', 'Play Super Variable Geo on the Super Famicom.', 'Based on the popular franchise. Features a roster of high-school girls with unique martial arts styles, smooth 16-bit animations, and a deep combo system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-volley-ii-japan-rev-0a', 'SNES', 'Super Volley II (Japan) (Rev 0A)', '1994', 'Sports', 'Video System', '2', 'Volleyball simulation', 'Top-down volleyball simulation.', 'Lead your team to the 16-bit world championship.', 'Experience Super Volley II on the Super Famicom.', 'Features fast-paced 16-bit action with a focus on timing for spikes and blocks. Includes national teams and various specialized court surfaces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-wagan-land-japan', 'SNES', 'Super Wagan Land (Japan)', '1991', 'Action-Platformer', 'Hudson Soft', '1', '2D side-scrolling', 'Platformer with sound-wave combat.', 'Defeat enemies using your voice in this 16-bit classic.', 'Play Super Wagan Land on the Super Famicom.', 'A unique 16-bit platformer where you stun enemies with "shout" bubbles and engage in mini-game battles like Shiritori (word games) to defeat bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-wagan-land-2-japan', 'SNES', 'Super Wagan Land 2 (Japan)', '1992', 'Action-Platformer', 'Hudson Soft', '1', '2D side-scrolling', 'Enhanced sound-wave platformer sequel.', 'Master the new mini-games in this 16-bit sequel.', 'Play Super Wagan Land 2 on the Super Famicom.', 'Expands on the original with more complex level designs and even more creative boss battle mini-games, maintaining its status as a 16-bit family favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-wakana-land-v212-pure', 'SNES', 'Super Wakana Land (V2.1.2) (Pure)', '2019', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made total conversion of Mario World.', 'Explore Wakana''s world in this high-quality 16-bit hack.', 'Try Super Wakana Land (V2.1.2) on the SNES.', 'A polished 16-bit romhack featuring brand new levels, custom graphics, and a soundtrack inspired by the Touhou community. Offers a fresh challenge for SMW veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-widget-europe', 'SNES', 'Super Widget (Europe)', '1993', 'Action-Platformer', 'Atlus', '1', '2D side-scrolling', 'Side-scrolling action-platformer (Widget).', 'Protect the environment and save the Earth in 16-bit.', 'Play Super Widget on the Super Nintendo.', 'Based on the animated series. Transform into various forms (like a bird or a mole) to navigate 16-bit levels and defeat polluter villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-widget-usa', 'SNES', 'Super Widget (USA)', '1993', 'Action-Platformer', 'Atlus', '1', '2D side-scrolling', 'Action-platformer (USA release).', 'Use your alien powers to save the 16-bit ecosystem.', 'Experience Super Widget for the Super Nintendo.', 'A colorful 16-bit adventure. Master the transformation mechanics to solve environmental puzzles and defeat the forces of the evil Dr. Dante.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-wrestle-angels-japan', 'SNES', 'Super Wrestle Angels (Japan)', '1995', 'Wrestling', 'KSS', '2', 'Pro wrestling', 'Women''s wrestling simulation (Joshi Puro).', 'Manage and train your wrestling stars to the top.', 'Play Super Wrestle Angels on the Super Famicom.', 'A unique 16-bit hybrid of management sim and wrestling action. Recruit female wrestlers, manage their training, and compete in technical 16-bit matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-x-terminator-2-sasuke-japan-unl', 'SNES', 'Super X-Terminator 2 Sasuke (Japan) (Unl)', '1994', 'Shooter', 'Natsume', '1', 'Run and gun', 'Cheat device and game enhancer (Software).', 'Unlock hidden 16-bit features and cheats.', 'Explore Super X-Terminator 2 Sasuke on SNES.', 'A specialized 16-bit utility cartridge that allows players to enter cheat codes and modify game memory for various Super Famicom titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-yakyuudou-japan', 'SNES', 'Super Yakyuudou (Japan)', '1996', 'Sports', 'Banpresto', '2', 'Baseball simulation', 'Realistic 16-bit baseball simulation.', 'Win the Japanese series in this technical baseball sim.', 'Play Super Yakyuudou on the Super Famicom.', 'Focuses on the "Way of Baseball." Features detailed player stats and a realistic 16-bit presentation of pitching duels and tactical base running.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-zugan---hakotenjou-kara-no-shoutaijou-japan', 'SNES', 'Super Zugan - Hakotenjou Kara no Shoutaijou (Japan)', '1994', 'Mahjong', 'Jaleco', '1', 'Mahjong simulation', 'Mahjong board game based on the manga.', 'Win the high-stakes Mahjong match in 16-bit.', 'Play Super Zugan on the Super Famicom.', 'Based on the popular Mahjong manga. Features the series'' characters and humor, providing a faithful 16-bit recreation of the strategic tile game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-zugan-2---tsukanpo-fighter-japan', 'SNES', 'Super Zugan 2 - Tsukanpo Fighter (Japan)', '1995', 'Mahjong', 'Jaleco', '1', 'Mahjong simulation', 'Mahjong board game sequel.', 'Defeat your rivals in this humorous 16-bit Mahjong sequel.', 'Experience Super Zugan 2 on the Super Famicom.', 'Includes improved AI and more varied game modes. Features the same comedic tone as the original, with updated 16-bit sprites and faster gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('supercalifragilisticexpialidocious-world', 'SNES', 'Supercalifragilisticexpialidocious World', '2018', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made Mario World modification.', 'Survive the "Supercalifragilistic" 16-bit challenge.', 'Try the unique Supercalifragilistic World on SNES.', 'A creative 16-bit romhack featuring whimsical level design and a high difficulty curve, using the SMW engine to create an entirely new 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superstar-soccer-2---ronaldinho-97', 'SNES', 'Superstar Soccer 2 - Ronaldinho 97', '1997', 'Sports', 'Fan Developer', '2', 'Soccer', 'Fan-made soccer modification (ISSS Deluxe).', 'Play with Ronaldinho and the stars of 1997.', 'Experience Superstar Soccer 2 - Ronaldinho 97 on SNES.', 'A legendary 16-bit romhack of International Superstar Soccer. Updates the rosters and sprites to reflect the iconic 1997 era of world football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sutobasu-yarou-show-japan', 'SNES', 'Sutobasu Yarou Show (Japan)', '1994', 'Action', 'Sunsoft', '1', 'Action variety', 'Top-down arcade-style sports combat.', 'Win the brutal 16-bit "Stobasu" street basketball.', 'Play Sutobasu Yarou Show on the Super Famicom.', 'A chaotic 16-bit sports title featuring weapons, special moves, and high-energy basketball action in an urban arena setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sutte-hakkun-english', 'SNES', 'Sutte Hakkun (English)', '1999', 'Puzzle', 'Indies Zero', '1', 'Physics-based puzzle', 'Puzzle-platformer with liquid mechanics (English).', 'Inject life and colors into the 16-bit world.', 'Play Sutte Hakkun in English on the Super Nintendo.', 'The fan-translated 16-bit masterpiece. Control a transparent bird that sucks up colors and injects them into blocks to change their physics and solve complex puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sutte-hakkun-japan', 'SNES', 'Sutte Hakkun (Japan)', '1999', 'Puzzle', 'Indies Zero', '1', 'Physics-based puzzle', 'Unique puzzle-platformer (Japanese release).', 'Solve the ink-based logic puzzles in 16-bit.', 'Experience Sutte Hakkun on the Super Famicom.', 'Originally a Nintendo Power exclusive. A highly creative 16-bit puzzler that rewards experimentation with gravity and block properties.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('suzuka-8-hours-japan', 'SNES', 'Suzuka 8 Hours (Japan)', '1993', 'Racing', 'Namco', '2', 'Motorcycle racing', 'Motorcycle racing simulation (Suzuka).', 'Win the legendary 8-hour endurance race in 16-bit.', 'Play Suzuka 8 Hours on the Super Famicom.', 'A faithful 16-bit port of the Namco arcade hit. Features smooth Mode 7 scaling and challenging bike handling on the iconic Japanese circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('suzuka-8-hours-usa', 'SNES', 'Suzuka 8 Hours (USA)', '1993', 'Racing', 'Namco', '2', 'Motorcycle racing', 'Motorcycle racing simulation (USA release).', 'Master the 16-bit endurance circuit in the USA.', 'Experience Suzuka 8 Hours on the Super Nintendo.', 'Compete against a full field of racers. This 16-bit title emphasizes speed and cornering precision across the world-famous Suzuka track.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('suzuki-aguri-no-f-1-super-driving-japan', 'SNES', 'Suzuki Aguri no F-1 Super Driving (Japan)', '1992', 'Racing', 'Tecmo', '1', 'Formula One racing', 'Formula-style racing simulation.', 'Race with the legendary Aguri Suzuki in 16-bit.', 'Play Suzuki Aguri no F-1 Super Driving on SNES.', 'A technical 16-bit F-1 sim. Features customizable car settings and realistic racing physics, endorsed by the famous Japanese driver.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('swat-kats---the-radical-squadron-usa', 'SNES', 'SWAT Kats - The Radical Squadron (USA)', '1994', 'Action', 'Atlus', '1', '2D action platformer', 'Action-platformer based on the cartoon.', 'Fly the Turbokat and stop the villains of Mega Kat City.', 'Play SWAT Kats: The Radical Squadron on SNES.', 'Features high-flying jet levels and side-scrolling combat. Switch between T-Bone and Razor in this 16-bit action game inspired by the 90s classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sword-maniac-japan', 'SNES', 'Sword Maniac (Japan)', '1994', 'Action', 'Pandora Box', '1', 'Action RPG', 'Side-scrolling hack and slash action.', 'Slay your way through the 16-bit demonic castle.', 'Experience Sword Maniac on the Super Famicom.', 'Known as "X-Kaliber 2097" in the West. Features massive sprites, futuristic sword combat, and a gritty 16-bit cyberpunk atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sword-world-sfc-japan', 'SNES', 'Sword World SFC (Japan)', '1993', 'RPG', 'Group SNE', '1', 'Tabletop-style RPG', 'Turn-based tactical RPG (Sword World).', 'Lead your party of adventurers in this 16-bit tabletop sim.', 'Play Sword World SFC on the Super Famicom.', 'Based on the popular Japanese tabletop RPG. Features a deep character creation system and strategic 16-bit turn-based combat in a vast fantasy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sword-world-sfc-2---inishie-no-kyojin-densetsu-japan-rev-0a', 'SNES', 'Sword World SFC 2 - Inishie no Kyojin Densetsu (Japan) (Rev 0A)', '1994', 'RPG', 'Group SNE', '1', 'Tabletop-style RPG', 'Tactical RPG sequel (Ancient Giants).', 'Uncover the secrets of the ancients in this 16-bit sequel.', 'Experience Sword World SFC 2 on the Super Famicom.', 'Features a much larger map and refined combat mechanics. A complex 16-bit RPG that stays true to its pen-and-paper roots with deep statistics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sylvester-and-tweety-usa-proto', 'SNES', 'Sylvester and Tweety (USA) (Proto)', '1993', 'Platformer', 'Audiogenic', '1', '2D side-scrolling', 'Side-scrolling action (Unreleased Prototype).', 'Help Tweety outsmart Sylvester in this 16-bit proto.', 'Try the Sylvester and Tweety Prototype on the SNES.', 'A rare 16-bit look at a cancelled Looney Tunes project. Features classic cat-and-mouse platforming with large, colorful character sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syndicate-europe-enfrde', 'SNES', 'Syndicate (Europe) (En,Fr,De)', '1993', 'Strategy', 'Bullfrog Productions', '1', 'Real-time tactical strategy', 'Cyberpunk tactical simulation (European release).', 'Control a squad of cyborg agents and dominate the world.', 'Play the legendary Syndicate on the Super Nintendo.', 'A 16-bit technical feat. Lead your syndicate to global domination through tactical missions, research, and corporate warfare in a dark isometric future.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syndicate-europe-enfrde-beta', 'SNES', 'Syndicate (Europe) (En,Fr,De) (Beta)', '1993', 'Strategy', 'Bullfrog Productions', '1', 'Real-time tactical strategy', 'Cyberpunk tactical simulation (Beta Version).', 'Test the squad-based 16-bit tactical mechanics.', 'Check out the Syndicate Beta on the Super Nintendo.', 'A rare 16-bit development build. Features early versions of the isometric levels and the weapon research menus of the cyberpunk classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syndicate-japan', 'SNES', 'Syndicate (Japan)', '1993', 'Strategy', 'Bullfrog Productions', '1', 'Real-time tactical strategy', 'Cyberpunk tactical simulation (Japanese release).', 'Manage your 16-bit cyborg squad in Japan.', 'Experience Syndicate on the Super Famicom.', 'The authentic Japanese release of the Bullfrog classic. Offers the same deep strategic gameplay and tense isometric action for 16-bit strategy fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syndicate-usa', 'SNES', 'Syndicate (USA)', '1993', 'Strategy', 'Bullfrog Productions', '1', 'Real-time tactical strategy', 'Cyberpunk tactical simulation (USA release).', 'Expand your corporate empire in the 16-bit USA version.', 'Play Syndicate for the Super Nintendo.', 'Equip your agents with Persuadatrons and high-tech weaponry. A gritty and addictive 16-bit strategy title with a dark, mature theme.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syvalion-europe', 'SNES', 'Syvalion (Europe)', '1992', 'Shooter', 'Taito', '1', 'Experimental scrolling shooter', 'Side-scrolling dragon-combat shmup.', 'Destroy the gold-stealing mechs as a powerful dragon.', 'Play Syvalion on the Super Nintendo.', 'A unique 16-bit arcade port. Control a golden dragon with physics-based movement, breathing fire to clear levels and defeat robotic bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syvalion-europe-beta', 'SNES', 'Syvalion (Europe) (Beta)', '1992', 'Shooter', 'Taito', '1', 'Experimental scrolling shooter', 'Side-scrolling dragon combat (Beta Version).', 'Test the 16-bit dragon flight and fire physics.', 'Check out the Syvalion Beta on the Super Nintendo.', 'A rare 16-bit development slice. Witness the initial implementation of the dragon''s segmented body movement and the experimental level layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('syvalion-japan', 'SNES', 'Syvalion (Japan)', '1992', 'Shooter', 'Taito', '1', 'Experimental scrolling shooter', 'Dragon-combat shmup (Japanese release).', 'Master the 16-bit golden dragon in Japan.', 'Experience Syvalion on the Super Famicom.', 'Features the original Japanese difficulty and arcade-accurate scoring. A fast-paced 16-bit shmup that rewards precise dragon-tail control.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('t2---the-arcade-game-europe', 'SNES', 'T2 - The Arcade Game (Europe)', '1991', 'Shooter', 'Midway', '2', 'Arcade run and gun', 'Light-gun and controller action (Terminator 2).', 'Protect John Connor from the T-1000 in 16-bit.', 'Play T2: The Arcade Game on the Super Nintendo.', 'A faithful 16-bit port of the arcade hit. Blast through legions of terminators using the controller or the Super Scope in this high-intensity 16-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('t2---the-arcade-game-japan', 'SNES', 'T2 - The Arcade Game (Japan)', '1991', 'Shooter', 'Midway', '2', 'Arcade run and gun', 'Light-gun and controller action (T2).', 'Protect the resistance leader in the Japanese version.', 'Play T2: The Arcade Game on the Super Famicom.', 'A cinematic 16-bit shooter. Blast through Hunter-Killers and Endoskeletons. Use the Super Scope for an authentic arcade experience in this high-stakes 16-bit battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('t2---the-arcade-game-usa', 'SNES', 'T2 - The Arcade Game (USA)', '1991', 'Shooter', 'Midway', '2', 'Arcade run and gun', 'Light-gun and controller action (USA).', 'Stop the T-1000 and prevent Judgement Day in 16-bit.', 'Experience T2: The Arcade Game on the SNES.', 'The definitive 16-bit home port. Features digitized images from the movie and intense rail-shooter gameplay that tests your reflexes against the machine uprising.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('table-game-daishuugou!!-japan', 'SNES', 'Table Game Daishuugou!! (Japan)', '1995', 'Board Game', 'Natsume', '4', 'Multigame board compilation', 'Collection of classic board games.', 'Master multiple tabletop games in one 16-bit package.', 'Play Table Game Daishuugou!! on Super Famicom.', 'A comprehensive collection featuring Chess, Backgammon, and various traditional Japanese board games. Perfect for casual 16-bit sessions against the AI or a friend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactical-soccer-japan', 'SNES', 'Tactical Soccer (Japan)', '1993', 'Sports', 'Electronic Arts', '2', 'Soccer simulation', 'Top-down strategic soccer simulation.', 'Win the match through deep tactical management.', 'Experience Tactical Soccer on the Super Famicom.', 'A unique 16-bit sports title where you pause the action to issue specific movement and passing commands, blending strategy with traditional soccer gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactical-soccer-japan-beta', 'SNES', 'Tactical Soccer (Japan) (Beta)', '1993', 'Sports', 'Electronic Arts', '2', 'Soccer simulation', 'Strategic soccer simulation (Beta).', 'Test the early tactical command system.', 'Check out the Tactical Soccer Beta on the SNES.', 'A rare 16-bit development build. Features experimental UI layouts for the command menus and initial tuning for the player movement AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactics-ogre---let-us-cling-together-english-patched', 'SNES', 'Tactics Ogre - Let Us Cling Together (English Patched)', '1995', 'Strategy', 'Riverhillsoft', '1', 'Tactical RPG', 'Isometric tactical RPG (English Patched).', 'Lead your army through a branching political epic.', 'Play Tactics Ogre: Let Us Cling Together in English.', 'The 16-bit masterpiece that defined the genre. Features deep character customization, a mature story with moral choices, and a legendary fan translation for Western players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactics-ogre---let-us-cling-together-japan', 'SNES', 'Tactics Ogre - Let Us Cling Together (Japan)', '1995', 'Strategy', 'Riverhillsoft', '1', 'Tactical RPG', 'Isometric tactical RPG (Japanese release).', 'Experience the original epic of the Valethia islands.', 'Play Tactics Ogre on the Super Famicom.', 'Quest’s 16-bit magnum opus. Known for its sophisticated height-based combat mechanics, beautiful sprite art, and one of the most complex scripts in 16-bit history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactics-ogre---let-us-cling-together-japan-rev-a', 'SNES', 'Tactics Ogre - Let Us Cling Together (Japan) (Rev A)', '1995', 'Strategy', 'Riverhillsoft', '1', 'Tactical RPG', 'Isometric tactical RPG (Revision A).', 'Master the battlefield in the refined Rev A build.', 'Play Tactics Ogre (Rev A) on the Super Famicom.', 'The first 16-bit retail update. Optimizes unit pathfinding and fixes minor bugs related to specific class abilities and late-game inventory management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactics-ogre---let-us-cling-together-japan-rev-b', 'SNES', 'Tactics Ogre - Let Us Cling Together (Japan) (Rev B)', '1995', 'Strategy', 'Riverhillsoft', '1', 'Tactical RPG', 'Isometric tactical RPG (Revision B).', 'Play the definitive stable version of this RPG icon.', 'Play Tactics Ogre (Rev B) on the Super Famicom.', 'The final 16-bit revision. Includes all previous bug fixes and provides the most balanced and stable experience for this legendary tactical adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tadaima-yuusha-boshuuchuu-okawari-japan', 'SNES', 'Tadaima Yuusha Boshuuchuu Okawari (Japan)', '1993', 'Adventure', 'Namco', '1', 'Text-based adventure', 'Turn-based board game RPG hybrid.', 'Complete the quest and manage your party in 16-bit.', 'Play Tadaima Yuusha Boshuuchuu Okawari on SNES.', 'A charming 16-bit hybrid where hero recruitment meets board game mechanics. Navigate random events and build a balanced team to conquer the fantasy board.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taekwon-do-japan-jako', 'SNES', 'Taekwon-Do (Japan) (Ja,Ko)', '1993', 'Fighting', 'Human Entertainment', '2', 'Martial arts fighting', 'Side-view martial arts simulation.', 'Master the art of Taekwon-Do in 16-bit tournaments.', 'Experience Taekwon-Do on the Super Famicom.', 'Features realistic techniques and a technical stamina system. A unique 16-bit fighter that emphasizes discipline and timing over button-mashing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taiketsu!!-brass-numbers-japan', 'SNES', 'Taiketsu!! Brass Numbers (Japan)', '1995', 'Puzzle', 'Human Entertainment', '2', 'Turn-based strategy puzzle', 'Weapon-based 2D fighting game.', 'Defeat the robotic "Brass Numbers" in 16-bit combat.', 'Play Taiketsu!! Brass Numbers on Super Famicom.', 'A futuristic 16-bit fighter. Features large sprites, mechanical combatants with unique weapon systems, and smooth animations for a satisfying arcade-style experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taikou-risshiden-japan', 'SNES', 'Taikou Risshiden (Japan)', '1993', 'Strategy', 'Koei', '1', 'Historical simulation', 'Historical life-simulation and strategy.', 'Rise from a commoner to a powerful Shogun.', 'Explore Taikou Risshiden on the Super Famicom.', 'A deep 16-bit Koei simulation. Focuses on the life of Toyotomi Hideyoshi, blending role-playing elements with grand strategy and political maneuvering.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taikyoku-igo---goliath-japan', 'SNES', 'Taikyoku Igo - Goliath (Japan)', '1993', 'Board Game', 'Namco', '2', 'Go board game', 'Traditional Go board game simulation.', 'Defeat the "Goliath" AI in this 16-bit Go match.', 'Play Taikyoku Igo - Goliath on Super Famicom.', 'A specialized 16-bit Go title featuring a powerful engine for its time. Includes multiple board sizes and handicap settings for players of all skill levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taikyoku-igo---idaten-japan', 'SNES', 'Taikyoku Igo - Idaten (Japan)', '1994', 'Board Game', 'Namco', '2', 'Go board game', 'Traditional Go board game (Speed-focused).', 'Outplay the swift "Idaten" engine in 16-bit Go.', 'Experience Taikyoku Igo - Idaten on Super Famicom.', 'Features a fast-calculating AI designed for quick matches. A great 16-bit tool for practicing Go tactics and openings without long wait times.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takahashi-meijin-no-daibouken-shima-japan', 'SNES', 'Takahashi Meijin no Daibouken Shima (Japan)', '1992', 'Action-Platformer', 'Hudson Soft', '1', '2D side-scrolling', 'Side-scrolling platformer (Wonder Boy style).', 'Rescue your girlfriend in this 16-bit island quest.', 'Play Takahashi Meijin no Daibouken Shima on SNES.', 'The 16-bit debut of "Adventure Island." Features vibrant graphics, the classic skateboard mechanic, and challenging platforming across tropical levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takahashi-meijin-no-daibouken-shima-ii-japan', 'SNES', 'Takahashi Meijin no Daibouken Shima II (Japan)', '1993', 'Action-Platformer', 'Hudson Soft', '1', '2D side-scrolling', 'Enhanced island-hopping platformer sequel.', 'Explore the expanded archipelago in this 16-bit sequel.', 'Play Takahashi Meijin no Daibouken Shima II on SNES.', 'Improves on the original with a world map, diverse dinosaur companions to ride, and more complex environmental puzzles for a superior 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('take-yutaka-gi-memory-japan', 'SNES', 'Take Yutaka GI Memory (Japan)', '1995', 'Sports', 'Sammy', '1', 'Horse racing management', 'Horse racing and management simulation.', 'Train champions with the help of a legendary jockey.', 'Experience Take Yutaka GI Memory on Super Famicom.', 'Features detailed horse breeding and racing physics. A 16-bit sim that focuses on the career and expertise of the famous Japanese jockey Take Yutaka.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takeda-nobuhiro-no-super-cup-soccer-japan', 'SNES', 'Takeda Nobuhiro no Super Cup Soccer (Japan)', '1994', 'Sports', 'TOSE', '2', 'Soccer simulation', 'Arcade-style soccer simulation (Takeda).', 'Win the cup with high-speed 16-bit soccer action.', 'Play Takeda Nobuhiro no Super Cup Soccer on SNES.', 'Endorsed by the Japanese star. Features fast gameplay, large sprites, and a focus on spectacular shots and arcade-style goal-scoring.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takeda-nobuhiro-no-super-league-soccer-japan', 'SNES', 'Takeda Nobuhiro no Super League Soccer (Japan)', '1994', 'Sports', 'TOSE', '2', 'Soccer simulation', 'Professional league soccer simulation.', 'Manage your team to the top of the 16-bit league.', 'Play Takeda Nobuhiro no Super League Soccer on SNES.', 'Focuses on the Japanese professional league. Includes updated rosters, customizable formations, and fluid 16-bit animations for a realistic sports experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takemiya-masaki-kudan-no-igo-taishou-japan', 'SNES', 'Takemiya Masaki Kudan no Igo Taishou (Japan)', '1994', 'Board Game', 'Namco', '2', 'Go board game', 'Traditional Go simulation and education.', 'Learn from the Master in this 16-bit Go trainer.', 'Play Takemiya Masaki Kudan no Igo Taishou on SNES.', 'Features lessons and puzzles curated by the 9th-dan professional Takemiya Masaki. An excellent 16-bit educational tool for serious Go students.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-phantasia-japan', 'SNES', 'Tales of Phantasia (Japan)', '1995', 'RPG', 'Namco', '1', 'Japanese-style RPG', 'Technical action-RPG with voiced combat.', 'Travel through time to save the world in this epic.', 'Experience the original Tales of Phantasia on SNES.', 'A 16-bit technical marvel. Features the "Linear Motion Battle System" and high-quality audio that pushed the SNES hardware beyond its known limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-phantasia-japan-en-by-dejap-v12-lower-case-font', 'SNES', 'Tales of Phantasia (Japan) [En by DeJap v1.2] (Lower Case Font)', '1995', 'RPG', 'Namco', '1', 'Japanese-style RPG', 'Action-RPG (English Translation - Lower Case).', 'Enjoy the Phantasia epic with a clean English font.', 'Play Tales of Phantasia in English on the SNES.', 'The legendary DeJap 16-bit fan translation. Fully translates the massive story and voiced dialogue, using a modern lower-case font for better readability.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-phantasia-japan-en-by-dejap-v12-upper-case-font', 'SNES', 'Tales of Phantasia (Japan) [En by DeJap v1.2] (Upper Case Font)', '1995', 'RPG', 'Namco', '1', 'Japanese-style RPG', 'Action-RPG (English Translation - Upper Case).', 'Play the translated Phantasia classic in retro style.', 'Experience Tales of Phantasia (DeJap) on the SNES.', 'The classic 16-bit fan translation featuring a traditional "all-caps" RPG font. Offers the complete, unedited story of Cless and his time-traveling companions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tamagotchi-town-japan-np', 'SNES', 'Tamagotchi Town (Japan) (NP)', '1996', 'Simulation', 'Bandai', '1', 'Virtual pet simulation', 'Virtual pet simulation (Nintendo Power).', 'Manage your 16-bit digital town of Tamagotchis.', 'Play Tamagotchi Town on the Super Famicom.', 'Originally a downloadable title. Expand your town, play mini-games, and interact with various 16-bit Tamagotchi characters in this charming digital simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tarot-mystery-japan', 'SNES', 'Tarot Mystery (Japan)', '1993', 'Adventure', 'Human Entertainment', '1', 'Mystery adventure', 'Tarot reading and occult-themed puzzles.', 'Uncover your destiny in this unique 16-bit sim.', 'Experience Tarot Mystery on the Super Famicom.', 'Combines traditional Tarot card readings with logic-based puzzles. Features beautiful 16-bit occult art and a relaxing, mysterious atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tatakae-genshijin-2---rookie-no-bouken-japan', 'SNES', 'Tatakae Genshijin 2 - Rookie no Bouken (Japan)', '1994', 'Action-Platformer', 'Data East', '2', '2D run and gun', 'Prehistoric action-platformer (Joe & Mac 2).', 'Recover the crown in this colorful 16-bit sequel.', 'Play Tatakae Genshijin 2 on the Super Famicom.', 'Known as "Joe & Mac 2: Lost in the Tropics." Features RPG elements, village building, and incredible 16-bit boss fights against giant dinosaurs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tatakae-genshijin-3---shuyaku-wa-yappari-joe-&-mac-japan', 'SNES', 'Tatakae Genshijin 3 - Shuyaku wa Yappari Joe & Mac (Japan)', '1995', 'Action-Platformer', 'Data East', '2', '2D run and gun', 'Prehistoric action-platformer (Joe & Mac 3).', 'Save the cave-babes in the final 16-bit adventure.', 'Play Tatakae Genshijin 3 on the Super Famicom.', 'Known as "Joe & Mac: Caveman Ninja." A pixel-perfect 16-bit arcade port. Features wacky humor, multiple weapon types, and cooperative 2-player caveman action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-mania-europe', 'SNES', 'Taz-Mania (Europe)', '1992', 'Platformer', 'Beam Software', '1', '2D side-scrolling', 'Behind-the-back racing and platforming.', 'Chase down the items and survive the 16-bit road.', 'Play Taz-Mania on the Super Nintendo.', 'Features a unique perspective using the Mode 7 engine. Spin, jump, and eat your way through the desert in this fast-paced 16-bit Looney Tunes adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-mania-usa', 'SNES', 'Taz-Mania (USA)', '1992', 'Platformer', 'Beam Software', '1', '2D side-scrolling', 'Behind-the-back action (USA release).', 'Gulp down birds and outrun the obstacles as Taz.', 'Experience Taz-Mania for the Super Nintendo.', 'A visually impressive 16-bit title. Use Taz’s iconic tornado spin to navigate the shifting 3D-style roads and reach the end of the stage before time runs out.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-mania-usa-beta', 'SNES', 'Taz-Mania (USA) (Beta)', '1992', 'Platformer', 'Beam Software', '1', '2D side-scrolling', 'Behind-the-back action (USA Beta).', 'Test the early Mode 7 road physics as Taz.', 'Check out the Taz-Mania Beta on the SNES.', 'A rare 16-bit development build. Features experimental sprite scaling for obstacles and early iterations of the desert backgrounds and sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-mania-usa-rev-a', 'SNES', 'Taz-Mania (USA) (Rev A)', '1992', 'Platformer', 'Beam Software', '1', '2D side-scrolling', 'Behind-the-back action (USA Revision A).', 'Race through the outback in the refined 16-bit Taz.', 'Play Taz-Mania (Rev A) on the Super Nintendo.', 'The updated 16-bit retail version. Fixes minor collision bugs when spinning through objects and optimizes the Mode 7 scrolling for a smoother frame rate.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-secret-of-the-stars-usa', 'SNES', 'Tecmo Secret of the Stars (USA)', '1995', 'RPG', 'Tecmo', '1', 'Japanese-style RPG', 'Traditional turn-based RPG.', 'Lead the Aqutallion heirs to defeat the forces of Homun.', 'Play Tecmo Secret of the Stars on the SNES.', 'A unique 16-bit RPG featuring a dual-party system. Manage two different groups of heroes simultaneously to solve puzzles and engage in classic turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-secret-of-the-stars-usa-beta', 'SNES', 'Tecmo Secret of the Stars (USA) (Beta)', '1995', 'RPG', 'Tecmo', '1', 'Japanese-style RPG', 'Traditional turn-based RPG (Beta).', 'Test the early magic systems and party mechanics.', 'Check out the Secret of the Stars Beta on SNES.', 'A rare 16-bit development build. Features unfinished dialogue strings and early versions of the town maps and enemy encounter rates.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-secret-of-the-stars-usa-bug-fix-by-kingmike-v10-decatus-bribe-fix', 'SNES', 'Tecmo Secret of the Stars (USA) [Bug Fix by KingMike v1.0] (Decatus Bribe Fix)', '1995', 'RPG', 'Tecmo', '1', 'Japanese-style RPG', 'Turn-based RPG (Bug Fix Edition).', 'Experience the full quest without the game-breaking bugs.', 'Play Secret of the Stars (KingMike Fix) on SNES.', 'A vital 16-bit fan patch. Fixes the notorious "Decatus Bribe" glitch that prevented progress in the original retail release, ensuring a smooth playthrough.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-baseball-japan', 'SNES', 'Tecmo Super Baseball (Japan)', '1994', 'Sports', 'Tecmo', '2', 'Baseball simulation', 'Arcade-style baseball simulation.', 'Win the 16-bit world series with Tecmo precision.', 'Play Tecmo Super Baseball on the Super Famicom.', 'Features the signature Tecmo cinematic style. Includes smooth 16-bit animations, realistic stat tracking, and a focus on fast-paced pitcher-vs-batter duels.');
