INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-baseball-usa-beta', 'SNES', 'Tecmo Super Baseball (USA) (Beta)', '1994', 'Sports', 'Tecmo', '2', 'Baseball simulation', 'Arcade-style baseball (USA Beta).', 'Test the early batting physics and field logic.', 'Check out the Tecmo Super Baseball Beta on SNES.', 'A 16-bit development slice. Shows early iterations of the player sprites and the initial implementation of the "zoom-in" catch animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-bowl-japan', 'SNES', 'Tecmo Super Bowl (Japan)', '1993', 'Sports', 'Tecmo', '2', 'American football', 'Cinematic American Football simulation.', 'Conquer the 16-bit gridiron in the Japanese edition.', 'Play Tecmo Super Bowl on the Super Famicom.', 'The legendary football sim. Known for its cutscenes for touchdowns and big plays, offering a dramatic and accessible 16-bit sports experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-bowl-usa', 'SNES', 'Tecmo Super Bowl (USA)', '1993', 'Sports', 'Tecmo', '2', 'American football', 'Cinematic American Football (USA release).', 'Lead your NFL team to the Super Bowl in 16-bit.', 'Experience the classic Tecmo Super Bowl on SNES.', 'A cornerstone of 16-bit sports gaming. Features real players, a complete season mode, and the addictive gameplay that defined a generation of football fans.');
