INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-bowl-ii---special-edition-usa', 'SNES', 'Tecmo Super Bowl II - Special Edition (USA)', '1994', 'Sports', 'Tecmo', '2', 'American football', 'Advanced football sequel (USA release).', 'Win the "Special Edition" championship in 16-bit.', 'Experience Tecmo Super Bowl II on the SNES.', 'Features updated rosters and improved graphics. Includes the "Special Edition" enhancements for a more comprehensive and polished 16-bit football experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-bowl-iii---final-edition-japan', 'SNES', 'Tecmo Super Bowl III - Final Edition (Japan)', '1995', 'Sports', 'Tecmo', '2', 'American football', 'Final entry in the 16-bit football trilogy.', 'Achieve legendary status in the "Final Edition."', 'Play Tecmo Super Bowl III on the Super Famicom.', 'The pinnacle of the 16-bit series. Features the most refined graphics, customizable players, and a deep career mode that tracks stats across multiple seasons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-bowl-iii---final-edition-usa', 'SNES', 'Tecmo Super Bowl III - Final Edition (USA)', '1995', 'Sports', 'Tecmo', '2', 'American football', 'Final entry in the football trilogy (USA).', 'Create your own superstar in the 16-bit finale.', 'Experience Tecmo Super Bowl III on the SNES.', 'Introduces a robust player-creation tool and free agency. The ultimate 16-bit football package for fans seeking depth and long-term replayability.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-nba-basketball-australia', 'SNES', 'Tecmo Super NBA Basketball (Australia)', '1993', 'Sports', 'Tecmo', '2', 'Basketball arcade', 'Professional basketball simulation.', 'Dominate the 16-bit court in the Australian version.', 'Play Tecmo Super NBA Basketball on the SNES.', 'Features the full NBA license with real players and teams. A fast-paced 16-bit basketball sim with cinematic dunks and tight defensive gameplay.');
