INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-super-nba-basketball-usa', 'SNES', 'Tecmo Super NBA Basketball (USA)', '1993', 'Sports', 'Tecmo', '2', 'Basketball arcade', 'Professional basketball (USA release).', 'Lead your team to the NBA Finals in 16-bit.', 'Experience Tecmo Super NBA Basketball on the SNES.', 'The gold standard for 16-bit basketball. Features all the stars of the early 90s, detailed season tracking, and high-energy arcade-style gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teenage-mutant-hero-turtles---tournament-fighters-europe', 'SNES', 'Teenage Mutant Hero Turtles - Tournament Fighters (Europe)', '1993', 'Fighting', 'Konami', '2', '2D competitive fighting', 'One-on-one fighting game (TMHT).', 'Defeat the Shredder in the European 16-bit fighter.', 'Play TMHT: Tournament Fighters on the SNES.', 'The European version of the TMNT fighter. Features large, detailed sprites and a sophisticated fighting engine tailored for the SNES hardware.');
