INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teenage-mutant-ninja-turtles---tournament-fighters-usa-beta', 'SNES', 'Teenage Mutant Ninja Turtles - Tournament Fighters (USA) (Beta)', '1993', 'Fighting', 'Konami', '2', '2D competitive fighting', 'One-on-one fighting game (USA Beta).', 'Test the early turtle combat and sprite logic.', 'Check out the Tournament Fighters Beta on the SNES.', 'A rare 16-bit development build. Features unfinished background art and early versions of the character balancing and sound effects.');
