INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teenage-mutant-ninja-turtles-iv---turtles-in-time-usa-beta', 'SNES', 'Teenage Mutant Ninja Turtles IV - Turtles in Time (USA) (Beta)', '1992', 'Action', 'Konami', '2', '2D beat ''em up', 'Side-scrolling beat ''em up (USA Beta).', 'Explore the early development of the 16-bit Turtle saga.', 'Check out the Turtles in Time Beta on the SNES.', 'A fascinating look at the 16-bit porting process. Features different enemy placements and prototype versions of the iconic 16-bit music tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teitoku-no-ketsudan-japan', 'SNES', 'Teitoku no Ketsudan (Japan)', '1994', 'Strategy', 'Koei', '1', 'Turn-based military strategy', 'Grand strategy and naval combat (P.T.O.).', 'Command the Pacific fleet in this deep 16-bit sim.', 'Play Teitoku no Ketsudan on the Super Famicom.', 'Koei''s "Pacific Theater of Operations." Manage resources, ship production, and tactical naval battles in an accurate 16-bit historical simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teitoku-no-ketsudan-japan-rev-a', 'SNES', 'Teitoku no Ketsudan (Japan) (Rev A)', '1994', 'Strategy', 'Koei', '1', 'Turn-based military strategy', 'Grand strategy (Updated Revision A).', 'Lead your fleet to victory in the refined Rev A.', 'Play Teitoku no Ketsudan (Rev A) on Super Famicom.', 'The updated 16-bit retail version. Fixes minor menu navigation bugs and optimizes the AI''s strategic planning for long-term campaigns.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teitoku-no-ketsudan-ii-japan', 'SNES', 'Teitoku no Ketsudan II (Japan)', '1995', 'Strategy', 'Koei', '1', 'Turn-based military strategy', 'Advanced naval strategy sequel (P.T.O. II).', 'Master the global naval war in this 16-bit sequel.', 'Experience Teitoku no Ketsudan II on Super Famicom.', 'Significantly expands the scope of the original. Features much more detailed 16-bit graphics and a complex system for diplomatic and military management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teitoku-no-ketsudan-ii-japan-rev-a', 'SNES', 'Teitoku no Ketsudan II (Japan) (Rev A)', '1995', 'Strategy', 'Koei', '1', 'Turn-based military strategy', 'Advanced strategy sequel (Revision A).', 'Conquer the seas in the most stable 16-bit version.', 'Play Teitoku no Ketsudan II (Rev A) on SNES.', 'The definitive 16-bit Japanese release. Includes final bug fixes for the troop transport logic and optimizes the save data for massive world maps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tekichuu-keiba-juku-japan', 'SNES', 'Tekichuu Keiba Juku (Japan)', '1994', 'Sports', 'Asmik', '1', 'Horse racing simulation', 'Horse racing and betting simulation.', 'Study the odds and win big on the 16-bit track.', 'Explore Tekichuu Keiba Juku on the Super Famicom.', 'A detailed 16-bit horse racing "cram school." Learn how to analyze horse stats, track conditions, and betting patterns to become a 16-bit racing expert.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tekken-2-world-unl', 'SNES', 'Tekken 2 (World) (Unl)', '1996', 'Fighting', 'Namco', '2', '3D-style fighting (2D adaptation)', 'One-on-one fighting game (Unlicensed).', 'Experience the 3D fighter in 2D 16-bit form.', 'Try the rare Tekken 2 on the Super Nintendo.', 'An impressive unlicensed 16-bit port. Attempts to recreate the Tekken experience on the SNES with large sprites and a surprisingly competent fighting engine for a bootleg title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('temple-of-the-winds-31', 'SNES', 'Temple of the Winds 3.1', '2019', 'Action-Adventure', 'Fan Developer', '1', 'Top-down exploration', 'Fan-made total conversion (Zelda Hack).', 'Navigate the elemental temple in this 16-bit quest.', 'Play Temple of the Winds 3.1 on the SNES.', 'A creative 16-bit romhack of A Link to the Past. Features entirely new dungeon layouts, custom puzzles, and a specialized focus on wind-based environmental mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchi-muyou!---game-hen-japan', 'SNES', 'Tenchi Muyou! - Game Hen (Japan)', '1995', 'Adventure', 'Banpresto', '1', 'Visual novel adventure', 'Turn-based strategy RPG (Anime-based).', 'Lead Tenchi and his friends in tactical 16-bit combat.', 'Experience Tenchi Muyou! Game Hen on Super Famicom.', 'Based on the popular anime series. Features beautiful 16-bit sprite work, a unique grid-based combat system, and a charming story that captures the spirit of the show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchi-muyou!---game-hen-japan-en-by-borderline+lnf-v10', 'SNES', 'Tenchi Muyou! - Game Hen (Japan) [En by BorderLine+LNF v1.0]', '1995', 'Adventure', 'Banpresto', '1', 'Visual novel adventure', 'Strategy RPG (English Translation).', 'Play the Tenchi Muyou! RPG in English for the first time.', 'Play Tenchi Muyou! Game Hen in English on SNES.', 'The complete 16-bit fan translation. Makes the tactical combat and humorous character interactions accessible to Western fans of the Tenchi universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchi-o-kurau---sangokushi-gunyuuden-japan', 'SNES', 'Tenchi o Kurau - Sangokushi Gunyuuden (Japan)', '1994', 'Action RPG', 'Capcom', '1', 'Hack and slash RPG', 'Grand strategy (Three Kingdoms era).', 'Unify China in this 16-bit historical simulation.', 'Play Tenchi o Kurau on the Super Famicom.', 'The SNES entry in the "Destiny of an Emperor" series. Features large-scale tactical battles, officer recruitment, and deep management of the Three Kingdoms territories.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchi-souzou-japan', 'SNES', 'Tenchi Souzou (Japan)', '1995', 'Simulation', 'Enix', '1', 'God simulation', 'Action-RPG (Original Japanese Version).', 'Restore the world from the underworld in 16-bit.', 'Experience Tenchi Souzou (Terranigma) on SNES.', 'A technical and emotional 16-bit masterpiece. Guide Ark through the resurrection of the continents, plants, animals, and eventually humanity in a stunning world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tengai-makyou-zero---shounen-jump-no-shou-japan', 'SNES', 'Tengai Makyou Zero - Shounen Jump no Shou (Japan)', '1995', 'RPG', 'Hudson Soft', '1', 'Japanese-style RPG', 'Technical JRPG (Jump Special Edition).', 'Explore a specialized 16-bit quest with Jump characters.', 'Play Tengai Makyou Zero (Shounen Jump) on SNES.', 'A rare promotional version of the JRPG classic. Features a real-time clock and high-fidelity 16-bit graphics powered by the specialized SPC7110 expansion chip.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tengai-makyou-zero-japan', 'SNES', 'Tengai Makyou Zero (Japan)', '1995', 'RPG', 'Hudson Soft', '1', 'Japanese-style RPG', 'Epic JRPG with real-time clock system.', 'Journey through the Fire Clan''s 16-bit legend.', 'Experience Tengai Makyou Zero on the Super Famicom.', 'One of the most advanced 16-bit RPGs. Uses a real-time calendar for in-game events and features an incredible amount of voiced lines and high-quality animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenryuu-genichiro-no-pro-wrestling-revolution-japan', 'SNES', 'Tenryuu Genichiro no Pro Wrestling Revolution (Japan)', '1994', 'Wrestling', 'Human Entertainment', '2', 'Pro wrestling', 'Professional wrestling simulation.', 'Win the 16-bit championship with Genichiro Tenryu.', 'Play Pro Wrestling Revolution on the Super Famicom.', 'A technical 16-bit wrestler featuring realistic movesets and a stamina-based combat system endorsed by the legendary Japanese pro wrestler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenshi-no-uta---shiroki-tsubasa-no-inori-japan', 'SNES', 'Tenshi no Uta - Shiroki Tsubasa no Inori (Japan)', '1994', 'RPG', 'Telenet Japan', '1', 'Japanese-style RPG', 'Traditional turn-based JRPG (Angel''s Song).', 'Follow a touching story of faith and 16-bit adventure.', 'Experience Tenshi no Uta on the Super Famicom.', 'Known for its beautiful 16-bit soundtrack and classic dragon-quest style gameplay. Features a tragic and engaging narrative with polished turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-europe', 'SNES', 'Terminator 2 - Judgment Day (Europe)', '1993', 'Action', 'Bits Studios', '1', '2D action platformer', 'Side-scrolling action (Terminator 2).', 'Protect John Connor from the T-1000 in 16-bit.', 'Play Terminator 2: Judgment Day on the SNES.', 'A challenging 16-bit action title. Navigate through futuristic ruins and modern-day Los Angeles, using a variety of weapons to stop the liquid metal assassin.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-europe-beta', 'SNES', 'Terminator 2 - Judgment Day (Europe) (Beta)', '1993', 'Action', 'Bits Studios', '1', '2D action platformer', 'Action-platformer (Beta Version).', 'Test the early T-800 physics and level layouts.', 'Check out the Terminator 2 Beta on the SNES.', 'A rare 16-bit development slice. Features unfinished background tiles and prototype versions of the driving stages and the iconic 16-bit theme music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-usa', 'SNES', 'Terminator 2 - Judgment Day (USA)', '1993', 'Action', 'Bits Studios', '1', '2D action platformer', 'Side-scrolling action (USA release).', 'Ensure the future of humanity in this 16-bit struggle.', 'Experience T2: Judgment Day for the Super Nintendo.', 'Battle through the 16-bit representation of the film''s plot. Includes challenging platforming segments and high-stakes vehicle missions against SkyNet''s forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-the-europe', 'SNES', 'Terminator, The (Europe)', '1992', 'Action', 'Probe Entertainment', '1', '2D action platformer', 'Action-platformer (The Terminator).', 'Infiltrate the past and stop the T-800 in 16-bit.', 'Play The Terminator on the Super Nintendo.', 'A gritty 16-bit action game based on the original 1984 film. Features atmospheric levels and intense run-and-gun gameplay through the war-torn future and 80s LA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-the-europe-beta', 'SNES', 'Terminator, The (Europe) (Beta)', '1992', 'Action', 'Probe Entertainment', '1', '2D action platformer', 'Action-platformer (Beta Version).', 'Explore the early 16-bit future-war development.', 'Check out The Terminator Beta on the SNES.', 'A fascinating 16-bit look at the design process. Includes prototype enemy placements and early iterations of the cinematic 16-bit cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-the-usa', 'SNES', 'Terminator, The (USA)', '1992', 'Action', 'Probe Entertainment', '1', '2D action platformer', 'Action-platformer (USA release).', 'Stop the assassination of Sarah Connor in 16-bit.', 'Experience The Terminator for the Super Nintendo.', 'Master the 16-bit arsenal and survive the relentless pursuit of the machine. Features a high difficulty level and iconic 16-bit synth music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terranigma-europe', 'SNES', 'Terranigma (Europe)', '1995', 'Action RPG', 'Quintet', '1', 'Top-down action RPG', 'Action-RPG (European English Version).', 'Experience the ultimate 16-bit journey of rebirth.', 'Play the legendary Terranigma on the SNES.', 'Widely considered one of the best 16-bit games ever. Combines fluid action-combat with a deep, philosophical story and some of the best graphics on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terranigma-france', 'SNES', 'Terranigma (France)', '1995', 'Action RPG', 'Quintet', '1', 'Top-down action RPG', 'Action-RPG (French Translation).', 'Vivez l''aventure épique de Terranigma en français.', 'Jouez à Terranigma en français sur SNES.', 'The official 16-bit French localization. Allows francophone players to experience the deep narrative of Ark and the resurrection of the Earth with high-quality text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terranigma-germany', 'SNES', 'Terranigma (Germany)', '1995', 'Action RPG', 'Quintet', '1', 'Top-down action RPG', 'Action-RPG (German Translation).', 'Erleben Sie das 16-bit Meisterwerk Terranigma auf Deutsch.', 'Spielen Sie Terranigma auf Deutsch auf dem SNES.', 'The official 16-bit German release. Known for its excellent localization, bringing the complex themes of the game to life for German-speaking fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terranigma-germany-rev-a', 'SNES', 'Terranigma (Germany) (Rev A)', '1995', 'Action RPG', 'Quintet', '1', 'Top-down action RPG', 'Action-RPG (German Revision A).', 'Experience the refined 16-bit German classic.', 'Play Terranigma (Rev A) on the Super Nintendo.', 'The updated 16-bit German retail version. Fixes minor text overflows and optimizes the save system for a more stable adventure through the ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terranigma-spain', 'SNES', 'Terranigma (Spain)', '1995', 'Action RPG', 'Quintet', '1', 'Top-down action RPG', 'Action-RPG (Spanish Translation).', 'Disfruta de la obra maestra Terranigma en español.', 'Juega a Terranigma en español para la SNES.', 'One of the few 16-bit RPGs officially localized into Spanish. An essential experience for Spanish-speaking fans of the 16-bit action-adventure genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-2-europe', 'SNES', 'Tetris 2 (Europe)', '1993', 'Puzzle', 'Nintendo R&D1', '2', 'Falling-block puzzle', 'Falling-block puzzle (Match-3 style).', 'Clear the 16-bit screens in this Tetris sequel.', 'Play Tetris 2 on the Super Nintendo.', 'Features a "Flash" mechanic where you must match three colored blocks to clear them. A unique 16-bit departure from the traditional line-clearing formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-2-usa', 'SNES', 'Tetris 2 (USA)', '1993', 'Puzzle', 'Nintendo R&D1', '2', 'Falling-block puzzle', 'Falling-block puzzle (USA release).', 'Master the 16-bit colors in the official USA version.', 'Experience Tetris 2 for the Super Nintendo.', 'Offers a variety of game modes, including a challenging puzzle mode where you must clear specific 16-bit block formations in a limited time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-2-usa-rev-a', 'SNES', 'Tetris 2 (USA) (Rev A)', '1993', 'Puzzle', 'Nintendo R&D1', '2', 'Falling-block puzzle', 'Falling-block puzzle (USA Revision A).', 'Master the 16-bit puzzle in the refined version.', 'Play Tetris 2 (Rev A) on the Super Nintendo.', 'The updated 16-bit retail version. Fixes minor graphical bugs in the background animations and optimizes the piece-drop physics for smoother play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-attack-europe-enja', 'SNES', 'Tetris Attack (Europe) (En,Ja)', '1996', 'Puzzle', 'Intelligent Systems', '2', 'Panel-matching puzzle', 'Head-to-head puzzle action (Yoshi-themed).', 'Defeat Bowser''s minions in this 16-bit puzzle masterpiece.', 'Play Tetris Attack on the Super Nintendo.', 'A 16-bit classic known as "Panel de Pon" in Japan. Features addictive swap-and-match gameplay with a high-speed competitive 2-player mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-attack-usa-enja', 'SNES', 'Tetris Attack (USA) (En,Ja)', '1996', 'Puzzle', 'Intelligent Systems', '2', 'Panel-matching puzzle', 'Puzzle action (USA release).', 'Challenge your friends in the ultimate 16-bit puzzle battle.', 'Experience Tetris Attack for the Super Nintendo.', 'Features the cast of Yoshi''s Island. A technical 16-bit puzzler that rewards quick thinking and massive chain reactions to send garbage blocks to rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-battle-gaiden-english', 'SNES', 'Tetris Battle Gaiden (English)', '1993', 'Puzzle', 'Bullet-Proof Software', '2', 'Competitive puzzle', 'Competitive puzzle (English Translation).', 'Play the cult-classic Battle Gaiden in English.', 'Play Tetris Battle Gaiden in English on the SNES.', 'The fan-translated 16-bit masterpiece. Features characters with unique magic powers that sabotage opponents, creating the most chaotic 16-bit Tetris experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-battle-gaiden-japan', 'SNES', 'Tetris Battle Gaiden (Japan)', '1993', 'Puzzle', 'Bullet-Proof Software', '2', 'Competitive puzzle', 'Competitive puzzle with magic powers.', 'Master the character-specific spells in 16-bit.', 'Experience Tetris Battle Gaiden on Super Famicom.', 'A fan-favorite in the 16-bit competitive scene. Collect orbs to trigger powers like shield, shrink, or block-swaps in this high-energy puzzle fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-flash-japan', 'SNES', 'Tetris Flash (Japan)', '1993', 'Puzzle', 'Taito', '2', 'Arcade puzzle', 'Falling-block puzzle (Japanese Tetris 2).', 'Master the "Flash" mechanics in the Japanese original.', 'Play Tetris Flash on the Super Famicom.', 'The Japanese name for Tetris 2. Features the same 16-bit color-matching gameplay and vibrant backgrounds, with a focus on quick-clear puzzle logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetsuwan-atom-japan', 'SNES', 'Tetsuwan Atom (Japan)', '1994', 'Action-Platformer', 'Tezuka Productions', '1', '2D side-scrolling', 'Side-scrolling action (Astro Boy).', 'Protect the future as the iconic Astro Boy in 16-bit.', 'Play Tetsuwan Atom on the Super Famicom.', 'Based on the legendary manga. Features high-flying 16-bit action, laser attacks, and boss fights against giant robots from the Osamu Tezuka universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-12th-annual-vanilla-level-design-contest:-collaboration-hack', 'SNES', 'The 12th Annual Vanilla Level Design Contest: Collaboration Hack', '2019', 'Platformer', 'Fan Developer', '1', '2D platformer compilation', 'Collaborative SMW level collection (VLDC 12).', 'Play the best "vanilla" levels from the 16-bit community.', 'Try the VLDC 12 Collaboration Hack on SNES.', 'A massive 16-bit compilation featuring dozens of creative levels that use only original Mario World assets. A testament to 16-bit level design ingenuity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-9th-annual-vanilla-level-design-contest:-collaboration-hack-by-smw-central', 'SNES', 'The 9th Annual Vanilla Level Design Contest: Collaboration Hack by SMW Central', '2016', 'Platformer', 'Fan Developer', '1', '2D platformer compilation', 'Collaborative SMW level collection (VLDC 9).', 'Explore a massive world of 16-bit community creativity.', 'Play the VLDC 9 Collaboration Hack on SNES.', 'A landmark 16-bit ROM hack. Features an enormous overworld connecting levels from the SMW Central design contest, showcasing the best 16-bit platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-legend-of-zelda---a-link-to-the-past---title-skip-and-full-hearts', 'SNES', 'The Legend of Zelda - A Link to the Past - Title Skip and Full Hearts', '2014', 'Action-Adventure', 'Fan Developer', '1', 'Top-down action RPG', 'Quality of Life modification (Zelda).', 'Start your Zelda adventure with speed and power.', 'Try the Zelda: ALttP Title Skip mod on SNES.', 'A specialized 16-bit tweak. Bypasses the intro cutscenes and grants the player full heart containers from the start for a faster 16-bit gameplay loop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-legend-of-zelda-parallel-worlds-remodel', 'SNES', 'The Legend of Zelda Parallel Worlds Remodel', '2016', 'Action-Adventure', 'Fan Developer', '1', 'Top-down action RPG', 'Massive world overhaul (Zelda Remodel).', 'Experience a tougher, redesigned 16-bit Hyrule.', 'Play Zelda: Parallel Worlds Remodel on SNES.', 'A fan-favorite 16-bit total conversion. Redesigns the entire world map and all dungeons, offering a much more difficult and fresh 16-bit Zelda challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-lion-king-early-prototype', 'SNES', 'The Lion King Early Prototype', '1994', 'Platformer', 'Westwood Studios', '1', '2D side-scrolling', 'Side-scrolling platformer (Early Prototype).', 'Explore the early 16-bit pride lands.', 'Check out The Lion King Early Prototype on SNES.', 'A fascinating 16-bit development look. Features unfinished animations for Simba, different enemy placements, and prototype music from the Disney classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-lost-levels-enhanced-by-pac', 'SNES', 'The Lost Levels Enhanced by Pac', '2018', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Enhanced platformer (The Lost Levels).', 'Conquer the hardest 16-bit Mario levels with a twist.', 'Play The Lost Levels Enhanced on the SNES.', 'A 16-bit modification that ports the Famicom classic into the SMW engine. Features updated physics, custom sprites, and several 16-bit quality-of-life fixes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-mysterious-mine-the-true-final-version', 'SNES', 'The Mysterious Mine (The True Final Version)', '2019', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made total conversion platformer.', 'Reach the "True Final Version" of this 16-bit quest.', 'Explore The Mysterious Mine on the SNES.', 'A high-quality 16-bit ROM hack of SMW. Features a dark, cave-themed aesthetic, custom power-ups, and intricate puzzle-platforming that challenges 16-bit veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('theme-park-europe-enfrde', 'SNES', 'Theme Park (Europe) (En,Fr,De)', '1994', 'Simulation', 'Bullfrog Productions', '1', 'Theme park management', 'Business management simulation.', 'Build and manage a profitable 16-bit amusement park.', 'Play Theme Park on the Super Nintendo.', 'The definitive 16-bit park builder. Manage ticket prices, staff, and ride safety across various global locations. Features deep economic strategy and charming 16-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('theme-park-japan', 'SNES', 'Theme Park (Japan)', '1994', 'Simulation', 'Bullfrog Productions', '1', 'Theme park management', 'Business management simulation (Japan).', 'Become the ultimate theme park tycoon in 16-bit.', 'Experience Theme Park on the Super Famicom.', 'The official Japanese localization. Offers the same deep management systems, from salt content in fries to the speed of the rollercoasters, all in 16-bit detail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thomas-the-tank-engine-and-friends-europe', 'SNES', 'Thomas the Tank Engine and Friends (Europe)', '1993', 'Platformer', 'Bright Light Productions', '1', '2D side-scrolling', 'Educational and mini-game collection.', 'Complete various tasks on the Island of Sodor.', 'Play Thomas the Tank Engine on the SNES.', 'A 16-bit title designed for younger players. Features racing, memory games, and simple navigation tasks with the beloved 16-bit sprites of Thomas and his friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thomas-the-tank-engine-and-friends-usa', 'SNES', 'Thomas the Tank Engine and Friends (USA)', '1993', 'Platformer', 'Bright Light Productions', '1', '2D side-scrolling', 'Educational and mini-game collection (USA).', 'Help Thomas and friends in this 16-bit adventure.', 'Experience Thomas the Tank Engine for the SNES.', 'Includes various interactive environments and educational puzzles. A colorful and accessible 16-bit experience that captures the charm of the original TV series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thoroughbred-breeder-japan', 'SNES', 'Thoroughbred Breeder (Japan)', '1993', 'Simulation', 'Hect', '1', 'Horse breeding simulation', 'Horse breeding and racing simulation.', 'Breed a champion racehorse in this 16-bit sim.', 'Play Thoroughbred Breeder on the Super Famicom.', 'A detailed 16-bit simulation. Manage bloodlines, training schedules, and betting strategies to dominate the Japanese horse racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thoroughbred-breeder-ii-japan', 'SNES', 'Thoroughbred Breeder II (Japan)', '1994', 'Simulation', 'Hect', '1', 'Horse breeding simulation', 'Enhanced breeding simulation sequel.', 'Create the ultimate 16-bit racing legacy.', 'Experience Thoroughbred Breeder II on Super Famicom.', 'Expands on the original with more detailed statistics, more diverse training options, and improved 16-bit visuals for the racing segments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thoroughbred-breeder-iii-japan', 'SNES', 'Thoroughbred Breeder III (Japan)', '1995', 'Simulation', 'Hect', '1', 'Horse breeding simulation', 'Advanced breeding simulation finale.', 'Master the 16-bit stables in the final entry.', 'Play Thoroughbred Breeder III on the Super Famicom.', 'The most comprehensive entry in the series. Features refined genetics systems and the most fluid 16-bit racing animations of the trilogy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thunder-spirits-japan', 'SNES', 'Thunder Spirits (Japan)', '1991', 'Shooter', 'Tecnosoft', '1', 'Vertical scrolling shooter', 'Horizontal-scrolling shoot ''em up (Shmup).', 'Defeat the ORN Empire in this 16-bit shmup.', 'Play Thunder Spirits on the Super Famicom.', 'Based on the legendary Thunder Force III. Features intense 16-bit horizontal action, massive bosses, and a stellar synth-rock soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thunder-spirits-usa', 'SNES', 'Thunder Spirits (USA)', '1991', 'Shooter', 'Tecnosoft', '1', 'Vertical scrolling shooter', 'Horizontal-scrolling shoot ''em up (USA).', 'Blast through alien defenses in 16-bit glory.', 'Experience Thunder Spirits on the Super Nintendo.', 'A classic 16-bit shooter known for its fast-paced action and diverse weapon system. Navigate through organic and mechanical stages to save the galaxy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thunderbirds---kokusai-kyuujotai-shutsudou-seyo!-japan', 'SNES', 'Thunderbirds - Kokusai Kyuujotai Shutsudou seyo! (Japan)', '1993', 'Action', 'ITL', '1', '2D action platformer', 'Vehicle-based action and rescue.', 'Execute the International Rescue missions in 16-bit.', 'Play Thunderbirds on the Super Famicom.', 'Based on the cult classic show. Control iconic 16-bit vehicles like Thunderbird 1 and 2 to solve puzzles and complete dangerous rescue operations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tick-the-usa', 'SNES', 'Tick, The (USA)', '1994', 'Action-Platformer', 'Software Creations', '1', '2D side-scrolling', 'Side-scrolling beat ''em up (Superhero).', 'Stop the villains of The City in this 16-bit brawl.', 'Play The Tick on the Super Nintendo.', 'Captures the surreal humor of the cartoon. Fight through waves of absurd enemies with The Tick''s superhuman strength in this colorful 16-bit beat ''em up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-slip-europe', 'SNES', 'Time Slip (Europe)', '1993', 'Action', 'Data East', '1', 'Isometric action', 'Side-scrolling action and platforming.', 'Travel through time to prevent a global catastrophe.', 'Experience Time Slip on the Super Nintendo.', 'Features levels set in various historical and future eras. Use 16-bit time-travel mechanics to navigate stages and defeat enemies across the ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-slip-europe-beta', 'SNES', 'Time Slip (Europe) (Beta)', '1993', 'Action', 'Data East', '1', 'Isometric action', 'Action and platforming (Beta Version).', 'Explore the early 16-bit time-travel development.', 'Check out the Time Slip Beta on the SNES.', 'A rare 16-bit development slice. Features unfinished level transitions and prototype enemy AI, offering a look into the game''s 16-bit design history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-slip-usa', 'SNES', 'Time Slip (USA)', '1993', 'Action', 'Data East', '1', 'Isometric action', 'Side-scrolling action (USA release).', 'Master the 16-bit time portal in the USA version.', 'Play Time Slip for the Super Nintendo.', 'An ambitious 16-bit title. Battle through diverse settings from the prehistoric era to high-tech futures in a quest to stop an alien invasion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-trax-europe', 'SNES', 'Time Trax (Europe)', '1994', 'Action', 'THQ', '1', 'Side-scrolling action', 'Isometric action and strategy.', 'Track down time-traveling criminals in 16-bit.', 'Play Time Trax on the Super Nintendo.', 'Based on the sci-fi series. Features a unique 16-bit isometric perspective and a variety of high-tech gadgets to capture fugitives across time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-trax-usa', 'SNES', 'Time Trax (USA)', '1994', 'Action', 'THQ', '1', 'Side-scrolling action', 'Isometric action and strategy (USA).', 'Protect the timeline in this 16-bit sci-fi quest.', 'Experience Time Trax on the Super Nintendo.', 'Combines exploration with tactical combat. Navigate 16-bit futuristic environments and use your specialized skills to preserve history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-trax-usa-beta', 'SNES', 'Time Trax (USA) (Beta)', '1994', 'Action', 'THQ', '1', 'Side-scrolling action', 'Isometric action (USA Beta).', 'Test the early 16-bit isometric combat and physics.', 'Check out the Time Trax Beta on the SNES.', 'A rare 16-bit look at an unreleased (at the time) prototype. Features experimental camera angles and early versions of the time-stasis mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('timecop-europe', 'SNES', 'Timecop (Europe)', '1995', 'Action', 'Software Creations', '1', 'Side-scrolling action', 'Digitalized side-scrolling action.', 'Arrest criminals across history in this 16-bit tie-in.', 'Play Timecop on the Super Nintendo.', 'Based on the Jean-Claude Van Damme film. Features digitized 16-bit character sprites and intense action sequences across multiple historical eras.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('timecop-japan', 'SNES', 'Timecop (Japan)', '1995', 'Action', 'Software Creations', '1', 'Side-scrolling action', 'Digitalized side-scrolling action (Japan).', 'Navigate the 16-bit timeline in the Japanese release.', 'Experience Timecop on the Super Famicom.', 'Delivers the same high-stakes action and digitized 16-bit visuals. Features challenging boss fights and recognizable settings from the sci-fi movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('timecop-usa', 'SNES', 'Timecop (USA)', '1995', 'Action', 'Software Creations', '1', 'Side-scrolling action', 'Digitalized side-scrolling action (USA).', 'Enforce the 16-bit time-laws as a T.E.C. agent.', 'Play Timecop for the Super Nintendo.', 'Use an arsenal of 16-bit futuristic weapons to stop a rogue politician from altering the past. Features impressive digitized animations for the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('timon-&-pumbaas-jungle-games-europe', 'SNES', 'Timon & Pumbaa''s Jungle Games (Europe)', '1995', 'Minigame Compilation', 'Disney Interactive', '2', 'Variety mini-games', 'Mini-game collection (Lion King).', 'Play the funniest 16-bit games in the jungle.', 'Experience Timon & Pumbaa''s Jungle Games on SNES.', 'Features four addictive 16-bit mini-games, including "Jungle Pinball" and "Sling Shooter," starring the iconic Disney duo with vibrant animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('timon-&-pumbaas-jungle-games-usa', 'SNES', 'Timon & Pumbaa''s Jungle Games (USA)', '1995', 'Minigame Compilation', 'Disney Interactive', '2', 'Variety mini-games', 'Mini-game collection (USA release).', 'Enjoy Hakuna Matata in these 16-bit challenges.', 'Play Timon & Pumbaa''s Jungle Games on SNES.', 'A colorful 16-bit title perfect for quick play sessions. Features high-quality Disney sprites and humorous 16-bit sound effects and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tin-star-usa', 'SNES', 'Tin Star (USA)', '1994', 'Shooter', 'Software Creations', '1', 'Top-down shooter', 'Light-gun style shooting gallery.', 'Clean up the 16-bit Wild West as Tin Star.', 'Play the unique Tin Star on the Super Nintendo.', 'A specialized 16-bit shooter. Can be played with the controller, Super Scope, or SNES Mouse. Features a humorous 16-bit robotic western theme.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tinhead-europe-proto', 'SNES', 'Tinhead (Europe) (Proto)', '1993', 'Platformer', 'Probe Entertainment', '1', '2D side-scrolling', 'Surreal side-scrolling platformer (Proto).', 'Navigate bizarre 16-bit worlds as the metallic Tinhead.', 'Try the Tinhead Prototype on the Super Nintendo.', 'A creative 16-bit platformer. Features a protagonist who can fire his head in different directions to defeat enemies and solve environmental puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tintin-in-tibet-europe-enfrdenl', 'SNES', 'Tintin in Tibet (Europe) (En,Fr,De,Nl)', '1995', 'Platformer', 'Bit Managers', '1', '2D side-scrolling', 'Side-scrolling action-adventure (Tintin).', 'Find Tchang in the 16-bit mountains of Tibet.', 'Experience Tintin in Tibet on the Super Nintendo.', 'Known for its beautiful, comic-accurate 16-bit graphics. A challenging 16-bit adventure that requires precise platforming and careful observation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---buster-busts-loose!-europe', 'SNES', 'Tiny Toon Adventures - Buster Busts Loose! (Europe)', '1992', 'Platformer', 'Infogrames', '1', '2D side-scrolling', 'Cinematic action-platformer (Tiny Toons).', 'Star in your own 16-bit movie as Buster Bunny.', 'Play Buster Busts Loose! on the Super Nintendo.', 'Features incredible 16-bit animations and diverse levels, from a high-speed train to a haunted mansion. One of the best 16-bit cartoon adaptations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---buster-busts-loose!-europe-bug-fix-by-kingmike-v10-train-bug-fix', 'SNES', 'Tiny Toon Adventures - Buster Busts Loose! (Europe) [Bug Fix by KingMike v1.0] (Train Bug Fix)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Action-platformer (Train Bug Fix).', 'Experience the 16-bit classic without the crashes.', 'Play Buster Busts Loose! (KingMike Fix) on SNES.', 'A vital 16-bit fan patch. Fixes a notorious game-breaking bug in the train level of the European version, ensuring a smooth 16-bit playthrough.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---buster-busts-loose!-spain', 'SNES', 'Tiny Toon Adventures - Buster Busts Loose! (Spain)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Action-platformer (Spanish release).', 'Disfruta de la aventura de Buster en español.', 'Juega a Tiny Toon Adventures en español para SNES.', 'The official 16-bit Spanish localization. Experience Buster Bunny''s cinematic 16-bit levels with fully translated menus and story text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---buster-busts-loose!-usa', 'SNES', 'Tiny Toon Adventures - Buster Busts Loose! (USA)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Action-platformer (USA release).', 'Run, jump, and dash through 16-bit Acme Acres.', 'Experience Buster Busts Loose! for the SNES.', 'Master Buster''s 16-bit wall-run and dash mechanics. A high-energy title that captures the frantic spirit of the Tiny Toons cartoon in 16-bit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---buster-busts-loose!-usa-beta', 'SNES', 'Tiny Toon Adventures - Buster Busts Loose! (USA) (Beta)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Action-platformer (USA Beta).', 'Explore the early 16-bit animations of Buster Bunny.', 'Check out the Buster Busts Loose! Beta on SNES.', 'A fascinating 16-bit development build. Features different level orders and prototype versions of the 16-bit cinematic cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---buster-busts-loose!-usa-beta-bug-fix-by-kingmike-v10-train-bug-fix', 'SNES', 'Tiny Toon Adventures - Buster Busts Loose! (USA) (Beta) [Bug Fix by KingMike v1.0] (Train Bug Fix)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Action-platformer (Beta Bug Fix).', 'Test the 16-bit Beta with improved stability.', 'Try the Buster Busts Loose! Beta (Fix) on SNES.', 'Combines the rarity of the 16-bit Beta build with the stability of KingMike''s train bug fix, allowing for a complete look at the game''s 16-bit evolution.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---buster-busts-loose!-usa-bug-fix-by-kingmike-v10-train-bug-fix', 'SNES', 'Tiny Toon Adventures - Buster Busts Loose! (USA) [Bug Fix by KingMike v1.0] (Train Bug Fix)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Action-platformer (USA Bug Fix).', 'The definitive 16-bit way to play Buster''s quest.', 'Play Buster Busts Loose! (Bug Fixed) on SNES.', 'The most stable 16-bit version of the USA release. Fixes rare technical issues in the 16-bit engine, providing a perfect platforming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---dotabata-daiundoukai-japan', 'SNES', 'Tiny Toon Adventures - Dotabata Daiundoukai (Japan)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Wacky sports mini-game collection (Japan).', 'Compete in the 16-bit Acme Games in Japan.', 'Play Dotabata Daiundoukai on the Super Famicom.', 'The Japanese version of Wacky Sports Challenge. Features high-energy 16-bit mini-games like bungee jumping and bird-man flying with the Tiny Toons cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---wacky-sports-challenge-usa', 'SNES', 'Tiny Toon Adventures - Wacky Sports Challenge (USA)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Sports mini-game collection (USA release).', 'Win the 16-bit trophy in these wacky events.', 'Experience Wacky Sports Challenge on the SNES.', 'Features four-player support (with Multitap). A fun 16-bit party game with specialized events that test your reflexes and 16-bit timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---wild-&-wacky-sports-europe', 'SNES', 'Tiny Toon Adventures - Wild & Wacky Sports (Europe)', '1992', 'Sports', 'Konami', '4', 'Arcade sports', 'Sports mini-game collection (Europe).', 'Master the 16-bit Wild & Wacky sports.', 'Play Tiny Toon Adventures in Europe on SNES.', 'The European release of the 16-bit sports title. Features vibrant 16-bit graphics and a great selection of competitive mini-games for the whole family.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---wild-&-wacky-sports-europe-beta', 'SNES', 'Tiny Toon Adventures - Wild & Wacky Sports (Europe) (Beta)', '1994', 'Sports', 'Konami', '4', 'Arcade sports', 'Sports mini-game collection (Europe Beta).', 'Test the early 16-bit sports physics as Plucky.', 'Check out the Wild & Wacky Sports Beta on SNES.', 'A rare 16-bit development build. Shows early iterations of the mini-game scoring systems and prototype versions of the 16-bit sports arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures---wild-&-wacky-sports-europe-rev-a', 'SNES', 'Tiny Toon Adventures - Wild & Wacky Sports (Europe) (Rev A)', '1994', 'Sports', 'Konami', '4', 'Arcade sports', 'Sports mini-game collection (Europe Rev A).', 'Experience the refined 16-bit wacky sports.', 'Play Wild & Wacky Sports (Rev A) on the SNES.', 'The updated 16-bit retail version. Fixes minor graphical glitches in the bungee jumping mode and optimizes the 16-bit 4-player logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures-japan', 'SNES', 'Tiny Toon Adventures (Japan)', '1994', 'Sports', 'Konami', '4', 'Arcade sports', 'Action-platformer (Japanese version).', 'Rescue the cast in this 16-bit Japanese classic.', 'Experience Tiny Toon Adventures on Super Famicom.', 'The authentic Japanese release of Buster Bunny''s 16-bit epic. Known for its fluid controls and faithful 16-bit recreation of the show''s humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tiny-toon-adventures-japan-rev-a', 'SNES', 'Tiny Toon Adventures (Japan) (Rev A)', '1992', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Action-platformer (Japan Rev A).', 'Play the most stable 16-bit Tiny Toons in Japan.', 'Play Tiny Toon Adventures (Rev A) on Super Famicom.', 'The final 16-bit retail revision in Japan. Includes all minor bug fixes for the 16-bit sprite engine, ensuring the smoothest platforming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tko-super-championship-boxing-europe', 'SNES', 'TKO Super Championship Boxing (Europe)', '1992', 'Sports', 'Rare', '2', 'Boxing', 'One-on-one arcade boxing.', 'Become the world heavyweight champion in 16-bit.', 'Play TKO Super Championship Boxing on the SNES.', 'Features large, detailed sprites and a strategic stamina system. Master the 16-bit ring with precise jabs and hooks in this realistic European sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tko-super-championship-boxing-usa', 'SNES', 'TKO Super Championship Boxing (USA)', '1992', 'Sports', 'Rare', '2', 'Boxing', 'One-on-one arcade boxing (USA).', 'Climb the ranks and win the 16-bit belt.', 'Experience TKO Super Championship Boxing on SNES.', 'A technical 16-bit boxing sim. Includes multiple camera angles and a deep career mode where you train your fighter to reach the pinnacle of the world circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tko-super-championship-boxing-usa-sample', 'SNES', 'TKO Super Championship Boxing (USA) (Sample)', '1992', 'Sports', 'Rare', '2', 'Boxing', 'Arcade boxing (Early Sample).', 'Test the 16-bit punch physics and sprite logic.', 'Check out the TKO Boxing Sample on the SNES.', 'A rare 16-bit development slice. Features limited character selection and prototype ring backgrounds, offering a look at the game''s early 16-bit design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tls4s-math-contest-2---epic-adventures-in-test-stages!', 'SNES', 'TLs4''s MATH Contest 2 - Epic Adventures in Test Stages!', '2020', 'Platformer', 'Fan Developer', '1', '2D platformer compilation', 'Fan-made educational platformer.', 'Solve math problems to progress through 16-bit stages.', 'Try TLs4''s MATH Contest 2 on the SNES.', 'A creative 16-bit romhack of Super Mario World. Blends traditional platforming with mathematical puzzles, turning learning into a high-speed 16-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tnn-bass-tournament-of-champions-usa', 'SNES', 'TNN Bass Tournament of Champions (USA)', '1995', 'Sports', 'Bethesda Softworks', '1', 'Fishing simulation', 'Realistic fishing simulation.', 'Win the 16-bit bass fishing championship.', 'Play TNN Bass Tournament of Champions on SNES.', 'Features professional tournaments and a diverse tackle box. Navigate 16-bit lakes using the boat and find the best spots to land a trophy-sized bass.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tokimeki-memorial---densetsu-no-ki-no-shita-de-japan', 'SNES', 'Tokimeki Memorial - Densetsu no Ki no Shita de (Japan)', '1996', 'Simulation', 'Konami', '1', 'Dating simulation', 'High-school dating simulation.', 'Win the heart of your dream girl under the legendary tree.', 'Experience Tokimeki Memorial on the Super Famicom.', 'The game that defined the genre. Manage your 16-bit student life, study hard, join clubs, and navigate complex social interactions in this 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tokimeki-memorial---densetsu-no-ki-no-shita-de-japan-rev-a', 'SNES', 'Tokimeki Memorial - Densetsu no Ki no Shita de (Japan) (Rev A)', '1996', 'Simulation', 'Konami', '1', 'Dating simulation', 'Dating simulation (Updated Revision).', 'Experience the refined 16-bit student life in Japan.', 'Play Tokimeki Memorial (Rev A) on Super Famicom.', 'The updated 16-bit retail version. Fixes minor text errors in the branching dialogue and optimizes the loading times for the animated character portraits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tokoros-mahjong-japan', 'SNES', 'Tokoro''s Mahjong (Japan)', '1994', 'Mahjong', 'Vic Tokai', '1', 'Mahjong simulation', 'Traditional Mahjong simulation.', 'Defeat the famous George Tokoro in 16-bit Mahjong.', 'Play Tokoro''s Mahjong on the Super Famicom.', 'Features the likeness and humor of the Japanese celebrity. A solid 16-bit board game experience with a focus on fast gameplay and strategic tile management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-&-jerry-europe', 'SNES', 'Tom & Jerry (Europe)', '1993', 'Platformer', 'Software Creations', '1', '2D side-scrolling', 'Side-scrolling action-platformer.', 'Survive the 16-bit cat-and-mouse chaos.', 'Play Tom & Jerry on the Super Nintendo.', 'Control Jerry as you navigate through various house environments. Use household items to trap Tom and solve 16-bit puzzles in this colorful cartoon adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-&-jerry-japan', 'SNES', 'Tom & Jerry (Japan)', '1993', 'Platformer', 'Software Creations', '1', '2D side-scrolling', 'Action-platformer (Japanese release).', 'Experience Tom & Jerry''s 16-bit rivalry in Japan.', 'Experience Tom & Jerry on the Super Famicom.', 'The authentic Japanese release. Features fluid 16-bit animations and challenging platforming segments inspired by the most iconic episodes of the cartoon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-&-jerry-usa', 'SNES', 'Tom & Jerry (USA)', '1993', 'Platformer', 'Software Creations', '1', '2D side-scrolling', 'Action-platformer (USA release).', 'Help Jerry outsmart Tom across 16-bit levels.', 'Play Tom & Jerry for the Super Nintendo.', 'A classic 16-bit title with a focus on verticality and item usage. Dodge traps and collect cheese while exploring detailed 16-bit rooms and gardens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-&-jerry-usa-beta', 'SNES', 'Tom & Jerry (USA) (Beta)', '1993', 'Platformer', 'Software Creations', '1', '2D side-scrolling', 'Action-platformer (USA Beta).', 'Explore the early 16-bit Tom & Jerry level designs.', 'Check out the Tom & Jerry Beta on the SNES.', 'A rare 16-bit development build. Features unfinished background tiles and prototype versions of the 16-bit sound effects and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-vs-jerry---the-chase-is-on!', 'SNES', 'Tom VS Jerry - The Chase is On!', '2019', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made total conversion platformer.', 'Catch Jerry or escape Tom in this 16-bit hack.', 'Try Tom VS Jerry: The Chase is On! on the SNES.', 'A high-quality 16-bit romhack of SMW. Features custom character sprites and entirely new level layouts designed to capture the frantic pace of the original show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-meolas-sidekicks-soccer-usa', 'SNES', 'Tony Meola''s Sidekicks Soccer (USA)', '1993', 'Sports', 'Sculptured Software', '2', 'Soccer simulation', 'Isometric soccer simulation.', 'Win the 16-bit cup with USA star Tony Meola.', 'Experience Tony Meola''s Sidekicks Soccer on SNES.', 'Features a unique isometric perspective and Mode 7 field scaling. A fast-paced 16-bit sports title that emphasizes arcade-style goal scoring and defense.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-europe', 'SNES', 'Top Gear (Europe)', '1992', 'Racing', 'Gremlin Graphics', '2', 'Top-down racing', 'Behind-the-car racing simulation.', 'Race across the world and win the 16-bit cup.', 'Play the legendary Top Gear on the Super Nintendo.', 'Known for its incredible soundtrack and split-screen multiplayer. Manage your fuel and nitro across 32 tracks in this 16-bit racing masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-usa', 'SNES', 'Top Gear (USA)', '1992', 'Racing', 'Gremlin Graphics', '2', 'Top-down racing', 'Behind-the-car racing (USA release).', 'Dominate the 16-bit circuit in the official USA version.', 'Experience Top Gear on the Super Nintendo.', 'The foundational 16-bit racer. Features diverse global tracks and a strategic pit-stop mechanic that rewards careful resource management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-2-europe', 'SNES', 'Top Gear 2 (Europe)', '1993', 'Racing', 'Gremlin Graphics', '2', 'Top-down racing', 'Enhanced racing simulation sequel.', 'Upgrade your car and win the 16-bit world tour.', 'Play Top Gear 2 on the Super Nintendo.', 'Introduces a robust car customization system. Earn money in 16-bit races to upgrade your engine, tires, and armor in this deeper, more technical sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-2-usa', 'SNES', 'Top Gear 2 (USA)', '1993', 'Racing', 'Gremlin Graphics', '2', 'Top-down racing', 'Enhanced racing sequel (USA release).', 'Become the 16-bit racing champion in the USA sequel.', 'Experience Top Gear 2 for the Super Nintendo.', 'Features weather effects and realistic car damage. A refined 16-bit racing experience that balances high-speed action with strategic vehicle maintenance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-3000-europe', 'SNES', 'Top Gear 3000 (Europe)', '1995', 'Racing', 'Gremlin Graphics', '2', 'Futuristic top-down racing', 'Futuristic racing simulation (Year 3000).', 'Race through the galaxy in the 16-bit future.', 'Play Top Gear 3000 on the Super Nintendo.', 'The only game on the system to use the DSP-4 chip. Features 16-bit intergalactic tracks, futuristic power-ups like teleporters, and 4-player split-screen support.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-3000-usa', 'SNES', 'Top Gear 3000 (USA)', '1995', 'Racing', 'Gremlin Graphics', '2', 'Futuristic top-down racing', 'Futuristic racing (USA release).', 'Master the 16-bit space tracks in the USA version.', 'Experience Top Gear 3000 for the Super Nintendo.', 'A technical powerhouse. Includes 47 futuristic planets to race on, with 16-bit upgrades ranging from nuclear engines to jumping shocks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-management-ii-japan', 'SNES', 'Top Management II (Japan)', '1994', 'Simulation', 'Koei', '1', 'Sports management', 'Corporate management simulation.', 'Lead your 16-bit company to global dominance.', 'Play Top Management II on the Super Famicom.', 'A deep 16-bit strategy game. Manage stock prices, product development, and staff morale in a realistic simulation of the Japanese business world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-racer-japan', 'SNES', 'Top Racer (Japan)', '1992', 'Racing', 'Gremlin Graphics', '2', 'Top-down racing', 'Behind-the-car racing (Japanese Top Gear).', 'Experience the 16-bit Top Gear racing in Japan.', 'Play Top Racer on the Super Famicom.', 'The Japanese name for the first Top Gear. Features the same iconic music and high-speed 16-bit gameplay that made the series a global hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-racer-2-japan', 'SNES', 'Top Racer 2 (Japan)', '1993', 'Racing', 'Gremlin Graphics', '2', 'Top-down racing', 'Racing simulation sequel (Japan).', 'Master the 16-bit upgrade system in Japan.', 'Experience Top Racer 2 on the Super Famicom.', 'The authentic Japanese release of the sequel. Offers the same addictive loop of 16-bit racing and vehicle customization across a global circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('torneco-no-daibouken---fushigi-no-dungeon-japan', 'SNES', 'Torneco no Daibouken - Fushigi no Dungeon (Japan)', '1993', 'RPG', 'Chunsoft', '1', 'Roguelike dungeon crawler', 'Roguelike/Mystery Dungeon RPG.', 'Survive the shifting 16-bit dungeons as Torneko.', 'Play Torneko no Daibouken on the Super Famicom.', 'The first "Mystery Dungeon" game. Guide the 16-bit merchant through randomly generated floors, collecting items and defeating monsters in turn-based combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('torneco-no-daibouken---fushigi-no-dungeon-japan-rev-a', 'SNES', 'Torneco no Daibouken - Fushigi no Dungeon (Japan) (Rev A)', '1993', 'RPG', 'Chunsoft', '1', 'Roguelike dungeon crawler', 'Mystery Dungeon RPG (Revision A).', 'Master the 16-bit dungeon in the refined version.', 'Play Torneko no Daibouken (Rev A) on Super Famicom.', 'The updated 16-bit retail version. Fixes minor item-interaction bugs and optimizes the dungeon generation algorithm for a smoother experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('torneco-no-daibouken---fushigi-no-dungeon-japan-en-by-magic-destiny-v099-~taloons-great-adventure---mystery-dungeon', 'SNES', 'Torneco no Daibouken - Fushigi no Dungeon (Japan) [En by Magic Destiny v0.99] (~Taloon''s Great Adventure - Mystery Dungeon)', '1993', 'RPG', 'Chunsoft', '1', 'Roguelike dungeon crawler', 'Mystery Dungeon RPG (English Translation).', 'Enjoy Torneko''s 16-bit adventure in English.', 'Play Taloon''s Great Adventure in English on SNES.', 'The complete 16-bit fan translation. Makes the complex item names and humorous dialogue accessible, bringing this 16-bit roguelike pioneer to the West.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('total-carnage-europe', 'SNES', 'Total Carnage (Europe)', '1993', 'Shooter', 'Midway', '2', 'Top-down shooter', 'Top-down twin-stick style shooter.', 'Survive the 16-bit warzone and defeat General Ahboob.', 'Play Total Carnage on the Super Nintendo.', 'The spiritual successor to Smash T.V. Features intense 16-bit arcade action, thousands of enemies, and massive, screen-filling bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('total-carnage-usa', 'SNES', 'Total Carnage (USA)', '1993', 'Shooter', 'Midway', '2', 'Top-down shooter', 'Top-down shooter (USA release).', 'Blast your way to the 16-bit "Pleasure Dome."', 'Experience Total Carnage for the Super Nintendo.', 'A frantic 16-bit run-and-gun. Collect keys and power-ups while navigating bullet-hell environments in this high-energy arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('total-carnage-usa-beta1', 'SNES', 'Total Carnage (USA) (Beta1)', '1993', 'Shooter', 'Midway', '2', 'Top-down shooter', 'Top-down shooter (Early Beta 1).', 'Test the initial 16-bit enemy wave logic.', 'Check out the Total Carnage Beta 1 on the SNES.', 'A rare 16-bit development look. Features prototype weapon balance and early versions of the massive desert boss animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('total-carnage-usa-beta2', 'SNES', 'Total Carnage (USA) (Beta2)', '1993', 'Shooter', 'Midway', '2', 'Top-down shooter', 'Top-down shooter (Advanced Beta 2).', 'Explore the refined 16-bit Carnage mechanics.', 'Check out the Total Carnage Beta 2 on the SNES.', 'A later 16-bit development build. Includes more polished sound effects and near-final enemy placements, showcasing the optimization of the 16-bit engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tottemo!-lucky-man---lucky-cookie-roulette-de-totsugeki!!-japan', 'SNES', 'Tottemo! Lucky Man - Lucky Cookie Roulette de Totsugeki!! (Japan)', '1995', 'Action', 'Bandai', '1', 'Action mini-games', 'Humorous board game based on the manga.', 'Win the 16-bit "Lucky Cookie" roulette.', 'Experience Tottemo! Lucky Man on the Super Famicom.', 'Based on the surreal comedy series. Features luck-based 16-bit board game mechanics, humorous mini-games, and the bizarre cast of the Lucky Man universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('touge-densetsu---saisoku-battle-japan', 'SNES', 'Touge Densetsu - Saisoku Battle (Japan)', '1994', 'Racing', 'Atlus', '2', 'Street racing', 'Street racing simulation (Touge).', 'Become the king of the 16-bit mountain pass.', 'Play Touge Densetsu on the Super Famicom.', 'A technical 16-bit racing title focused on drifting and mountain pass "Touge" battles. Features customizable 16-bit cars and challenging nighttime circuits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('touhou-mario-1---imperishable-night', 'SNES', 'Touhou Mario 1 - Imperishable Night', '2017', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Touhou-themed Mario World modification.', 'Navigate the Mushroom Kingdom as Touhou characters.', 'Try Touhou Mario 1: Imperishable Night on SNES.', 'A creative 16-bit crossover. Replaces Mario assets with Touhou Project characters and music, featuring specialized bullet-pattern levels in 16-bit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tower-dream-japan', 'SNES', 'Tower Dream (Japan)', '1994', 'Puzzle', 'ASCII Corporation', '1', 'Tower-building puzzle', 'Real-estate board game simulation.', 'Build your 16-bit tower and defeat your rivals.', 'Experience Tower Dream on the Super Famicom.', 'A unique 16-bit tycoon board game. Manage finances and construction to build the most successful skyscraper while sabotaging your opponents'' plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-europe-enfrde', 'SNES', 'Toy Story (Europe) (En,Fr,De)', '1995', 'Platformer', 'Traveller''s Tales', '1', '2D side-scrolling', 'Pre-rendered action-platformer (Disney).', 'Rescue the 16-bit toys as Woody and Buzz.', 'Play Toy Story on the Super Nintendo.', 'A technical marvel on the SNES. Features impressive pre-rendered 16-bit graphics, a first-person stage, and gameplay that follows the movie''s plot perfectly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-japan', 'SNES', 'Toy Story (Japan)', '1995', 'Platformer', 'Traveller''s Tales', '1', '2D side-scrolling', 'Pre-rendered action (Japanese release).', 'Experience the 16-bit Disney classic in Japan.', 'Experience Toy Story on the Super Famicom.', 'The authentic Japanese release. Delivers the same high-quality 16-bit visuals and diverse gameplay, from platforming to high-speed RC racing segments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-usa', 'SNES', 'Toy Story (USA)', '1995', 'Platformer', 'Traveller''s Tales', '1', '2D side-scrolling', 'Pre-rendered action (USA release).', 'Journey "To Infinity and Beyond" in 16-bit.', 'Play Toy Story for the Super Nintendo.', 'Pushes the 16-bit hardware to its limit. Features large character sprites, amazing 16-bit color palettes, and a variety of levels based on the Pixar film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toys-europe', 'SNES', 'Toys (Europe)', '1993', 'Platformer', 'Ocean Software', '1', '2D side-scrolling', 'Isometric action and puzzle game (Movie tie-in).', 'Infiltrate the 16-bit Zevo toy factory.', 'Play Toys: Let the Toy Wars Begin on the SNES.', 'Based on the Robin Williams film. Features a unique 16-bit isometric view. Use specialized toy weapons like peanut butter bombs to stop the evil general.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toys-usa', 'SNES', 'Toys (USA)', '1993', 'Platformer', 'Ocean Software', '1', '2D side-scrolling', 'Isometric action (USA release).', 'Protect the world of 16-bit toys in the USA version.', 'Experience Toys on the Super Nintendo.', 'Explore the whimsical yet dangerous 16-bit factory. Solve environmental puzzles and use remote-controlled toys to defeat robotic enemies in this colorful 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('traverse---starlight-&-prairie-japan', 'SNES', 'Traverse - Starlight & Prairie (Japan)', '1996', 'RPG', 'Pandora Box', '1', 'Japanese-style RPG', 'Non-linear exploration RPG.', 'Travel the 16-bit world and forge your own path.', 'Play Traverse: Starlight & Prairie on Super Famicom.', 'A unique 16-bit RPG focusing on freedom and life-simulation elements. Explore a vast world where your choices and the passage of time affect the story and character relationships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('treasure-hunter-g-japan', 'SNES', 'Treasure Hunter G (Japan)', '1996', 'RPG', 'Sting', '1', 'Japanese-style RPG', 'Tactical turn-based RPG (Square).', 'Find the legendary treasure in this 16-bit epic.', 'Experience Treasure Hunter G on the Super Famicom.', 'The final Square-published title for the system. Features impressive pre-rendered 16-bit sprites and a unique grid-based combat system with high-fidelity audio.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('treasure-hunter-g-japan-en-by-metalhawk+obsolete-v10postbeta2', 'SNES', 'Treasure Hunter G (Japan) [En by Metalhawk+Obsolete v1.0PostBeta2]', '1996', 'RPG', 'Sting', '1', 'Japanese-style RPG', 'Tactical RPG (English Translation).', 'Play the Square classic in English for the first time.', 'Play Treasure Hunter G in English on the SNES.', 'The definitive 16-bit fan translation. Fully translates the humorous dialogue and deep tactical mechanics of this late-generation 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trinea-japan', 'SNES', 'Trinea (Japan)', '1993', 'Action-Adventure', 'Irem', '1', 'Top-down exploration', 'Hybrid of RPG and action.', 'Restore the 16-bit world through three different eras.', 'Experience Trinea on the Super Famicom.', 'Features three playable characters with distinct 16-bit gameplay styles. Navigate through a complex narrative that blends traditional RPG exploration with real-time combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('troddlers-europe', 'SNES', 'Troddlers (Europe)', '1993', 'Puzzle', 'Sales Curve', '2', 'Physics-based puzzle', 'Lemmings-style puzzle platformer.', 'Guide the 16-bit Troddlers to the exit safely.', 'Play Troddlers on the Super Nintendo.', 'A clever 16-bit puzzler. Use blocks to create paths and avoid traps. Features over 100 levels and a robust 2-player cooperative mode for shared 16-bit puzzle solving.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('troddlers-europe-beta', 'SNES', 'Troddlers (Europe) (Beta)', '1993', 'Puzzle', 'Sales Curve', '2', 'Physics-based puzzle', 'Puzzle platformer (Beta Version).', 'Test the early block-placement and AI logic.', 'Check out the Troddlers Beta on the Super Nintendo.', 'A rare 16-bit development look. Features prototype level layouts and early versions of the Troddler sprites and environmental interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('troddlers-usa', 'SNES', 'Troddlers (USA)', '1993', 'Puzzle', 'Sales Curve', '2', 'Physics-based puzzle', 'Puzzle platformer (USA release).', 'Master the 16-bit physics puzzles in the USA version.', 'Experience Troddlers for the Super Nintendo.', 'Combines quick thinking with precise platforming. Use the 16-bit environment to your advantage to rescue as many Troddlers as possible from hazardous stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('troy-aikman-nfl-football-europe', 'SNES', 'Troy Aikman NFL Football (Europe)', '1994', 'Sports', 'Leland Interactive Media', '2', 'American football', 'American Football simulation (Aikman).', 'Win the 16-bit Super Bowl in the European edition.', 'Play Troy Aikman NFL Football on the SNES.', 'Features an emphasis on simulation and strategy. Includes a deep 16-bit playbook and a specialized "Pro-Logic" system for realistic player AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('troy-aikman-nfl-football-usa', 'SNES', 'Troy Aikman NFL Football (USA)', '1994', 'Sports', 'Leland Interactive Media', '2', 'American football', 'American Football (USA release).', 'Lead your 16-bit team to victory with Troy Aikman.', 'Experience Troy Aikman NFL Football on the SNES.', 'Includes the 1994 NFL rosters and a robust season mode. A solid 16-bit sports title that focuses on the tactical side of professional football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('true-lies-europe', 'SNES', 'True Lies (Europe)', '1994', 'Action', 'Leland Interactive Media', '2', 'Isometric run and gun', 'Top-down cinematic action (True Lies).', 'Stop the terrorists and save your family in 16-bit.', 'Play True Lies on the Super Nintendo.', 'Based on the Schwarzenegger film. Features intense 16-bit gunplay, diverse missions, and impressive top-down graphics that capture the movie''s high-stakes action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('true-lies-germany', 'SNES', 'True Lies (Germany)', '1994', 'Action', 'Leland Interactive Media', '2', 'Isometric run and gun', 'Cinematic action (German release).', 'Spielen Sie die 16-bit Action von True Lies.', 'Erleben Sie True Lies auf dem SNES in Deutschland.', 'The official 16-bit German localization. Features the same explosive action and challenging missions, fully translated for the German-speaking 16-bit audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('true-lies-japan', 'SNES', 'True Lies (Japan)', '1994', 'Action', 'Leland Interactive Media', '2', 'Isometric run and gun', 'Cinematic action (Japanese release).', 'Experience the 16-bit movie tie-in in Japan.', 'Experience True Lies on the Super Famicom.', 'Known for its fluid 16-bit controls and detailed environments. Navigate through malls, parks, and secret bases in this faithful 16-bit arcade-style shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('true-lies-usa', 'SNES', 'True Lies (USA)', '1994', 'Action', 'Leland Interactive Media', '2', 'Isometric run and gun', 'Cinematic action (USA release).', 'Eliminate the "Crimson Jihad" in this 16-bit shooter.', 'Play True Lies for the Super Nintendo.', 'One of the most polished top-down shooters on the system. Use a variety of 16-bit weapons and cover mechanics to survive through the film-inspired levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('true-lies-usa-beta', 'SNES', 'True Lies (USA) (Beta)', '1994', 'Action', 'Leland Interactive Media', '2', 'Isometric run and gun', 'Cinematic action (USA Beta).', 'Explore the early 16-bit Arnold-style action.', 'Check out the True Lies Beta on the SNES.', 'A fascinating 16-bit development build. Features different enemy placements and prototype versions of the 16-bit weapon sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trump-island-japan', 'SNES', 'Trump Island (Japan)', '1994', 'Board Game', 'Pack-In-Video', '1', 'Turn-based board game', 'Board game and mini-game collection.', 'Conquer Trump Island in this 16-bit challenge.', 'Play Trump Island on the Super Famicom.', 'A colorful 16-bit board game featuring card-based movement and various humorous mini-games. Compete against the AI or friends in a race for 16-bit dominance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsukikomori-japan', 'SNES', 'Tsukikomori (Japan)', '1994', 'Adventure', 'Visit', '1', 'Story-driven adventure', 'Sound-novel horror mystery.', 'Survive the night in this 16-bit interactive story.', 'Experience Tsukikomori on the Super Famicom.', 'A chilling 16-bit sound novel from the creators of School Days. Features multiple branching paths and atmospheric 16-bit music and still-images.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuppari-oozumou---risshin-shusse-hen-japan', 'SNES', 'Tsuppari Oozumou - Risshin Shusse Hen (Japan)', '1994', 'Sports', 'Technos Japan', '2', 'Sumo wrestling', 'Traditional Sumo wrestling simulation.', 'Rise to the rank of Yokozuna in 16-bit sumo.', 'Play Tsuppari Oozumou on the Super Famicom.', 'Features a unique 16-bit RPG-style progression. Train your wrestler, master technical throws, and climb the ranks of the professional 16-bit sumo world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuri-tarou-japan', 'SNES', 'Tsuri Tarou (Japan)', '1994', 'Sports', 'ASCII Corporation', '1', 'Fishing simulation', 'Charming fishing simulation.', 'Catch the legendary 16-bit fish in the peaceful rivers.', 'Play Tsuri Tarou on the Super Famicom.', 'A relaxing 16-bit fishing game. Features beautiful 16-bit nature backgrounds and a variety of lures and equipment to master the art of 16-bit angling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuyoshi-shikkari-shinasai---taisen-puzzle-dama-japan', 'SNES', 'Tsuyoshi Shikkari Shinasai - Taisen Puzzle Dama (Japan)', '1994', 'Puzzle', 'Konami', '2', 'Competitive puzzle', 'Competitive puzzle game (Konami).', 'Match the 16-bit orbs to defeat your rivals.', 'Experience Taisen Puzzle Dama on Super Famicom.', 'Features the cast of the popular Japanese manga. A fast-paced 16-bit "falling object" puzzler with a heavy emphasis on chaining together massive combos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tuff-e-nuff-europe', 'SNES', 'Tuff E Nuff (Europe)', '1993', 'Fighting', 'Jaleco', '2', '2D competitive fighting', 'One-on-one fighting game (Europe).', 'Prove your strength in the 16-bit "Tuff E Nuff" arena.', 'Play Tuff E Nuff on the Super Nintendo.', 'Known as "Dead Dance" in Japan. Features large, detailed 16-bit sprites and a unique system where your character gains new moves as they progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tuff-e-nuff-usa', 'SNES', 'Tuff E Nuff (USA)', '1993', 'Fighting', 'Jaleco', '2', '2D competitive fighting', 'One-on-one fighting game (USA release).', 'Climb the 16-bit tower and defeat Jado.', 'Experience Tuff E Nuff for the Super Nintendo.', 'A gritty 16-bit post-apocalyptic fighter. Master the specialized movesets of Kotono, Syoh, and Zaki in this atmospheric 16-bit brawl.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turbo-toons-europe', 'SNES', 'Turbo Toons (Europe)', '1993', 'Racing', 'Electronic Arts', '2', 'Arcade racing', 'Top-down arcade racing (Hanna-Barbera).', 'Race the 16-bit Looney Tunes stars to the finish.', 'Play Turbo Toons on the Super Nintendo.', 'A frantic 16-bit racer from a top-down perspective. Features a variety of cartoon characters and power-ups for high-energy 16-bit racing fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turf-hero-japan', 'SNES', 'Turf Hero (Japan)', '1994', 'Sports', 'Taito', '2', 'Horse racing', 'Horse racing simulation (JRA licensed).', 'Master the 16-bit tracks in this professional sim.', 'Play Turf Hero on the Super Famicom.', 'Features realistic horse stats and 16-bit racing physics. A deep simulation that captures the excitement of Japanese horse racing in the 16-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turf-memories-japan', 'SNES', 'Turf Memories (Japan)', '1994', 'Sports', 'Koei', '1', 'Horse racing management', 'Horse racing and management.', 'Build a 16-bit racing legacy through the generations.', 'Experience Turf Memories on the Super Famicom.', 'Focuses on the long-term management of a racing stable. Includes 16-bit breeding mechanics and detailed season tracking for hardcore 16-bit racing fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turn-and-burn---no-fly-zone-europe', 'SNES', 'Turn and Burn - No-Fly Zone (Europe)', '1994', 'Shooter', 'Imagineering', '1', 'First-person flight shooter', 'Flight combat simulation (Carrier based).', 'Complete 16-bit missions from your aircraft carrier.', 'Play Turn and Burn: No-Fly Zone on the SNES.', 'Features a cockpit-view perspective and intense 16-bit dogfights. Master the difficult carrier landings in this technical 16-bit flight simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turn-and-burn---no-fly-zone-spain', 'SNES', 'Turn and Burn - No-Fly Zone (Spain)', '1994', 'Shooter', 'Imagineering', '1', 'First-person flight shooter', 'Flight combat simulation (Spanish release).', 'Domina los cielos de 16-bit en este simulador.', 'Juega a Turn and Burn en español para la SNES.', 'The official 16-bit Spanish localization. Features fully translated HUD and mission briefings, making the complex 16-bit aerial combat accessible to Spanish fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turn-and-burn---no-fly-zone-usa', 'SNES', 'Turn and Burn - No-Fly Zone (USA)', '1994', 'Shooter', 'Imagineering', '1', 'First-person flight shooter', 'Flight combat simulation (USA release).', 'Engage in 16-bit air superiority missions.', 'Experience Turn and Burn for the Super Nintendo.', 'A realistic 16-bit F-14 Tomcat simulator. Use radar, missiles, and 16-bit flight tactics to eliminate enemy threats in the "No-Fly Zone."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twinbee---rainbow-bell-adventure-english-translation', 'SNES', 'TwinBee - Rainbow Bell Adventure (English Translation)', '1993', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Side-scrolling action-adventure (Translation).', 'Journey through the 16-bit Rainbow Bell in English.', 'Play TwinBee: Rainbow Bell Adventure in English.', 'The complete 16-bit fan translation. Makes the charming story and diverse platforming levels of this TwinBee spin-off accessible to 16-bit fans worldwide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twinbee---rainbow-bell-adventure-japan', 'SNES', 'TwinBee - Rainbow Bell Adventure (Japan)', '1993', 'Platformer', 'Konami', '1', '2D side-scrolling', 'Side-scrolling action-adventure (TwinBee).', 'Restore the 16-bit peace as TwinBee, WinBee, or GwinBee.', 'Experience Rainbow Bell Adventure on Super Famicom.', 'A departure from the usual shmup style. Features vibrant 16-bit platforming, branching paths, and incredible 16-bit boss fights in a colorful world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twisted-tales-of-spike-mcfang-the-usa', 'SNES', 'Twisted Tales of Spike McFang, The (USA)', '1993', 'Action-Adventure', 'Solar', '1', 'Top-down action RPG', 'Action-RPG with a magical hat.', 'Defeat the zombie wizard in this quirky 16-bit quest.', 'Play Twisted Tales of Spike McFang on SNES.', 'A unique 16-bit RPG where you attack by spinning your cape and throwing your hat. Features a humorous story and vibrant 16-bit character designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ufo-kamen-yakisoban---kettler-no-kuroi-inbou---keihin-ban-japan', 'SNES', 'U.F.O. Kamen Yakisoban - Kettler no Kuroi Inbou - Keihin Ban (Japan)', '1996', 'Action', 'KID', '1', 'Action adventure', 'Bizarre action-platformer (Prize Edition).', 'Eat the 16-bit noodles and save the day.', 'Play U.F.O. Kamen Yakisoban (Keihin Ban) on SNES.', 'A rare 16-bit promotional version. Features the Japanese noodle mascot in a wacky 16-bit beat ''em up adventure with specialized 16-bit item placements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ufo-kamen-yakisoban---kettler-no-kuroi-inbou-japan', 'SNES', 'U.F.O. Kamen Yakisoban - Kettler no Kuroi Inbou (Japan)', '1996', 'Action', 'KID', '1', 'Action adventure', 'Bizarre action-platformer (Nissin Mascot).', 'Defeat Kettler in this 16-bit noodle-themed quest.', 'Experience U.F.O. Kamen Yakisoban on Super Famicom.', 'Control the hero of the fried noodles! Use unique 16-bit attacks to defeat food-themed villains in this colorful and surreal 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('un-squadron-europe', 'SNES', 'U.N. Squadron (Europe)', '1991', 'Shooter', 'Capcom', '2', 'Horizontal scrolling shooter', 'Side-scrolling shoot ''em up (Capcom).', 'Master the mercenary skies in this 16-bit classic.', 'Play U.N. Squadron on the Super Nintendo.', 'One of the greatest 16-bit shmups. Features an upgrade shop, multiple aircraft, and legendary 16-bit boss encounters based on the Area 88 manga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('un-squadron-usa', 'SNES', 'U.N. Squadron (USA)', '1991', 'Shooter', 'Capcom', '2', 'Horizontal scrolling shooter', 'Side-scrolling shoot ''em up (USA release).', 'Infiltrate the enemy desert base in 16-bit.', 'Experience U.N. Squadron for the Super Nintendo.', 'A technical 16-bit masterpiece. Choose your pilot and customize your 16-bit fighter jet with specialized secondary weapons to complete high-stakes missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uchuu-no-kishi-tekkaman-blade-japan', 'SNES', 'Uchuu no Kishi Tekkaman Blade (Japan)', '1994', 'Action', 'Bec', '1', '2D action platformer', 'Side-scrolling action (Tekkaman Blade).', 'Stop the Radam invasion in 16-bit combat.', 'Play Uchuu no Kishi Tekkaman Blade on Super Famicom.', 'Based on the sci-fi anime. Features fast-paced 16-bit action and flight segments, capturing the power and speed of the 16-bit Tekkaman armor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uchuu-no-kishi-tekkaman-blade-japan-beta', 'SNES', 'Uchuu no Kishi Tekkaman Blade (Japan) (Beta)', '1994', 'Action', 'Bec', '1', '2D action platformer', 'Side-scrolling action (Beta Version).', 'Explore the early 16-bit Tekkaman combat logic.', 'Check out the Tekkaman Blade Beta on the SNES.', 'A rare 16-bit development build. Features unfinished background layers and prototype versions of the 16-bit transform animations and sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uchuu-no-kishi-tekkaman-blade-japan-en-by-d-v10-~space-knight-tekkaman-blade', 'SNES', 'Uchuu no Kishi Tekkaman Blade (Japan) [En by D v1.0] (~Space Knight Tekkaman Blade)', '1994', 'Action', 'Bec', '1', '2D action platformer', 'Action-platformer (English Translation).', 'Enjoy the Tekkaman epic in English for 16-bit.', 'Play Space Knight Tekkaman Blade in English on SNES.', 'The complete 16-bit fan translation. Fully translates the story scenes and menus, allowing 16-bit fans to follow the tragic saga of D-Boy in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uchuu-race---astro-go!-go!-japan', 'SNES', 'Uchuu Race - Astro Go! Go! (Japan)', '1993', 'Racing', 'Namco', '2', 'Arcade racing', 'Top-down sci-fi arcade racing.', 'Race through the 16-bit galaxy in this quirky sim.', 'Experience Uchuu Race: Astro Go! Go! on SNES.', 'A colorful 16-bit racer from a top-down perspective. Features unique alien vehicles and imaginative 16-bit interplanetary tracks with a high focus on arcade fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima---kyouryuu-teikoku-japan', 'SNES', 'Ultima - Kyouryuu Teikoku (Japan)', '1990', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Top-down action RPG (Savage Empire).', 'Explore the Valley of Eodon and unite the tribes.', 'Play Ultima: Kyouryuu Teikoku on Super Famicom.', 'The Japanese 16-bit version of "The Savage Empire." A unique spin-off that swaps high fantasy for a prehistoric world filled with dinosaurs and tribal warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima---runes-of-virtue-ii-usa', 'SNES', 'Ultima - Runes of Virtue II (USA)', '1993', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Top-down action adventure.', 'Defeat the Black Knight and save Britannia in 16-bit.', 'Play Ultima: Runes of Virtue II on the SNES.', 'A more action-oriented take on the Ultima universe. Features dungeon crawling, puzzle solving, and real-time combat designed specifically for console play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima---runes-of-virtue-ii-usa-beta-1993-07-30', 'SNES', 'Ultima - Runes of Virtue II (USA) (Beta) (1993-07-30)', '1993', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Action adventure (Early Beta).', 'Test the initial dungeon layouts and NPC logic.', 'Check out the Runes of Virtue II Beta (1993) on SNES.', 'A rare 16-bit development build. Features placeholder text and early versions of the inventory management system from the Ultima spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima---runes-of-virtue-ii-usa-beta-1994-xx-xx', 'SNES', 'Ultima - Runes of Virtue II (USA) (Beta) (1994-XX-XX)', '1994', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Action adventure (Late Beta).', 'Explore the near-final 16-bit Britannia quest.', 'Check out the Runes of Virtue II Beta (1994) on SNES.', 'A more polished 16-bit prototype. Includes refined enemy AI and near-complete music tracks, offering a glimpse at the game''s final balancing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-gaiden---kuro-kishi-no-inbou-japan', 'SNES', 'Ultima Gaiden - Kuro Kishi no Inbou (Japan)', '1991', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Side-scrolling action RPG (Black Knight).', 'Stop the Black Knight''s conspiracy in 16-bit.', 'Play Ultima Gaiden on the Super Famicom.', 'A unique Japanese-exclusive entry. Focuses on side-scrolling combat and platforming while maintaining the narrative depth and world-building of the Ultima series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-vi---itsuwari-no-yogensha-japan', 'SNES', 'Ultima VI - Itsuwari no Yogensha (Japan)', '1991', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Isometric open-world RPG (Ultima VI).', 'Expose the false prophet and save the gargoyles.', 'Play Ultima VI on the Super Famicom.', 'A massive 16-bit translation of the PC classic. Explore a seamless world map, interact with hundreds of NPCs, and solve a deep, philosophical mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-vi---itsuwari-no-yogensha-japan-beta', 'SNES', 'Ultima VI - Itsuwari no Yogensha (Japan) (Beta)', '1991', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Open-world RPG (Beta Version).', 'Explore the early 16-bit world of Britannia.', 'Check out the Ultima VI Beta on the Super Famicom.', 'A rare look at the localization process. Features untranslated Japanese text strings and early versions of the icon-based interface.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-vi---the-false-prophet-usa', 'SNES', 'Ultima VI - The False Prophet (USA)', '1991', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Isometric open-world RPG (USA release).', 'Uncover the truth behind the gargoyle invasion.', 'Experience Ultima VI: The False Prophet on SNES.', 'One of the most ambitious RPGs on the system. Features a complex item interaction system and a vast world where every object can be manipulated.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-vii---the-black-gate-japan', 'SNES', 'Ultima VII - The Black Gate (Japan)', '1993', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Top-down RPG (The Black Gate).', 'Investigate a series of murders in 16-bit Britannia.', 'Play Ultima VII on the Super Famicom.', 'A condensed version of the legendary PC title. Features a real-time combat system and a dark, mature storyline involving a mysterious cult.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-vii---the-black-gate-usa', 'SNES', 'Ultima VII - The Black Gate (USA)', '1993', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Top-down RPG (USA release).', 'Stop the Guardian from entering the 16-bit world.', 'Experience Ultima VII: The Black Gate on SNES.', 'Known for its deep lore and atmospheric world. Navigate the political and magical landscape of Britannia to stop an ancient evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-vii---the-black-gate-usa-beta', 'SNES', 'Ultima VII - The Black Gate (USA) (Beta)', '1993', 'RPG', 'Origin Systems', '1', 'Japanese-style RPG', 'Top-down RPG (Beta Version).', 'Test the early real-time combat mechanics.', 'Check out the Ultima VII Beta on the Super Nintendo.', 'A 16-bit development slice. Shows early iterations of the party management menus and prototype versions of the spell-casting animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-fighter-usa', 'SNES', 'Ultimate Fighter (USA)', '1993', 'Fighting', 'IFC', '2', '2D competitive fighting', '2D fighting game with RPG elements.', 'Win the tournament and master the 16-bit arts.', 'Play Ultimate Fighter on the Super Nintendo.', 'Features a unique story mode where your character grows stronger. Combines traditional fighting mechanics with side-scrolling action sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-football-japan', 'SNES', 'Ultimate Football (Japan)', '1992', 'Sports', 'Capcom', '2', 'American football', 'American Football simulation (Japan).', 'Lead your team to 16-bit gridiron glory.', 'Play Ultimate Football on the Super Famicom.', 'A technical football sim with a focus on play-calling and player statistics. Features smooth 16-bit animations and a challenging season mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-mortal-kombat-3---redux', 'SNES', 'Ultimate Mortal Kombat 3 - Redux', '2020', 'Fighting', 'Fan Developer', '2', '2D competitive fighting', 'Fighting game (Fan Enhancement).', 'Play the ultimate 16-bit MK3 experience.', 'Try Ultimate Mortal Kombat 3 Redux on the SNES.', 'A high-quality fan modification. Restores cut content, adds new characters, and rebalances the gameplay for a more arcade-accurate 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-mortal-kombat-3-europe', 'SNES', 'Ultimate Mortal Kombat 3 (Europe)', '1995', 'Fighting', 'Midway', '2', '2D competitive fighting', 'One-on-one fighting game (Europe).', 'Finish your opponents in the ultimate 16-bit kontest.', 'Play Ultimate Mortal Kombat 3 on the SNES.', 'The definitive 16-bit entry. Features a massive roster of ninjas and cyborgs, lightning-fast gameplay, and the iconic "Fatality" finishing moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-mortal-kombat-3-usa', 'SNES', 'Ultimate Mortal Kombat 3 (USA)', '1995', 'Fighting', 'Midway', '2', '2D competitive fighting', 'One-on-one fighting game (USA release).', 'Master the kombat and become the 16-bit champion.', 'Experience UMK3 for the Super Nintendo.', 'Pushes the SNES hardware with digitized sprites and complex combos. Includes the "Kool Stuff" and "Scott''s Stuff" hidden menus for 16-bit customization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-mortal-kombat-3-deluxe', 'SNES', 'Ultimate Mortal Kombat 3 Deluxe', '2021', 'Fighting', 'Fan Developer', '2', '2D competitive fighting', 'Fighting game (Deluxe Modification).', 'Experience UMK3 with expanded features in 16-bit.', 'Try Ultimate Mortal Kombat 3 Deluxe on the SNES.', 'An advanced fan-made version. Includes extra stages, restored voice lines, and secret characters not found in the original 16-bit retail release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-baseball-jitsumei-ban-japan', 'SNES', 'Ultra Baseball Jitsumei Ban (Japan)', '1994', 'Sports', 'Culture Brain', '2', 'Baseball simulation', 'Realistic baseball simulation (Japan).', 'Win the pennant in this technical 16-bit sim.', 'Play Ultra Baseball Jitsumei Ban on Super Famicom.', 'Features the real names and stats of the Japanese pro league. A simulation-heavy 16-bit title for serious fans of the sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-baseball-jitsumei-ban-japan-en-by-vx-v104final', 'SNES', 'Ultra Baseball Jitsumei Ban (Japan) [En by VX v1.04Final]', '1994', 'Sports', 'Culture Brain', '2', 'Baseball simulation', 'Baseball simulation (English Translation).', 'Enjoy the realistic 16-bit baseball in English.', 'Play Ultra Baseball Jitsumei Ban in English.', 'The VX fan translation. Localizes the complex player statistics and menu options, making the Japanese pro league accessible to 16-bit fans worldwide.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-baseball-jitsumei-ban-2-japan', 'SNES', 'Ultra Baseball Jitsumei Ban 2 (Japan)', '1995', 'Sports', 'Culture Brain', '2', 'Baseball simulation', 'Enhanced baseball simulation sequel.', 'Master the 16-bit diamond in this realistic sequel.', 'Play Ultra Baseball Jitsumei Ban 2 on Super Famicom.', 'Features improved pitcher-batter physics and updated rosters. Offers a more refined 16-bit presentation of the Japanese professional baseball season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-baseball-jitsumei-ban-3-japan', 'SNES', 'Ultra Baseball Jitsumei Ban 3 (Japan)', '1996', 'Sports', 'Culture Brain', '2', 'Baseball simulation', 'Advanced baseball simulation finale.', 'Complete the 16-bit baseball trilogy in Japan.', 'Experience Ultra Baseball Jitsumei Ban 3 on SNES.', 'The most polished entry in the series. Features detailed animations for every play and the most comprehensive stat-tracking on the 16-bit system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-league---moero!-soccer-daikessen!!-japan', 'SNES', 'Ultra League - Moero! Soccer Daikessen!! (Japan)', '1993', 'Sports', 'Hudson Soft', '2', 'Soccer arcade', 'Turn-based soccer RPG (Ultra Series).', 'Lead the Ultraman soccer team to a 16-bit victory.', 'Play Ultra League on the Super Famicom.', 'A wacky 16-bit hybrid. Use special powers and tactical commands to win matches in a soccer league populated by Ultraman characters and kaiju.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-seven-japan', 'SNES', 'Ultra Seven (Japan)', '1995', 'Action', 'Bandai', '1', '2D action platformer', 'One-on-one fighting game (Ultra Seven).', 'Defeat the space monsters as the legendary 16-bit hero.', 'Play Ultra Seven on the Super Famicom.', 'Features cinematic combat and finishers accurate to the show. Battle iconic kaiju in detailed 16-bit urban environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultraman---towards-the-future-europe', 'SNES', 'Ultraman - Towards the Future (Europe)', '1991', 'Action', 'Bec', '1', '2D action platformer', 'One-on-one fighting game (Europe).', 'Save the Earth in this 16-bit Ultraman fighter.', 'Experience Ultraman: Towards the Future on SNES.', 'A challenging 16-bit fighter. Master Ultraman''s energy attacks to deplete the monster''s health and finish them with the iconic Specium Ray.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultraman---towards-the-future-usa', 'SNES', 'Ultraman - Towards the Future (USA)', '1991', 'Action', 'Bec', '1', '2D action platformer', 'One-on-one fighting game (USA release).', 'Battle the kaiju threat in 16-bit glory.', 'Play Ultraman: Towards the Future on the SNES.', 'Based on the Australian-produced series. Features large character sprites and high-stakes 16-bit battles against massive alien monsters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultraman-japan', 'SNES', 'Ultraman (Japan)', '1991', 'Action', 'Bec', '1', '2D action platformer', 'One-on-one fighting game (Japan).', 'Defeat the classic kaiju in the 16-bit original.', 'Experience the original Ultraman on Super Famicom.', 'The launch-window 16-bit fighter. Features a unique health system where you must "Finish" the monster once their bar is depleted to win the round.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('umi-no-nushi-tsuri-japan', 'SNES', 'Umi no Nushi Tsuri (Japan)', '1994', 'Simulation', 'Pack-In-Video', '1', 'Fishing simulation', 'Open-sea fishing simulation.', 'Catch the kings of the ocean in 16-bit.', 'Play Umi no Nushi Tsuri on the Super Famicom.', 'The ocean-based entry in the "Legend of the River King" series. Features RPG elements, beautiful 16-bit scenery, and a variety of sea life to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('umi-no-nushi-tsuri-japan-rev-a', 'SNES', 'Umi no Nushi Tsuri (Japan) (Rev A)', '1994', 'Simulation', 'Pack-In-Video', '1', 'Fishing simulation', 'Open-sea fishing (Revision A).', 'Master the 16-bit waves in the refined version.', 'Play Umi no Nushi Tsuri (Rev A) on Super Famicom.', 'The updated 16-bit retail release. Fixes minor bugs in the fish-hooking physics and optimizes the boat navigation on the 16-bit world map.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('umi-tsuri-meijin---suzuki-hen-japan', 'SNES', 'Umi Tsuri Meijin - Suzuki Hen (Japan)', '1994', 'Simulation', 'Pack-In-Video', '1', 'Fishing simulation', 'Sea fishing simulation (Suzuki Hen).', 'Become a 16-bit sea bass fishing master.', 'Experience Umi Tsuri Meijin on the Super Famicom.', 'A technical 16-bit sim focused on sea bass. Includes realistic equipment options and tidal physics to challenge experienced 16-bit anglers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('umihara-kawase-japan', 'SNES', 'Umihara Kawase (Japan)', '1994', 'Platformer', 'Miyako Bussan', '1', 'Physics-based platformer', 'Unique physics-based platformer.', 'Use your fishing line to swing through 16-bit levels.', 'Play the legendary Umihara Kawase on SNES.', 'A 16-bit cult classic. Master the incredible elastic physics of your fishing hook to navigate surreal levels and avoid strange aquatic enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('umihara-kawase-japan-en-by-satsu-v090', 'SNES', 'Umihara Kawase (Japan) [En by Satsu v0.90]', '1994', 'Platformer', 'Miyako Bussan', '1', 'Physics-based platformer', 'Physics-based platformer (English Patched).', 'Enjoy Umihara Kawase''s unique world in English.', 'Play Umihara Kawase in English on the SNES.', 'The fan-translated 16-bit version. Makes the menus and end-of-level statistics fully readable, allowing fans to focus on mastering the complex 16-bit swinging mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uncharted-waters---new-horizons-usa', 'SNES', 'Uncharted Waters - New Horizons (USA)', '1994', 'Strategy', 'Koei', '1', 'Naval trading simulation', 'Naval exploration and trading RPG.', 'Sail the seven seas and build a 16-bit empire.', 'Play Uncharted Waters: New Horizons on SNES.', 'A massive Koei masterpiece. Choose from six different characters and engage in trading, piracy, and exploration in a sprawling 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uncharted-waters-usa', 'SNES', 'Uncharted Waters (USA)', '1994', 'Strategy', 'Koei', '1', 'Naval trading simulation', 'Naval strategy and trading (Original).', 'Discover the 16-bit world in the first entry.', 'Experience Uncharted Waters on the Super Nintendo.', 'Set the foundation for the series. Manage your fleet, navigate real-world geography, and profit from the age of discovery in 16-bit detail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('undercover-cops-japan', 'SNES', 'Undercover Cops (Japan)', '1992', 'Action', 'Irem', '2', '2D beat ''em up', 'Side-scrolling beat ''em up (Irem).', 'Clean up the 16-bit post-apocalyptic streets.', 'Play Undercover Cops on the Super Famicom.', 'A gorgeous 16-bit arcade port. Features incredibly detailed sprite work, unique "food" health items, and satisfyingly brutal combat against weird 16-bit mutants.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uniracers-usa', 'SNES', 'Uniracers (USA)', '1994', 'Racing', 'Nintendo EAD', '2', 'Physics-based arcade racing', 'Unicycle racing and stunts (USA).', 'Race at high speed in this 16-bit unicycle sim.', 'Play the fast-paced Uniracers on the Super Nintendo.', 'A unique 16-bit title from DMA Design. Perform stunts to gain speed across winding, colorful 16-bit tracks in a race against the clock or a friend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('unirally-europe', 'SNES', 'Unirally (Europe)', '1994', 'Racing', 'Nintendo EAD', '2', 'Physics-based arcade racing', 'Unicycle racing (European release).', 'Perform stunts and win the 16-bit gold medal.', 'Experience Unirally on the Super Nintendo.', 'The European title for Uniracers. Known for its smooth 16-bit scrolling and addictive gameplay where style and speed go hand-in-hand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('universal-soldier-usa-proto', 'SNES', 'Universal Soldier (USA) (Proto)', '1992', 'Action', 'Probe Entertainment', '1', '2D action platformer', 'Side-scrolling action (Unreleased Proto).', 'Master the 16-bit cyborg combat in this prototype.', 'Try the Universal Soldier Prototype on the SNES.', 'A rare 16-bit look at a cancelled project. Based on the Turrican engine, featuring high-quality run-and-gun action and detailed cinematic 16-bit sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('untouchables-the-usa', 'SNES', 'Untouchables, The (USA)', '1991', 'Action', 'Ocean Software', '1', 'Top-down action', 'Multi-genre action game (The Untouchables).', 'Take down Al Capone in this 16-bit movie tie-in.', 'Play The Untouchables on the Super Nintendo.', 'Features a variety of 16-bit gameplay styles, from shooting galleries to side-scrolling action, recreating the most iconic scenes from the classic film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('urban-strike-europe', 'SNES', 'Urban Strike (Europe)', '1994', 'Action', 'Electronic Arts', '1', 'Isometric run and gun', 'Isometric helicopter combat (Urban Strike).', 'Stop a madman''s 16-bit plot across America.', 'Play Urban Strike on the Super Nintendo.', 'The final entry in the "Strike" trilogy. Features new 16-bit on-foot missions, diverse helicopter models, and massive isometric environments like Las Vegas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('urban-strike-usa', 'SNES', 'Urban Strike (USA)', '1994', 'Action', 'Electronic Arts', '1', 'Isometric run and gun', 'Isometric helicopter combat (USA release).', 'Protect the 16-bit USA from a high-tech threat.', 'Experience Urban Strike for the Super Nintendo.', 'A technical tour de force. Features impressive 16-bit explosions, complex mission objectives, and the most refined vehicle physics of the 16-bit series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('usa-ice-hockey-japan', 'SNES', 'USA Ice Hockey (Japan)', '1992', 'Sports', 'Human Entertainment', '2', 'Ice hockey', 'Arcade-style ice hockey (Japan).', 'Win the 16-bit hockey cup in the Japanese edition.', 'Play USA Ice Hockey on the Super Famicom.', 'A fast-paced 16-bit sports title. Features aggressive body-checking and smooth skating mechanics, providing a fun and accessible 16-bit hockey experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('usa-ice-hockey-japan-rev-a', 'SNES', 'USA Ice Hockey (Japan) (Rev A)', '1992', 'Sports', 'Human Entertainment', '2', 'Ice hockey', 'Arcade-style hockey (Japan Rev A).', 'Master the 16-bit ice in the refined Rev A.', 'Play USA Ice Hockey (Rev A) on the Super Famicom.', 'The updated 16-bit retail version. Fixes minor sprite flickering during crowded goal-mouth scrambles and optimizes the 16-bit AI defensive logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ushio-to-tora-japan', 'SNES', 'Ushio to Tora (Japan)', '1993', 'Action-Adventure', 'Toei Animation', '1', '2D action platformer', 'Side-scrolling action (Ushio to Tora).', 'Defeat the 16-bit demons with the Beast Spear.', 'Experience Ushio to Tora on the Super Famicom.', 'Based on the popular manga/anime. Features intense 16-bit boss fights and fast-paced action, capturing the powerful bond between the boy and the monster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('utopia---the-creation-of-a-nation-europe', 'SNES', 'Utopia - The Creation of a Nation (Europe)', '1994', 'Strategy', 'Bullfrog Productions', '1', 'Turn-based god simulation', 'Planetary management simulation (Utopia).', 'Colonize a new planet and ensure colony survival.', 'Play Utopia: The Creation of a Nation on SNES.', 'A deep 16-bit city-builder set in space. Manage oxygen, housing, and defense systems while fending off alien attacks in this strategic simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('utopia---the-creation-of-a-nation-germany', 'SNES', 'Utopia - The Creation of a Nation (Germany)', '1994', 'Strategy', 'Bullfrog Productions', '1', 'Turn-based god simulation', 'Planetary management (German release).', 'Erbaue eine neue Zivilisation in 16-Bit.', 'Erleben Sie Utopia auf Deutsch für das SNES.', 'The official 16-bit German localization. Manage resources and citizen happiness in a complex sci-fi setting, fully translated for German-speaking strategy fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('utopia---the-creation-of-a-nation-japan', 'SNES', 'Utopia - The Creation of a Nation (Japan)', '1994', 'Strategy', 'Bullfrog Productions', '1', 'Turn-based god simulation', 'Planetary management (Japanese release).', 'Lead your space colony to 16-bit prosperity.', 'Experience Utopia on the Super Famicom.', 'Known for its sophisticated UI and deep economic systems. Navigate the challenges of off-world colonization in this authentic 16-bit Japanese release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('utopia---the-creation-of-a-nation-usa', 'SNES', 'Utopia - The Creation of a Nation (USA)', '1994', 'Strategy', 'Bullfrog Productions', '1', 'Turn-based god simulation', 'Planetary management (USA release).', 'Build and protect the ultimate space colony.', 'Play Utopia for the Super Nintendo.', 'Balance military spending with civilian growth. Features a variety of alien planets to conquer and manage in this detailed 16-bit strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('utopia---the-creation-of-a-nation-usa-beta', 'SNES', 'Utopia - The Creation of a Nation (USA) (Beta)', '1994', 'Strategy', 'Bullfrog Productions', '1', 'Turn-based god simulation', 'Planetary management (USA Beta).', 'Explore early 16-bit colony building mechanics.', 'Check out the Utopia Beta on the Super Nintendo.', 'A rare 16-bit development build. Features prototype building designs and early versions of the alien attack logic and HUD layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('val-disere-championship-europe', 'SNES', 'Val d''Isere Championship (Europe)', '1994', 'Sports', 'Coki', '1', 'Ski racing', 'Skiing and snowboarding simulation.', 'Win the gold in the 16-bit Val d''Isere slopes.', 'Play Val d''Isere Championship on the SNES.', 'Features impressive pseudo-3D graphics. Compete in downhill, slalom, and freestyle events with fast-paced 16-bit action and realistic physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vegas-stakes-europe', 'SNES', 'Vegas Stakes (Europe)', '1993', 'Simulation', 'HAL Laboratory', '4', 'Casino gambling', 'Casino gambling simulation (Las Vegas).', 'Win $10 million in the 16-bit Vegas casinos.', 'Play Vegas Stakes on the Super Nintendo.', 'The sequel to Casino Kid. Features Blackjack, Poker, Craps, Roulette, and Slot Machines with a charming 16-bit story mode and multiplayer support.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vegas-stakes-usa', 'SNES', 'Vegas Stakes (USA)', '1993', 'Simulation', 'HAL Laboratory', '4', 'Casino gambling', 'Casino simulation (USA release).', 'Try your luck at the 16-bit high-stakes tables.', 'Experience Vegas Stakes for the Super Nintendo.', 'Travel through various high-end 16-bit casinos. Manage your bankroll and interact with diverse NPCs in this comprehensive digital casino experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('verne-world-japan', 'SNES', 'Verne World (Japan)', '1995', 'Adventure', 'System Sacom', '1', 'Story-driven adventure', 'Traditional JRPG (Jules Verne theme).', 'Explore a 16-bit world inspired by Jules Verne.', 'Experience Verne World on the Super Famicom.', 'A unique 16-bit RPG featuring characters and settings from "20,000 Leagues Under the Sea" and other classics. Includes a turn-based combat system and deep exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('viking-no-daimeiwaku-japan', 'SNES', 'Viking no Daimeiwaku (Japan)', '1994', 'Action-Adventure', 'Namco', '1', 'Comedy action adventure', 'Puzzle-action game (The Humans).', 'Guide your tribe to the end of each 16-bit level.', 'Play Viking no Daimeiwaku on the Super Famicom.', 'A Japanese release of "The Humans." Use specialized tools and 16-bit teamwork to help your prehistoric tribe navigate hazardous environments and solve puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-bart-europe', 'SNES', 'Virtual Bart (Europe)', '1994', 'Platformer', 'Sculptured Software', '1', '2D side-scrolling', 'Mini-game collection (The Simpsons).', 'Survive Bart''s 16-bit virtual reality nightmares.', 'Play Virtual Bart on the Super Nintendo.', 'Features diverse gameplay styles, from a baby-Bart platformer to a 16-bit "Road Rash" style motorcycle race through a post-apocalyptic Springfield.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-bart-japan', 'SNES', 'Virtual Bart (Japan)', '1994', 'Platformer', 'Sculptured Software', '1', '2D side-scrolling', 'Mini-game collection (Japanese release).', 'Experience the Simpsons'' 16-bit virtual chaos.', 'Experience Virtual Bart on the Super Famicom.', 'The official 16-bit Japanese port. Includes all the wacky mini-games and high-quality 16-bit voice clips from the original TV show cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-bart-usa', 'SNES', 'Virtual Bart (USA)', '1994', 'Platformer', 'Sculptured Software', '1', '2D side-scrolling', 'Mini-game collection (USA release).', 'Complete the 16-bit VR challenges as Bart Simpson.', 'Play Virtual Bart for the Super Nintendo.', 'Spin the virtual wheel to play different stages. Master the 16-bit tomato-throwing and dinosaur-survival levels in this humorous Simpsons adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-bart-usa-beta', 'SNES', 'Virtual Bart (USA) (Beta)', '1994', 'Platformer', 'Sculptured Software', '1', '2D side-scrolling', 'Mini-game collection (USA Beta).', 'Test the early 16-bit Simpsons VR mechanics.', 'Check out the Virtual Bart Beta on the SNES.', 'A rare 16-bit development look. Features unfinished background animations and prototype versions of the 16-bit sound effects for the baby-Bart level.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-soccer-europe', 'SNES', 'Virtual Soccer (Europe)', '1994', 'Sports', 'Taito', '2', 'Arcade soccer', 'Arcade-style soccer (Isometric).', 'Win the 16-bit world cup in Virtual Soccer.', 'Play Virtual Soccer on the Super Nintendo.', 'Features a unique isometric perspective and fast-paced 16-bit gameplay. Includes a wide range of national teams and customizable tournament modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-soccer-usa-proto', 'SNES', 'Virtual Soccer (USA) (Proto)', '1994', 'Sports', 'Taito', '2', 'Arcade soccer', 'Arcade-style soccer (Unreleased Proto).', 'Test the 16-bit isometric soccer physics.', 'Check out the Virtual Soccer USA Proto on SNES.', 'A rare look at a cancelled 16-bit US release. Features unfinished menu systems but fully playable 16-bit soccer matches with smooth sprite scaling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-wars-japan', 'SNES', 'Virtual Wars (Japan)', '1992', 'Shooter', 'NCS', '1', 'Top-down shooter', 'Futuristic action (Cyberpunk).', 'Jack into the 16-bit matrix and defeat the virus.', 'Experience Virtual Wars on the Super Famicom.', 'A 16-bit action title with a heavy sci-fi aesthetic. Navigate through digital landscapes and engage in fast-paced 16-bit combat against corrupted programs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('volleyball-twin-japan', 'SNES', 'Volleyball Twin (Japan)', '1994', 'Sports', 'Masaya', '2', 'Arcade volleyball', 'Arcade volleyball simulation.', 'Master the 16-bit court in this twin-team sim.', 'Play Volleyball Twin on the Super Famicom.', 'Features a focus on cooperative 16-bit play. Master the timing for spikes and blocks across various international 16-bit volleyball arenas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vortex-europe-enes', 'SNES', 'Vortex (Europe) (En,Es)', '1993', 'Shooter', 'Argonaut Games', '1', 'Polygonal rail shooter', '3D tank combat (Super FX chip).', 'Pilot the morphing 16-bit V-Wing through 3D zones.', 'Play Vortex on the Super Nintendo.', 'One of the few games to utilize the Super FX chip for 3D polygons. Transform your 16-bit mech into a walker, tank, or jet to navigate complex 3D environments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vortex-japan', 'SNES', 'Vortex (Japan)', '1993', 'Shooter', 'Argonaut Games', '1', 'Polygonal rail shooter', '3D tank combat (Japanese release).', 'Experience the 16-bit 3D polygon power of Vortex.', 'Experience Vortex on the Super Famicom.', 'A technical marvel for its time. Features challenging 3D exploration and combat, pushing the 16-bit hardware to create a unique polygonal world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vortex-usa-enes', 'SNES', 'Vortex (USA) (En,Es)', '1993', 'Shooter', 'Argonaut Games', '1', 'Polygonal rail shooter', '3D tank combat (USA release).', 'Defeat the Aki-Do forces in this 16-bit 3D epic.', 'Play the Super FX classic Vortex on the SNES.', 'Transform and fight through 16-bit 3D landscapes. Use your different forms strategically to solve environmental puzzles and defeat massive polygonal bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vs-collection-japan', 'SNES', 'Vs. Collection (Japan)', '1996', 'Compilation', 'Bottom Up', '2', 'Game compilation', 'Classic board game collection.', 'Win at 16-bit Chess, Checkers, and more.', 'Experience Vs. Collection on the Super Famicom.', 'A comprehensive 16-bit suite of classic board games. Features various difficulty levels and clean 16-bit graphics for a relaxing mental challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagan-paradise-japan', 'SNES', 'Wagan Paradise (Japan)', '1995', 'Action-Platformer', 'Hudson Soft', '1', '2D side-scrolling', 'Action-platformer with sound bubbles.', 'Save the Wagan Kingdom in this 16-bit paradise.', 'Play Wagan Paradise on the Super Famicom.', 'The most visually impressive 16-bit Wagan title. Features beautiful graphics, creative mini-game boss battles, and charming 16-bit platforming action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waialae-country-club-usa', 'SNES', 'Waialae Country Club (USA)', '1994', 'Sports', 'T&E Soft', '1', 'Golf simulation', 'Realistic golf simulation (Waialae).', 'Tee off at the 16-bit Hawaii country club.', 'Play Waialae Country Club on the Super Nintendo.', 'Features digitized 16-bit graphics of the real-world course. Manage wind, club selection, and green slope in this technical 16-bit golf sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waialae-no-kiseki-japan', 'SNES', 'Waialae no Kiseki (Japan)', '1994', 'Sports', 'T&E Soft', '1', 'Golf simulation', 'Golf simulation (Japanese version).', 'Master the 16-bit Waialae greens in Japan.', 'Experience Waialae no Kiseki on Super Famicom.', 'A faithful 16-bit recreation of the famous Hawaiian golf course. Offers deep mechanics and a realistic 16-bit golfing experience for fans of the sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wakataka-oozumou---yume-no-kyoudai-taiketsu-japan', 'SNES', 'Wakataka Oozumou - Yume no Kyoudai Taiketsu (Japan)', '1994', 'Sports', 'Technos Japan', '2', 'Sumo wrestling', 'Sumo wrestling simulation (Wakataka).', 'Lead the 16-bit sumo brothers to the top.', 'Play Wakataka Oozumou on the Super Famicom.', 'Focuses on the legendary brothers Wakanohana and Takanohana. Features technical 16-bit sumo combat and a deep career management mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wakuwaku-ski-wonder-spur-japan', 'SNES', 'Wakuwaku Ski Wonder Spur (Japan)', '1995', 'Sports', 'Human Entertainment', '1', 'Ski simulation', 'Downhill skiing simulation.', 'Race down the 16-bit mountains in Wonder Spur.', 'Experience Wakuwaku Ski on the Super Famicom.', 'A fun and accessible 16-bit skiing game. Features colorful graphics, varied weather conditions, and high-speed 16-bit downhill competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wally-o-sagase!---ehon-no-kuni-no-daibouken-japan', 'SNES', 'Wally o Sagase! - Ehon no Kuni no Daibouken (Japan)', '1995', 'Adventure', 'Namco', '1', 'Hidden object adventure', 'Hidden object and mini-games (Waldo).', 'Find Waldo in the 16-bit Picture Lands.', 'Play Wally o Sagase! on the Super Famicom.', 'The Japanese version of "Where''s Waldo?". Features detailed 16-bit crowd scenes and various interactive mini-games based on the popular book series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('war-2410-usa', 'SNES', 'War 2410 (USA)', '1994', 'Strategy', 'Advanced Productions', '1', 'Turn-based strategy', 'Turn-based hex-grid strategy (War 2410).', 'Lead your 16-bit army to victory in the future.', 'Play War 2410 for the Super Nintendo.', 'A deep sci-fi strategy game. Command tanks, infantry, and air units on a 16-bit hex-based map to outmaneuver the enemy forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('war-3010---the-revolution-usa', 'SNES', 'War 3010 - The Revolution (USA)', '1994', 'Strategy', 'Advanced Productions', '1', 'Turn-based strategy', 'Turn-based strategy sequel (War 3010).', 'Command the 16-bit revolutionary forces in space.', 'Experience War 3010 for the Super Nintendo.', 'Expands the strategy to intergalactic warfare. Features a complex 16-bit resource management system and challenging turn-based tactical combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waratte-iitomo!-tamorin-pick-japan', 'SNES', 'Waratte Iitomo! Tamorin Pick (Japan)', '1993', 'Variety', 'Namco', '2', 'TV show mini-games', 'Variety show mini-game collection.', 'Play through the 16-bit "Tamorin" variety games.', 'Play Waratte Iitomo! on the Super Famicom.', 'Based on the popular Japanese TV show. Features the celebrity Tamori and a variety of 16-bit comedic mini-games for up to four players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wares-la-japan', 'SNES', 'Wares, La (Japan)', '1996', 'Puzzle', 'Nichibutsu', '1', 'Tile-based puzzle', 'Turn-based strategy RPG (The War).', 'Conquer the 16-bit fantasy world of La Wares.', 'Experience La Wares on the Super Famicom.', 'A tactical 16-bit RPG with a focus on unit management and story-driven missions. Navigate a complex political narrative in a vibrant 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warios-adventure-by-retrodeath', 'SNES', 'Wario''s Adventure by Retrodeath', '2020', 'Platformer', 'Fan Developer', '1', '2D side-scrolling', 'Fan-made Mario World modification.', 'Go on a greedy 16-bit adventure with Wario.', 'Try Wario''s Adventure on the Super Nintendo.', 'A high-quality 16-bit romhack featuring Wario as the protagonist. Includes custom 16-bit moves, new levels, and a focus on collecting coins.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warios-woods-europe', 'SNES', 'Wario''s Woods (Europe)', '1994', 'Puzzle', 'Nintendo R&D1', '2', 'Action puzzle', 'Falling-block puzzle game (Nintendo).', 'Stack and clear the monsters in 16-bit.', 'Play Wario''s Woods on the Super Nintendo.', 'The final official 16-bit US release for SNES. A unique 16-bit puzzler where you control Toad on the field to arrange bombs and enemies into lines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warios-woods-usa', 'SNES', 'Wario''s Woods (USA)', '1994', 'Puzzle', 'Nintendo R&D1', '2', 'Action puzzle', 'Puzzle action (USA release).', 'Help Toad defeat Wario in this 16-bit puzzle duel.', 'Experience Wario''s Woods for the Super Nintendo.', 'Features a competitive 2-player mode and challenging 16-bit logic puzzles. A masterclass in 16-bit puzzle design with vibrant Nintendo characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warlock-europe', 'SNES', 'Warlock (Europe)', '1995', 'Action', 'Realtime Associates', '1', '2D action platformer', 'Side-scrolling action (Movie tie-in).', 'Defeat the warlock and save the 16-bit future.', 'Play Warlock on the Super Nintendo.', 'Based on the horror film series. Features atmospheric 16-bit levels, magical combat, and a quest to recover the six ancient stones in 16-bit detail.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warlock-japan', 'SNES', 'Warlock (Japan)', '1995', 'Action', 'Realtime Associates', '1', '2D action platformer', 'Side-scrolling action (Japanese release).', 'Master the 16-bit magic in the Japanese version.', 'Experience Warlock on the Super Famicom.', 'Delivers the same dark 16-bit atmosphere and challenging platforming. Battle through diverse historical eras using a variety of 16-bit spells.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warlock-usa', 'SNES', 'Warlock (USA)', '1995', 'Action', 'Realtime Associates', '1', '2D action platformer', 'Side-scrolling action (USA release).', 'Stop the Warlock''s 16-bit ritual across time.', 'Play Warlock for the Super Nintendo.', 'A gritty 16-bit action-platformer. Features impressive special effects for the era and a high difficulty curve that rewards 16-bit platforming precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warlock-usa-beta-0556', 'SNES', 'Warlock (USA) (Beta) [0556]', '1995', 'Action', 'Realtime Associates', '1', '2D action platformer', 'Action-platformer (Beta 0556).', 'Explore early 16-bit magic and level layouts.', 'Check out Warlock Beta [0556] on the SNES.', 'A 16-bit development slice. Features different orb physics and prototype versions of the historical background tiles in 16-bit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warlock-usa-beta-9fb9', 'SNES', 'Warlock (USA) (Beta) [9FB9]', '1995', 'Action', 'Realtime Associates', '1', '2D action platformer', 'Action-platformer (Beta 9FB9).', 'Test the near-final 16-bit Warlock combat.', 'Check out Warlock Beta [9FB9] on the SNES.', 'A later 16-bit development build. Includes more polished sound effects and near-complete enemy placements for the 16-bit campaign.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warp-speed-europe', 'SNES', 'Warp Speed (Europe)', '1992', 'Simulation', 'Accolade', '1', 'Space flight simulation', 'First-person space combat (Warp Speed).', 'Protect the 16-bit galaxy in your starfighter.', 'Play Warp Speed on the Super Nintendo.', 'A cockpit-view 16-bit space sim. Features 3D-style navigation, resource management, and intense dogfights against 16-bit alien fleets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('warp-speed-usa', 'SNES', 'Warp Speed (USA)', '1992', 'Simulation', 'Accolade', '1', 'Space flight simulation', 'Space combat simulation (USA release).', 'Defeat the alien invaders in 16-bit deep space.', 'Experience Warp Speed for the Super Nintendo.', 'Choose from different 16-bit starships and complete non-linear missions. A technical 16-bit title that emphasizes strategic space travel and combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waterworld-europe', 'SNES', 'Waterworld (Europe)', '1995', 'Action', 'Ocean Software', '1', '2D action platformer', 'Isometric survival action (Waterworld).', 'Protect the 16-bit Atoll from the Smokers.', 'Experience Waterworld on the Super Nintendo.', 'Based on the Kevin Costner film. Control the Mariner''s 16-bit trimaran in isometric combat and engage in on-foot missions to save the 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzky-and-the-nhlpa-all-stars-usa', 'SNES', 'Wayne Gretzky and the NHLPA All-Stars (USA)', '1992', 'Sports', 'Bethesda Softworks', '2', 'Ice hockey', 'Arcade ice hockey simulation.', 'Win the 16-bit Stanley Cup with Gretzky.', 'Play Wayne Gretzky and the NHLPA All-Stars on SNES.', 'Features the endorsement of "The Great One." A fast-paced 16-bit hockey title with a focus on arcade-style shooting, large player sprites, and smooth on-ice movement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wayne-gretzky-and-the-nhlpa-all-stars-usa-beta', 'SNES', 'Wayne Gretzky and the NHLPA All-Stars (USA) (Beta)', '1992', 'Sports', 'Bethesda Softworks', '2', 'Ice hockey', 'Arcade ice hockey (Beta).', 'Test the 16-bit skating and shooting physics.', 'Check out the Gretzky NHLPA Beta on the SNES.', 'A rare 16-bit development build. Features prototype menu screens and early iterations of the player AI and goalie reaction logic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waynes-world-europe', 'SNES', 'Wayne''s World (Europe)', '1993', 'Platformer', 'Radical Entertainment', '1', '2D side-scrolling', 'Side-scrolling action-adventure.', 'Master the 16-bit rock and roll world.', 'Play Wayne''s World on the Super Nintendo.', 'Based on the SNL movie. Control Wayne and Garth in a 16-bit quest through surreal levels, using guitars to blast enemies in a quest to save their TV show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('waynes-world-usa', 'SNES', 'Wayne''s World (USA)', '1993', 'Platformer', 'Radical Entertainment', '1', '2D side-scrolling', 'Action-adventure (USA release).', 'Party on in this 16-bit movie tie-in.', 'Experience Wayne''s World for the Super Nintendo.', 'A wacky 16-bit platformer filled with references to the film. Navigate through the music store and donut shop while battling bizarre 16-bit bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wcw-super-brawl-wrestling-usa', 'SNES', 'WCW Super Brawl Wrestling (USA)', '1994', 'Sports', 'Probe Entertainment', '2', 'Arcade wrestling', 'Professional wrestling simulation.', 'Become the 16-bit WCW heavyweight champion.', 'Play WCW Super Brawl Wrestling on the SNES.', 'Features 16-bit recreations of legends like Ric Flair and Sting. Includes a unique "cinema-style" view for special moves and high-energy wrestling action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('were-back!---a-dinosaurs-story-europe', 'SNES', 'We''re Back! - A Dinosaur''s Story (Europe)', '1993', 'Platformer', 'Imagitec Design', '1', '2D platformer', 'Side-scrolling platformer (Dinosaurs).', 'Guide Rex to the 16-bit museum safely.', 'Play We''re Back! A Dinosaur''s Story on SNES.', 'Based on the animated film. Control a friendly dinosaur in a 16-bit adventure, using tail-swipes and power-ups to navigate the streets of New York.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('were-back!---a-dinosaurs-story-usa', 'SNES', 'We''re Back! - A Dinosaur''s Story (USA)', '1993', 'Platformer', 'Imagitec Design', '1', '2D platformer', 'Action-platformer (USA release).', 'Protect your dino-friends in 16-bit.', 'Experience We''re Back! for the Super Nintendo.', 'Features vibrant 16-bit graphics and accessible gameplay. Navigate through diverse levels while avoiding the evil Professor Screweyes and his traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('weapon-lord-europe', 'SNES', 'Weapon Lord (Europe)', '1995', 'Fighting', 'Visual Concepts', '2', 'Weapon-based fighting', 'Weapon-based 2D fighting game.', 'Conquer the 16-bit arena in this brutal fighter.', 'Play WeaponLord on the Super Nintendo.', 'A technical 16-bit powerhouse. Features a deep parry system, weapon-breaking mechanics, and large, barbarian-themed sprites in a dark fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('weapon-lord-usa', 'SNES', 'Weapon Lord (USA)', '1995', 'Fighting', 'Visual Concepts', '2', 'Weapon-based fighting', 'Weapon-based fighting (USA release).', 'Master the 16-bit blade in the USA version.', 'Experience WeaponLord for the Super Nintendo.', 'Often cited as a precursor to modern weapon fighters. Features complex combos and "death moves" in a high-intensity 16-bit competitive environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wedding-peach-japan', 'SNES', 'Wedding Peach (Japan)', '1993', 'Action', 'Shin-Ei Animation', '1', '2D action adventure', 'Competitive puzzle game (Anime).', 'Win the 16-bit battle for love and beauty.', 'Play Wedding Peach on the Super Famicom.', 'Based on the "magical girl" anime. Features various 16-bit mini-games and a competitive puzzle mode with charming animations and character voices.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wheel-of-fortune---deluxe-edition-usa', 'SNES', 'Wheel of Fortune - Deluxe Edition (USA)', '1994', 'Game Show', 'GameTek', '2', 'TV game show', 'TV show word-puzzle simulation.', 'Solve the 16-bit phrases and win big.', 'Play Wheel of Fortune Deluxe on the SNES.', 'The ultimate 16-bit version of the classic game show. Features thousands of new puzzles, improved 16-bit digitized graphics, and Vanna White''s likeness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wheel-of-fortune-usa', 'SNES', 'Wheel of Fortune (USA)', '1992', 'Game Show', 'GameTek', '2', 'TV game show', 'TV show puzzle (USA release).', 'Spin the 16-bit wheel and avoid the bankrupt.', 'Experience Wheel of Fortune for the Super Nintendo.', 'Compete against friends or AI in this faithful 16-bit recreation. Test your word-solving skills across hundreds of categories in a classic TV format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('where-in-the-world-is-carmen-sandiego-europe-enfrdeesit', 'SNES', 'Where in the World is Carmen Sandiego (Europe) (En,Fr,De,Es,It)', '1991', 'Educational', 'Broderbund', '1', 'Geography adventure', 'Educational geography adventure.', 'Track down the 16-bit master thief globally.', 'Play Where in the World is Carmen Sandiego on SNES.', 'An educational 16-bit classic. Use geographical clues to track Carmen''s gang across the globe, learning facts while solving the 16-bit mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('where-in-the-world-is-carmen-sandiego-usa', 'SNES', 'Where in the World is Carmen Sandiego (USA)', '1991', 'Educational', 'Broderbund', '1', 'Geography adventure', 'Educational mystery (USA release).', 'Recover the 16-bit stolen treasures.', 'Experience Carmen Sandiego for the Super Nintendo.', 'Combines investigative work with geographical knowledge. A polished 16-bit title that makes learning about world cultures and locations fun and engaging.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('where-in-time-is-carmen-sandiego-usa', 'SNES', 'Where in Time is Carmen Sandiego (USA)', '1993', 'Educational', 'Broderbund', '1', 'Time-travel adventure', 'Educational time-travel mystery.', 'Catch Carmen Sandiego across 16-bit history.', 'Play Where in Time is Carmen Sandiego on SNES.', 'Travel from Ancient Egypt to the future in this 16-bit educational quest. Solve historical puzzles and track clues through different eras to catch the thief.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('whirlo-europe', 'SNES', 'Whirlo (Europe)', '1992', 'Platformer', 'Core Design', '1', '2D side-scrolling', 'Atmospheric action-platformer.', 'Survive the 16-bit journey of the Valkyrie.', 'Experience the rare Whirlo on the Super Nintendo.', 'A cult classic known for its high difficulty and dark fairy-tale atmosphere. Guide the protagonist through 16-bit hazards using specialized jump and dive moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('whizz-europe', 'SNES', 'Whizz (Europe)', '1993', 'Platformer', 'Flair Software', '1', '2D platformer', 'Isometric racing and platforming.', 'Race against the 16-bit clock as Whizz the rabbit.', 'Play Whizz on the Super Nintendo.', 'Features a unique isometric perspective. Navigate through colorful 16-bit obstacle courses, utilizing speed and precise jumps to reach the finish line.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('whizz-usa', 'SNES', 'Whizz (USA)', '1993', 'Platformer', 'Flair Software', '1', '2D platformer', 'Isometric racing (USA release).', 'Master the 16-bit isometric tracks.', 'Experience Whizz for the Super Nintendo.', 'A fast-paced 16-bit title with a focus on timing and pathfinding. Explore diverse environments while managing a strict 16-bit time limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wicked-18-usa', 'SNES', 'Wicked 18 (USA)', '1993', 'Sports', 'Accolade', '4', 'Golf simulation', 'Technical golf simulation.', 'Master the "wicked" 16-bit fantasy courses.', 'Play Wicked 18 on the Super Nintendo.', 'A spin-off of the True Golf series. Features surreal and challenging 16-bit course designs with the high-quality physics the engine is known for.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-guns-europe', 'SNES', 'Wild Guns (Europe)', '1994', 'Shooter', 'Natsume', '2', 'Arcade run and gun', 'Steampunk gallery shooter.', 'Blast your way through the 16-bit robotic West.', 'Play the legendary Wild Guns on the Super Nintendo.', 'A 16-bit masterpiece. Combines shooting-gallery action with dodging mechanics. Features incredible 16-bit sprite work, co-op play, and massive mechanical bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-guns-japan', 'SNES', 'Wild Guns (Japan)', '1994', 'Shooter', 'Natsume', '2', 'Arcade run and gun', 'Steampunk gallery shooter (Japan).', 'Protect the 16-bit frontier in the Japanese original.', 'Experience Wild Guns on the Super Famicom.', 'The authentic Natsume classic. Known for its perfect 16-bit balancing and high-octane action. A must-play for fans of arcade-style 16-bit shooters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-guns-japan-beta', 'SNES', 'Wild Guns (Japan) (Beta)', '1994', 'Shooter', 'Natsume', '2', 'Arcade run and gun', 'Gallery shooter (Beta Version).', 'Explore the early 16-bit steampunk assets.', 'Check out the Wild Guns Beta on the Super Famicom.', 'A rare 16-bit development slice. Features unfinished background layers and prototype versions of the iconic 16-bit robot animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-guns-japan-sample', 'SNES', 'Wild Guns (Japan) (Sample)', '1994', 'Shooter', 'Natsume', '2', 'Arcade run and gun', 'Gallery shooter (Sample Version).', 'Test the 16-bit aiming and dodging mechanics.', 'Check out the Wild Guns Sample on the Super Famicom.', 'A 16-bit promotional build. Includes the first few stages and showcases the fluid 16-bit movement and shooting that made the game a legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-guns-usa', 'SNES', 'Wild Guns (USA)', '1994', 'Shooter', 'Natsume', '2', 'Arcade run and gun', 'Steampunk gallery shooter (USA).', 'Stop the Kid gang in this 16-bit arcade hit.', 'Play Wild Guns for the Super Nintendo.', 'Take control of Clint or Annie in this definitive 16-bit shooter. Master the lasso and special weapons to clear the 16-bit screen of robotic outlaws.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-snake-usa', 'SNES', 'Wild Snake (USA)', '1994', 'Puzzle', 'Sales Curve Interactive', '2', 'Action puzzle', 'Falling-block puzzle game.', 'Match the 16-bit snakes and clear the board.', 'Play Wild Snake on the Super Nintendo.', 'A unique 16-bit puzzler endorsed by Alexey Pajitnov. Use slithering snake pieces to clear blocks in a creative departure from the Tetris formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-trax-japan', 'SNES', 'Wild Trax (Japan)', '1993', 'Racing', 'Nintendo EAD', '2', 'Polygonal racing', '3D stunt racing (Super FX chip).', 'Race the 16-bit polygonal cars on Wild Trax.', 'Experience Wild Trax on the Super Famicom.', 'Known as "Stunt Race FX" in the West. Uses the Super FX chip to create 3D 16-bit racing environments with physics-based car behavior and personality.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wile-e-coyotes-revenge-europe-proto', 'SNES', 'Wile E Coyote''s Revenge (Europe) (Proto)', '1994', 'Platformer', 'Virgin Interactive', '1', '2D action platformer', 'Side-scrolling action (Unreleased Proto).', 'Catch the Road Runner in this 16-bit prototype.', 'Try Wile E Coyote''s Revenge on the Super Nintendo.', 'A rare 16-bit look at a Looney Tunes project. Features various ACME gadgets and fast-paced 16-bit platforming through the iconic desert landscapes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('williams-arcades-greatest-hits-europe', 'SNES', 'Williams Arcade''s Greatest Hits (Europe)', '1996', 'Compilation', 'Digital Eclipse', '2', 'Classic arcade compilation', 'Arcade classic collection.', 'Play the 16-bit ports of arcade legends.', 'Experience Williams Arcade''s Greatest Hits on SNES.', 'A nostalgic 16-bit compilation. Includes pixel-perfect ports of Defender, Joust, Robotron: 2084, Sinistar, and Bubbles in one 16-bit package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('williams-arcades-greatest-hits-usa', 'SNES', 'Williams Arcade''s Greatest Hits (USA)', '1996', 'Compilation', 'Digital Eclipse', '2', 'Classic arcade compilation', 'Arcade collection (USA release).', 'Relive the golden age of arcades in 16-bit.', 'Play Williams Arcade''s Greatest Hits on the SNES.', 'The definitive 16-bit home versions of classic arcade titles. Features high-quality sound and accurate 16-bit gameplay for these historical gems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander---the-secret-missions-europe', 'SNES', 'Wing Commander - The Secret Missions (Europe)', '1992', 'Simulation', 'Origin Systems', '1', 'Space combat simulator', 'Space combat simulation (Expansion).', 'Continue the 16-bit war against the Kilrathi.', 'Play Wing Commander: Secret Missions on the SNES.', 'A massive 16-bit expansion. Features new, high-difficulty missions and an expanded storyline for the legendary 16-bit space combat flight sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander---the-secret-missions-europe-beta', 'SNES', 'Wing Commander - The Secret Missions (Europe) (Beta)', '1992', 'Simulation', 'Origin Systems', '1', 'Space combat simulator', 'Space combat (Secret Missions Beta).', 'Explore the early 16-bit Kilrathi campaign.', 'Check out the Secret Missions Beta on the SNES.', 'A rare 16-bit development look at the expansion. Features prototype mission briefings and early 16-bit sprite scaling for the new enemy ships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander---the-secret-missions-usa', 'SNES', 'Wing Commander - The Secret Missions (USA)', '1992', 'Simulation', 'Origin Systems', '1', 'Space combat simulator', 'Space combat (USA Expansion).', 'Protect the 16-bit galaxy in these elite missions.', 'Experience Secret Missions for the Super Nintendo.', 'Pushes your 16-bit piloting skills to the limit. Navigate through complex nebulae and engage in large-scale 16-bit space battles.');
