INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander-germany', 'SNES', 'Wing Commander (Germany)', '1991', 'Simulation', 'Origin Systems', '1', 'Space combat simulator', 'Space combat (German release).', 'Kämpfen Sie im 16-bit Weltraum gegen die Kilrathi.', 'Spielen Sie Wing Commander auf Deutsch für das SNES.', 'The official 16-bit German localization. Experience the epic space opera with fully translated menus and dialogue in this technical 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander-japan', 'SNES', 'Wing Commander (Japan)', '1991', 'Simulation', 'Origin Systems', '1', 'Space combat simulator', 'Space combat (Japanese release).', 'Experience the 16-bit space epic in Japan.', 'Experience Wing Commander on the Super Famicom.', 'Known for its impressive 16-bit scaling effects and deep narrative. A faithful port of the PC classic tailored for the 16-bit console audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-commander-usa', 'SNES', 'Wing Commander (USA)', '1991', 'Simulation', 'Origin Systems', '1', 'Space combat simulator', 'Space combat (USA release).', 'Become a 16-bit ace pilot in the USA version.', 'Play Wing Commander for the Super Nintendo.', 'The foundational 16-bit space sim. Manage your wingman, upgrade your 16-bit fighter, and climb the ranks to defeat the Kilrathi threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wings-2---aces-high-usa', 'SNES', 'Wings 2 - Aces High (USA)', '1992', 'Simulation', 'Cinemaware', '1', 'World War I flight action', 'WWI flight combat simulation.', 'Become a 16-bit flying ace in the Great War.', 'Play Wings 2: Aces High on the Super Nintendo.', 'Features impressive Mode 7 scrolling for the 16-bit landscapes. Engage in dogfights, bombing runs, and strafing missions in this atmospheric 16-bit sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wings-2---aces-high-usa-beta', 'SNES', 'Wings 2 - Aces High (USA) (Beta)', '1992', 'Simulation', 'Cinemaware', '1', 'World War I flight action', 'WWI flight combat (USA Beta).', 'Test the early 16-bit biplane physics.', 'Check out the Wings 2 Beta on the Super Nintendo.', 'A 16-bit development build. Features experimental camera angles and early versions of the 16-bit terrain rendering for the WWI battlefields.');
