INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winning-post-2---program-96-japan', 'SNES', 'Winning Post 2 - Program ''96 (Japan)', '1996', 'Simulation', 'Koei', '1', 'Horse racing management', 'Enhanced racing management sequel.', 'Lead your 16-bit stable to the ''96 championship.', 'Experience Winning Post 2: Program ''96 on SNES.', 'An expanded version of the sequel. Features updated 16-bit rosters, more detailed track conditions, and a refined interface for managing your 16-bit racing empire.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winning-post-2---program-96-japan-rev-a', 'SNES', 'Winning Post 2 - Program ''96 (Japan) (Rev A)', '1996', 'Simulation', 'Koei', '1', 'Horse racing management', 'Management sequel (Rev A).', 'Experience the ultimate 16-bit horse racing sim.', 'Play Winning Post 2: Program ''96 (Rev A) on SNES.', 'The definitive update for the ''96 edition. Optimizes 16-bit save data management and clarifies several complex breeding statistics for hardcore players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winning-post-2-japan', 'SNES', 'Winning Post 2 (Japan)', '1994', 'Simulation', 'Koei', '1', 'Horse racing management', 'Horse racing and breeding sequel.', 'Dominate the Japanese 16-bit racing circuit.', 'Play Winning Post 2 on the Super Famicom.', 'A massive leap for the series. Features a more dynamic 16-bit world where your decisions impact the long-term history of the Japanese racing league.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-extreme-skiing-and-snowboarding-usa', 'SNES', 'Winter Extreme Skiing and Snowboarding (USA)', '1995', 'Sports', 'Imagineering', '2', 'Extreme winter sports', 'Downhill skiing and snowboarding.', 'Conquer the 16-bit slopes in Winter Extreme.', 'Play Winter Extreme on the Super Nintendo.', 'Features fast-paced 16-bit winter sports action. Use specialized moves to navigate difficult downhill courses and reach the finish line in record 16-bit time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-gold-europe', 'SNES', 'Winter Gold (Europe)', '1994', 'Sports', 'Ocean Software', '2', 'Winter sports simulation', '3D sports simulation (Super FX 2).', 'Win 16-bit gold in this polygonal 3D showcase.', 'Experience Winter Gold on the Super Nintendo.', 'A technical marvel. Uses the Super FX 2 chip to render 3D polygons for Bobsleigh, Ski Jumping, and Luge, offering a unique 16-bit visual experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-olympic-games---lillehammer-94-europe-enfrdeesitptsvno', 'SNES', 'Winter Olympic Games - Lillehammer ''94 (Europe) (En,Fr,De,Es,It,Pt,Sv,No)', '1994', 'Sports', 'Eurocom', '4', 'Olympic sports compilation', 'Multi-event winter sports (1994).', 'Compete for 16-bit glory in the Lillehammer games.', 'Play Winter Olympic Games on the Super Nintendo.', 'The official 16-bit title of the ''94 Olympics. Compete in 10 different events with realistic physics and 16-bit international team representation.');
