INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizap!---ankoku-no-ou-japan', 'SNES', 'Wizap! - Ankoku no Ou (Japan)', '1996', 'RPG', 'ASCII Corporation', '1', 'Action RPG', 'Hybrid of RPG and strategy.', 'Defeat the dark king in this 16-bit fantasy epic.', 'Play Wizap! Ankoku no Ou on the Super Famicom.', 'A unique 16-bit title that blends party-based RPG exploration with tactical combat elements. Features a dark atmosphere and complex 16-bit character growth.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizap!---ankoku-no-ou-japan-beta', 'SNES', 'Wizap! - Ankoku no Ou (Japan) (Beta)', '1996', 'RPG', 'ASCII Corporation', '1', 'Action RPG', 'RPG/Strategy (Beta Version).', 'Explore the early 16-bit fantasy world of Wizap!', 'Check out the Wizap! Beta on the Super Famicom.', 'A rare 16-bit development look. Features prototype menu layouts and early versions of the 16-bit spell effects and monster animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizard-of-oz-the-usa', 'SNES', 'Wizard of Oz, The (USA)', '1993', 'Adventure', 'Sega', '1', 'Storybook adventure', 'Side-scrolling action-platformer.', 'Follow the Yellow Brick Road in 16-bit glory.', 'Play The Wizard of Oz on the Super Nintendo.', 'Control Dorothy, the Scarecrow, the Tin Man, and the Lion. Use their unique 16-bit abilities to navigate puzzles and reach the Emerald City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-gaiden-iv---taima-no-kodou-japan', 'SNES', 'Wizardry Gaiden IV - Taima no Kodou (Japan)', '1994', 'RPG', 'Sir-Tech', '1', 'Dungeon crawler', 'First-person dungeon crawler RPG.', 'Navigate the 16-bit maze and defeat ancient evils.', 'Play Wizardry Gaiden IV on the Super Famicom.', 'A specialized 16-bit entry in the legendary series. Features high-difficulty dungeon crawling, complex party management, and detailed 16-bit monster art.');
