INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-i-ii-iii---story-of-llylgamyn-japan-np', 'SNES', 'Wizardry I-II-III - Story of Llylgamyn (Japan) (NP)', '1991', 'RPG', 'Sir-Tech', '1', 'Dungeon crawler compilation', 'RPG Trilogy (I-II-III).', 'Experience the 16-bit origins of the RPG genre.', 'Play Wizardry I-II-III on the Super Famicom.', 'A comprehensive 16-bit remake of the first three classic games. Features updated 16-bit graphics, a unified interface, and the legendary high-difficulty gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-i-ii-iii---story-of-llylgamyn-japan-np-en-by-aeon-genesis-v10', 'SNES', 'Wizardry I-II-III - Story of Llylgamyn (Japan) (NP) [En by Aeon Genesis v1.0]', '1991', 'RPG', 'Sir-Tech', '1', 'Dungeon crawler compilation', 'RPG Trilogy (English Translation).', 'Play the Wizardry 16-bit remakes in English.', 'Play Wizardry I-II-III in English on the SNES.', 'The definitive 16-bit fan translation. Brings the first three Wizardry adventures to Western 16-bit fans with updated visuals and clear English text.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-v---heart-of-the-maelstrom-usa', 'SNES', 'Wizardry V - Heart of the Maelstrom (USA)', '1990', 'RPG', 'Sir-Tech', '1', 'Turn-based dungeon crawler', 'First-person dungeon crawler (Part V).', 'Dive into the Heart of the Maelstrom in 16-bit.', 'Play Wizardry V on the Super Nintendo.', 'A deep and challenging 16-bit RPG. Features a massive underground labyrinth, a complex magic system, and intense turn-based 16-bit combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-v---saika-no-chuushin-japan', 'SNES', 'Wizardry V - Saika no Chuushin (Japan)', '1990', 'RPG', 'Sir-Tech', '1', 'Turn-based dungeon crawler', 'Dungeon crawler (Japanese release).', 'Explore the 16-bit depths in the Japanese version.', 'Experience Wizardry V on the Super Famicom.', 'Known for its atmospheric 16-bit music and detailed enemy sprites. Navigate the dangerous 16-bit floors and manage your party''s survival.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-vi---kindan-no-mafude-japan', 'SNES', 'Wizardry VI - Kindan no Mafude (Japan)', '1991', 'RPG', 'Sir-Tech', '1', 'Classic dungeon crawler', 'Advanced dungeon crawler (Part VI).', 'Find the Cosmic Forge in this 16-bit RPG epic.', 'Play Wizardry VI on the Super Famicom.', 'A landmark in the series. Features a more narrative-driven 16-bit experience with a deep character class system and improved 16-bit dungeon graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-vi---kindan-no-mafude-japan-en-by-tico-v030b-~wizardry---bane-of-the-cosmic-forge-incomplete', 'SNES', 'Wizardry VI - Kindan no Mafude (Japan) [En by TiCo v0.30b] (~Wizardry - Bane of the Cosmic Forge) (Incomplete)', '1991', 'RPG', 'Sir-Tech', '1', 'Classic dungeon crawler', 'Dungeon crawler (Partial Translation).', 'Experience the beginning of Wizardry VI in English.', 'Try Wizardry VI (TiCo Translation) on the SNES.', 'A 16-bit fan translation effort. Focuses on the core menus and initial story segments, making the beginning of this 16-bit RPG masterpiece more accessible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfchild-usa', 'SNES', 'Wolfchild (USA)', '1992', 'Action', 'Core Design', '1', '2D cinematic platformer', 'Side-scrolling action (Wolfchild).', 'Transform into a 16-bit wolf to save your father.', 'Play Wolfchild on the Super Nintendo.', 'A high-energy 16-bit action game. Collect energy to transform into a powerful werewolf with specialized 16-bit melee and projectile attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfenstein-3d-europe', 'SNES', 'Wolfenstein 3D (Europe)', '1994', 'Shooter', 'ID Software', '1', 'First-person shooter', 'First-person shooter (Wolfenstein 3D).', 'Escape the 16-bit Castle Wolfenstein.', 'Play Wolfenstein 3D on the Super Nintendo.', 'The 16-bit port of the FPS pioneer. Battle through secret passages and 16-bit guards to take down the Nazi regime in this fast-paced shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfenstein-3d-japan', 'SNES', 'Wolfenstein 3D (Japan)', '1994', 'Shooter', 'ID Software', '1', 'First-person shooter', 'First-person shooter (Japan).', 'Experience the 16-bit FPS original in Japan.', 'Experience Wolfenstein 3D on the Super Famicom.', 'The authentic Japanese 16-bit release. Features the same intense first-person action and maze-like levels, optimized for the 16-bit console hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfenstein-3d-usa', 'SNES', 'Wolfenstein 3D (USA)', '1994', 'Shooter', 'ID Software', '1', 'First-person shooter', 'First-person shooter (USA release).', 'Blast your way out of the 16-bit fortress.', 'Play Wolfenstein 3D for the Super Nintendo.', 'A landmark 16-bit title. Navigate through floors of 16-bit action, finding secret stashes and weapons to ensure your escape from the dungeon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfenstein-3d-usa-beta', 'SNES', 'Wolfenstein 3D (USA) (Beta)', '1994', 'Shooter', 'ID Software', '1', 'First-person shooter', 'First-person shooter (USA Beta).', 'Explore the early 16-bit FPS engine development.', 'Check out the Wolfenstein 3D Beta on the SNES.', 'A rare 16-bit development look. Features early 16-bit texture rendering and prototype versions of the weapon sprites and enemy sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolverine---adamantium-rage-europe', 'SNES', 'Wolverine - Adamantium Rage (Europe)', '1994', 'Action', 'Bits Studios', '1', '2D action platformer', 'Side-scrolling action-adventure.', 'Survive the 16-bit Adamantium Rage as Wolverine.', 'Play Wolverine: Adamantium Rage on the SNES.', 'A technically impressive 16-bit title. Use Wolverine''s claws and 16-bit healing factor to battle through a gauntlet of deadly 16-bit enemies and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolverine---adamantium-rage-japan', 'SNES', 'Wolverine - Adamantium Rage (Japan)', '1994', 'Action', 'Bits Studios', '1', '2D action platformer', 'Action-adventure (Japanese release).', 'Master Wolverine''s 16-bit rage in Japan.', 'Experience Wolverine: Adamantium Rage on Super Famicom.', 'Known for its high difficulty and detailed 16-bit animations. Navigate through complex 16-bit environments and use your animal instincts to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolverine---adamantium-rage-usa', 'SNES', 'Wolverine - Adamantium Rage (USA)', '1994', 'Action', 'Bits Studios', '1', '2D action platformer', 'Action-adventure (USA release).', 'Uncover Wolverine''s 16-bit past in this action epic.', 'Play Wolverine for the Super Nintendo.', 'A dark and atmospheric 16-bit title. Features a wide array of combat moves, wall-climbing, and challenging 16-bit platforming segments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolverine---adamantium-rage-usa-beta-30b8', 'SNES', 'Wolverine - Adamantium Rage (USA) (Beta) [30B8]', '1994', 'Action', 'Bits Studios', '1', '2D action platformer', 'Action-adventure (Beta 30B8).', 'Test the early 16-bit claw combat and physics.', 'Check out the Wolverine Beta [30B8] on the SNES.', 'A 16-bit development slice. Features prototype versions of the 16-bit enemy AI and early iterations of the complex 16-bit level layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolverine---adamantium-rage-usa-beta-de51', 'SNES', 'Wolverine - Adamantium Rage (USA) (Beta) [DE51]', '1994', 'Action', 'Bits Studios', '1', '2D action platformer', 'Action-adventure (Beta DE51).', 'Explore the refined 16-bit Adamantium Rage assets.', 'Check out the Wolverine Beta [DE51] on the SNES.', 'A later 16-bit development build. Includes more polished 16-bit character sprites and near-final versions of the iconic 16-bit soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-project-j---kikai-no-shounen-pino-japan', 'SNES', 'Wonder Project J - Kikai no Shounen Pino (Japan)', '1994', 'Adventure', 'Enix', '1', 'Interactive adventure', 'Life-simulation and adventure.', 'Teach the robot boy Pino how to be human in 16-bit.', 'Play Wonder Project J on the Super Famicom.', 'A groundbreaking 16-bit title with Ghibli-esque animations. Interact with Pino, praise or scold his actions, and guide him through a charming 16-bit world to save his creator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-project-j---kikai-no-shounen-pino-japan-en-by-wakdhacks-v104-~wonder-project-j---mechanical-boy-pino', 'SNES', 'Wonder Project J - Kikai no Shounen Pino (Japan) [En by WakdHacks v1.04] (~Wonder Project J - Mechanical Boy Pino)', '1994', 'Adventure', 'Enix', '1', 'Interactive adventure', 'Life-simulation (English Translation).', 'Experience Pino''s 16-bit journey in English.', 'Play Wonder Project J in English on the SNES.', 'The complete 16-bit fan translation. Makes the complex teaching mechanics and emotional story accessible, allowing Western fans to enjoy this unique 16-bit masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wondrous-magic-japan', 'SNES', 'Wondrous Magic (Japan)', '1993', 'RPG', 'SystemSoft', '1', 'Traditional RPG', 'Turn-based JRPG (Wondrous Magic).', 'Master the 16-bit elemental magic to save the land.', 'Experience Wondrous Magic on the Super Famicom.', 'A classic 16-bit JRPG featuring a deep magic-focused combat system. Explore a vibrant world with a party of mages in this hidden 16-bit gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wordtris-usa', 'SNES', 'Wordtris (USA)', '1993', 'Puzzle', 'Tetris Company', '2', 'Word puzzle', 'Falling-block word puzzle.', 'Form 16-bit words from falling letter tiles.', 'Play Wordtris on the Super Nintendo.', 'A creative 16-bit entry in the "tris" series. Combine falling letters vertically or horizontally to clear lines and achieve high 16-bit scores.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-class-rugby-europe', 'SNES', 'World Class Rugby (Europe)', '1993', 'Sports', 'Brian A. Rice', '4', 'Rugby simulation', 'Rugby union simulation.', 'Win the 16-bit world cup on the rugby pitch.', 'Play World Class Rugby on the SNES.', 'Features a top-down perspective and fast-paced 16-bit gameplay. Includes a wide range of international teams and realistic 16-bit rugby tactics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-class-rugby-france', 'SNES', 'World Class Rugby (France)', '1993', 'Sports', 'Brian A. Rice', '4', 'Rugby simulation', 'Rugby simulation (French release).', 'Gagnez la coupe du monde de 16-bit rugby.', 'Jouez à World Class Rugby sur la SNES.', 'The official 16-bit French localization. Experience the high-stakes world of international rugby with fully translated menus for the 16-bit European audience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-class-rugby-japan', 'SNES', 'World Class Rugby (Japan)', '1993', 'Sports', 'Brian A. Rice', '4', 'Rugby simulation', 'Rugby simulation (Japanese release).', 'Experience 16-bit professional rugby in Japan.', 'Experience World Class Rugby on the Super Famicom.', 'The authentic Japanese 16-bit release. Offers deep tactical control over scrums, line-outs, and kicks in a comprehensive 16-bit sports package.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-class-rugby-2---kokunai-gekitou-hen-93-japan', 'SNES', 'World Class Rugby 2 - Kokunai Gekitou Hen ''93 (Japan)', '1993', 'Sports', 'Brian A. Rice', '4', 'Rugby simulation', 'Rugby simulation sequel (Japan).', 'Conquer the 16-bit domestic rugby league.', 'Play World Class Rugby 2 on the Super Famicom.', 'Features updated rosters and improved 16-bit animations. Focuses on the intense 16-bit competition within the Japanese national rugby scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-cup-striker-europe-enfrde', 'SNES', 'World Cup Striker (Europe) (En,Fr,De)', '1994', 'Sports', 'Rage Software', '2', 'Soccer simulation', 'Arcade-style soccer (Striker).', 'Score the winning goal in this 16-bit soccer sim.', 'Play World Cup Striker on the Super Nintendo.', 'Known for its fast-paced gameplay and Mode 7 pitch effects. A high-energy 16-bit sports title that emphasizes arcade fun over strict simulation.');
