INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-cup-striker-japan', 'SNES', 'World Cup Striker (Japan)', '1994', 'Sports', 'Rage Software', '2', 'Soccer simulation', 'Arcade-style soccer (Japan).', 'Win the 16-bit world tournament in Japan.', 'Experience World Cup Striker on the Super Famicom.', 'The Japanese release of the hit soccer title. Delivers smooth 16-bit scrolling and addictive competitive gameplay for soccer fans in Japan.');
