INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-heroes-usa', 'SNES', 'World Heroes (USA)', '1992', 'Fighting', 'ADK', '2', 'Arcade-style fighting', 'One-on-one fighting game (USA release).', 'Become the greatest 16-bit hero in the world.', 'Play World Heroes for the Super Nintendo.', 'Includes 8 unique 16-bit characters. A solid fighting game port that brings the high-energy Neo Geo action to the 16-bit SNES hardware.');
