INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-heroes-2-usa', 'SNES', 'World Heroes 2 (USA)', '1993', 'Fighting', 'ADK', '2', 'Arcade-style fighting', 'One-on-one fighting sequel (USA).', 'Win the ultimate 16-bit tournament in the sequel.', 'Experience World Heroes 2 on the Super Nintendo.', 'Features a unique tug-of-war style life bar in 16-bit. A high-quality fighting game with diverse characters and specialized "Super" moves.');
