INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-league-basketball-europe', 'SNES', 'World League Basketball (Europe)', '1992', 'Sports', 'Krisalis Software', '2', 'Basketball simulation', 'Arcade-style basketball (World League).', 'Dominate the 16-bit court in World League.', 'Play World League Basketball on the SNES.', 'Features a rotating Mode 7 court that creates a 3D-like 16-bit effect. A fast-paced arcade basketball title with high-flying dunks and intense 16-bit action.');
