INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-masters-golf-europe', 'SNES', 'World Masters Golf (Europe)', '1994', 'Sports', 'Krisalis Software', '2', 'Golf simulation', 'Professional golf simulation.', 'Win the 16-bit world masters tournament.', 'Play World Masters Golf on the Super Nintendo.', 'A realistic 16-bit golf sim with a top-down view. Manage wind, club choice, and shot power across beautiful 16-bit courses around the globe.');
