INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('worms-europe', 'SNES', 'Worms (Europe)', '1995', 'Strategy', 'Team17', '4', 'Turn-based strategy', 'Turn-based artillery strategy.', 'Eliminate the enemy 16-bit worm squads.', 'Play the legendary Worms on the Super Nintendo.', 'A 16-bit strategy classic. Use an arsenal of wacky weapons like exploding sheep and bananas to destroy the destructible 16-bit environments.');
