INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-raw-europe', 'SNES', 'WWF Raw (Europe)', '1994', 'Sports', 'Sculptured Software', '2', 'Professional wrestling', 'Professional wrestling (WWF Raw).', 'Dominate the 16-bit ring in the Raw arena.', 'Play WWF Raw on the Super Nintendo.', 'Features the "Mega Move" system. Control 16-bit legends like Lex Luger and Bret Hart in intense 16-bit matches with specialized character abilities.');
