INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-royal-rumble-europe', 'SNES', 'WWF Royal Rumble (Europe)', '1993', 'Sports', 'Acclaim', '4', 'Professional wrestling', 'Professional wrestling (Royal Rumble).', 'Survive the 30-man 16-bit Royal Rumble.', 'Play WWF Royal Rumble on the Super Nintendo.', 'A 16-bit wrestling masterpiece. Features the iconic over-the-top-rope battle royal and a great selection of 16-bit superstars from the early 90s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-royal-rumble-japan', 'SNES', 'WWF Royal Rumble (Japan)', '1993', 'Sports', 'Acclaim', '4', 'Professional wrestling', 'Professional wrestling (Japan).', 'Experience the 16-bit Royal Rumble in Japan.', 'Experience WWF Royal Rumble on Super Famicom.', 'The authentic Japanese release. Delivers the same high-energy 16-bit wrestling action and digitized character themes that made the game a 16-bit hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-royal-rumble-usa', 'SNES', 'WWF Royal Rumble (USA)', '1993', 'Sports', 'Acclaim', '4', 'Professional wrestling', 'Professional wrestling (USA release).', 'Become the last man standing in 16-bit.', 'Play WWF Royal Rumble for the Super Nintendo.', 'Features a refined grappling system and multiple 16-bit match modes. One of the most popular 16-bit wrestling titles on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-super-wrestlemania-europe', 'SNES', 'WWF Super WrestleMania (Europe)', '1992', 'Sports', 'Technos Japan', '2', 'Professional wrestling', 'Professional wrestling (WrestleMania).', 'Win the 16-bit title at Super WrestleMania.', 'Play WWF Super WrestleMania on the SNES.', 'The first 16-bit WWF title on the system. Features large character sprites and the signature 16-bit moves of icons like Hulk Hogan and Sid Justice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-super-wrestlemania-japan', 'SNES', 'WWF Super WrestleMania (Japan)', '1992', 'Sports', 'Technos Japan', '2', 'Professional wrestling', 'Professional wrestling (Japan).', 'Experience the 16-bit Super WrestleMania in Japan.', 'Experience WWF Super WrestleMania on Super Famicom.', 'The Japanese version of the wrestling classic. Features the star-studded 16-bit roster of the Golden Era in intense 16-bit arcade-style combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-super-wrestlemania-usa', 'SNES', 'WWF Super WrestleMania (USA)', '1992', 'Sports', 'Technos Japan', '2', 'Professional wrestling', 'Professional wrestling (USA release).', 'Climb the 16-bit ranks at Super WrestleMania.', 'Play WWF Super WrestleMania for the SNES.', 'Master the 16-bit tie-up and submission mechanics. A foundational 16-bit sports title that brought the spectacle of the WWF to the Super Nintendo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania-europe', 'SNES', 'WWF WrestleMania (Europe)', '1991', 'Sports', 'Sculptured Software', '2', 'Professional wrestling', 'Professional wrestling (Arcade style).', 'Experience the 16-bit "Arcade Game" at home.', 'Play WWF WrestleMania on the Super Nintendo.', 'A unique 16-bit port of the Midway arcade game. Features fast-paced, over-the-top 16-bit action with special supernatural moves for the wrestlers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania-japan', 'SNES', 'WWF WrestleMania (Japan)', '1991', 'Sports', 'Sculptured Software', '2', 'Professional wrestling', 'Professional wrestling (Japan).', 'Win the 16-bit arcade tournament in Japan.', 'Experience WWF WrestleMania on the Super Famicom.', 'The Japanese release of the arcade-style fighter. Delivers digitized 16-bit graphics and high-speed wrestling action that feels more like a 16-bit fighting game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania-usa', 'SNES', 'WWF WrestleMania (USA)', '1991', 'Sports', 'Sculptured Software', '2', 'Professional wrestling', 'Professional wrestling (USA release).', 'Become the 16-bit intercontinental champion.', 'Play WWF WrestleMania for the Super Nintendo.', 'Features 8 playable 16-bit stars. Use specialized 16-bit combos and finishers in this frantic and colorful arcade-style wrestling experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-japan-proto', 'SNES', 'X (Japan) (Proto)', '1992', 'Shooter', 'Nintendo', '1', 'First-person shooter', '3D space combat simulation (Proto).', 'Test the early 16-bit wireframe flight engine.', 'Check out the X (Japan) Prototype on the SNES.', 'A rare 16-bit look at the precursor to Star Fox. Features wireframe 3D graphics and early 16-bit space flight physics, showcasing the experimental era of the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-zone-europe', 'SNES', 'X Zone (Europe)', '1992', 'Shooter', 'Kemco', '1', 'First-person shooter', 'Light-gun shooting gallery.', 'Clear the 16-bit sectors in X Zone.', 'Play X Zone on the Super Nintendo.', 'Designed for the Super Scope. Navigate a futuristic 16-bit world, blasting robotic enemies and projectiles in a high-speed first-person shooting experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-zone-japan-usa', 'SNES', 'X Zone (Japan, USA)', '1992', 'Shooter', 'Kemco', '1', 'First-person shooter', 'Light-gun shooter (USA/Japan).', 'Defeat the rogue 16-bit AI in X Zone.', 'Experience X Zone for the Super Nintendo.', 'A technical 16-bit shooter. Features multiple difficulty levels and intense boss battles that test your 16-bit aiming precision with the light gun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-kaliber-2097-europe', 'SNES', 'X-Kaliber 2097 (Europe)', '1993', 'Action', 'Atlus', '2', 'Futuristic action platformer', 'Side-scrolling cyberpunk action.', 'Slice through the 16-bit future as Slash.', 'Play X-Kaliber 2097 on the Super Nintendo.', 'Features a dark, neon-soaked 16-bit aesthetic. Use your energy sword to battle mutants and cyborgs in a gritty post-apocalyptic 16-bit world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-kaliber-2097-usa', 'SNES', 'X-Kaliber 2097 (USA)', '1993', 'Action', 'Atlus', '2', 'Futuristic action platformer', 'Cyberpunk action (USA release).', 'Restore order to Neo New York in 16-bit.', 'Experience X-Kaliber 2097 for the Super Nintendo.', 'Known for its pulse-pounding 16-bit industrial soundtrack and challenging swordplay. Master the block and parry mechanics to survive the 16-bit urban jungle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-kaliber-2097-usa-beta', 'SNES', 'X-Kaliber 2097 (USA) (Beta)', '1993', 'Action', 'Atlus', '2', 'Futuristic action platformer', 'Action-platformer (USA Beta).', 'Explore the early 16-bit Neo New York levels.', 'Check out the X-Kaliber 2097 Beta on the SNES.', 'A 16-bit development slice. Features prototype enemy placements and early versions of the 16-bit cinematic boss introductions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men---mutant-apocalypse-europe', 'SNES', 'X-Men - Mutant Apocalypse (Europe)', '1994', 'Action', 'Capcom', '2', 'Side-scrolling action', 'Action-platformer (Capcom).', 'Save mutantkind in this 16-bit X-Men epic.', 'Play X-Men: Mutant Apocalypse on the SNES.', 'Control Wolverine, Cyclops, Gambit, Beast, and Psylocke. Features fluid 16-bit animations and character-specific missions with unique 16-bit abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men---mutant-apocalypse-japan', 'SNES', 'X-Men - Mutant Apocalypse (Japan)', '1994', 'Action', 'Capcom', '2', 'Side-scrolling action', 'Action-platformer (Japanese release).', 'Defeat Apocalypse in the 16-bit Japanese version.', 'Experience Mutant Apocalypse on the Super Famicom.', 'The authentic Capcom 16-bit classic. Known for its arcade-quality graphics and challenging 16-bit platforming that stays true to the Marvel characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men---mutant-apocalypse-usa', 'SNES', 'X-Men - Mutant Apocalypse (USA)', '1994', 'Action', 'Capcom', '2', 'Side-scrolling action', 'Action-platformer (USA release).', 'Master the 16-bit powers of the X-Men.', 'Play X-Men: Mutant Apocalypse for the SNES.', 'Navigate through Genosha and Avalon to stop Magneto. Each X-Man features specialized 16-bit move-sets inspired by the classic fighting games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xak---the-art-of-visual-stage-japan', 'SNES', 'Xak - The Art of Visual Stage (Japan)', '1993', 'RPG', 'Micro Cabin', '1', 'Japanese role-playing', 'Action-RPG (Isometric).', 'Embark on the 16-bit quest of Xak.', 'Experience Xak: The Art of Visual Stage on SNES.', 'A classic PC-engine port. Features a unique 16-bit isometric perspective, real-time combat, and a deep fantasy story following the young warrior Latok Kart.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xalabaias-adventure', 'SNES', 'Xalabaias Adventure', '1995', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Fan-made total conversion platformer.', 'Explore a surreal 16-bit world as Xalabaias.', 'Try Xalabaias Adventure on the Super Nintendo.', 'A creative 16-bit ROM hack of SMW. Features bizarre custom graphics, challenging level design, and a unique 16-bit atmosphere that deviates from Mario standards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xardion-usa', 'SNES', 'Xardion (USA)', '1992', 'Action', 'Nintendo', '1', 'Sci-fi action platformer', 'Action-platformer with mechs.', 'Stop the bio-mechanical threat in 16-bit Xardion.', 'Play Xardion on the Super Nintendo.', 'Features three interchangeable 16-bit robot forms. Manage your energy and switch between mechs to utilize different 16-bit weapons and jumping heights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yadamon---wonderland-dreams-japan', 'SNES', 'Yadamon - Wonderland Dreams (Japan)', '1992', 'Action', 'Game Freak', '1', 'Anime-style action', 'Puzzle-adventure (Yadamon).', 'Navigate the 16-bit dream world as the witch.', 'Play Yadamon: Wonderland Dreams on Super Famicom.', 'Based on the anime. Features a mix of 16-bit mini-games and point-and-click style adventure elements with vibrant 16-bit character sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yakouchuu-japan', 'SNES', 'Yakouchuu (Japan)', '1993', 'Action', 'Nichibutsu', '1', 'Dark action adventure', 'Sound-novel mystery (Horror).', 'Solve the 16-bit mystery of the night insects.', 'Experience Yakouchuu on the Super Famicom.', 'A dark 16-bit interactive story set on a ship. Features multiple branching paths and atmospheric sound design to create a tense 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yam-yam-japan', 'SNES', 'Yam Yam (Japan)', '1994', 'Puzzle', 'Mitchell', '2', 'Arcade-style puzzle', 'Puzzle-action game.', 'Guide the 16-bit ghosts to safety in Yam Yam.', 'Play Yam Yam on the Super Famicom.', 'A charming 16-bit title with a unique control scheme. Use physics and 16-bit environmental interaction to lead characters through hazardous puzzle stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yet-another-smw-hack-by-jp32', 'SNES', 'Yet Another SMW Hack by JP32', '1991', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Fan-made Mario World modification.', 'Conquer the 16-bit levels designed by JP32.', 'Try Yet Another SMW Hack on the SNES.', 'A high-quality 16-bit ROM hack focusing on traditional platforming with a modern 16-bit twist. Includes custom overworlds and secret 16-bit exits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yogi-bear-japan', 'SNES', 'Yogi Bear (Japan)', '1994', 'Platformer', 'BlueSky Software', '1', 'Cartoon platformer', 'Side-scrolling platformer (Japan).', 'Help Yogi Bear save Jellystone Park in 16-bit.', 'Play Yogi Bear on the Super Famicom.', 'The Japanese release of the cartoon tie-in. Features colorful 16-bit graphics and accessible platforming suitable for fans of the classic 16-bit animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yogi-bears-cartoon-capers-europe', 'SNES', 'Yogi Bear''s Cartoon Capers (Europe)', '1994', 'Platformer', 'BlueSky Software', '1', 'Cartoon platformer', 'Action-platformer (Europe).', 'Solve the Jellystone 16-bit mystery as Yogi.', 'Experience Yogi Bear''s Cartoon Capers on SNES.', 'Navigate through forests and caves to stop the park from being closed. A lighthearted 16-bit platformer with various hidden items to find.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yokoyama-mitsuteru-sangokushi-japan', 'SNES', 'Yokoyama Mitsuteru Sangokushi (Japan)', '1992', 'Strategy', 'Koei', '1', 'Historical strategy', 'Grand strategy (Sangokushi).', 'Unify China in this 16-bit Mitsuteru adaptation.', 'Play Yokoyama Mitsuteru Sangokushi on SNES.', 'Based on the famous manga. Features deep 16-bit strategic management, recruitment, and tactical turn-based battles across the Three Kingdoms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yokoyama-mitsuteru-sangokushi-japan-rev-a', 'SNES', 'Yokoyama Mitsuteru Sangokushi (Japan) (Rev A)', '1992', 'Strategy', 'Koei', '1', 'Historical strategy', 'Strategy simulation (Revision A).', 'Master the 16-bit Three Kingdoms in the refined version.', 'Play Sangokushi (Rev A) on the Super Famicom.', 'The updated 16-bit retail version. Fixes minor menu bugs and optimizes the 16-bit AI decision-making for a more challenging unification quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yokoyama-mitsuteru-sangokushi-2-japan', 'SNES', 'Yokoyama Mitsuteru Sangokushi 2 (Japan)', '1994', 'Strategy', 'Koei', '1', 'Historical strategy', 'Grand strategy sequel (Sangokushi 2).', 'Lead your 16-bit kingdom to glory in the sequel.', 'Experience Sangokushi 2 on the Super Famicom.', 'Expands on the 16-bit original with more officers, refined diplomacy options, and improved 16-bit map graphics for better tactical planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yokoyama-mitsuteru-sangokushi-bangi---sugoroku-eiyuuki-japan', 'SNES', 'Yokoyama Mitsuteru Sangokushi Bangi - Sugoroku Eiyuuki (Japan)', '1995', 'Board Game', 'Koei', '4', 'Turn-based board game', 'Board-game strategy spin-off.', 'Win the 16-bit Three Kingdoms board game.', 'Play Sangokushi Bangi on the Super Famicom.', 'A unique 16-bit "Sugoroku" style board game. Use characters from the series to compete for territories in a fun, 16-bit competitive format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yokozuna-monogatari-japan', 'SNES', 'Yokozuna Monogatari (Japan)', '1994', 'Sports', 'Oz Club', '2', 'Sumo wrestling', 'Sumo wrestling management RPG.', 'Rise to the top of the 16-bit sumo world.', 'Experience Yokozuna Monogatari on Super Famicom.', 'A deep 16-bit simulation. Manage your wrestler''s diet, training, and matches to reach the prestigious rank of Yokozuna in 16-bit style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-no-cookie---kuruppon-oven-de-cookie-japan', 'SNES', 'Yoshi no Cookie - Kuruppon Oven de Cookie (Japan)', '1992', 'Puzzle', 'Nintendo', '2', 'Tile-matching puzzle', 'Puzzle action (Rare Prize Edition).', 'Solve the 16-bit cookie puzzles to win the oven.', 'Play the rare Yoshi no Cookie (NP) on SNES.', 'A specialized 16-bit promotional release. Features additional 16-bit puzzles and a unique story mode not found in the standard retail version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-no-cookie-japan', 'SNES', 'Yoshi no Cookie (Japan)', '1992', 'Puzzle', 'Nintendo', '2', 'Tile-matching puzzle', 'Falling-block puzzle (Japan).', 'Match the 16-bit cookies to clear the stage.', 'Play Yoshi no Cookie on the Super Famicom.', 'The Japanese version of the puzzle classic. Features addictive 16-bit match-3 gameplay and a competitive 2-player mode with 16-bit Mario characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-no-road-hunting-japan', 'SNES', 'Yoshi no Road Hunting (Japan)', '1993', 'Action', 'Vivarium', '1', 'Arcade-style action', 'Light-gun shooting (Japan).', 'Ride 16-bit Yoshi and blast the Koopa troop.', 'Play Yoshi no Road Hunting on the Super Famicom.', 'The Japanese title for Yoshi''s Safari. The only Mario 16-bit title to use the Super Scope for first-person 16-bit shooting action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshi-saves-summer-vacation', 'SNES', 'Yoshi Saves Summer Vacation', '2020', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Fan-made SMW modification.', 'Enjoy a 16-bit summer quest with Yoshi.', 'Try Yoshi Saves Summer Vacation on the SNES.', 'A vibrant 16-bit ROM hack. Features a bright, summer-themed world map and creative levels that focus on Yoshi''s specialized 16-bit abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-cookie-europe', 'SNES', 'Yoshi''s Cookie (Europe)', '1993', 'Puzzle', 'GameTek', '2', 'Tile-matching puzzle', 'Falling-block puzzle (Europe).', 'Master the 16-bit bakery in Yoshi''s Cookie.', 'Experience Yoshi''s Cookie for the Super Nintendo.', 'A polished 16-bit puzzler. Arrange rows and columns of 16-bit cookies to clear them. Features a challenging solo quest and a frantic 2-player mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-cookie-usa', 'SNES', 'Yoshi''s Cookie (USA)', '1993', 'Puzzle', 'GameTek', '2', 'Tile-matching puzzle', 'Puzzle action (USA release).', 'Help Mario and Yoshi bake 16-bit cookies.', 'Play Yoshi''s Cookie on the Super Nintendo.', 'Known for its catchy 16-bit music and simple yet deep puzzle logic. A perfect 16-bit pick-up-and-play title for puzzle fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-highland', 'SNES', 'Yoshi''s Highland', '1995', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Fan-made SMW modification.', 'Explore the 16-bit highlands with Yoshi.', 'Try Yoshi''s Highland on the Super Nintendo.', 'A technical 16-bit ROM hack featuring custom 16-bit music, new enemy types, and a unique difficulty curve designed for 16-bit veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-island---no-crying-improved-sfx-and-red-coins', 'SNES', 'Yoshi''s Island - No Crying, Improved SFX and Red Coins', '2021', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Quality of Life modification (Yoshi''s Island).', 'Experience the 16-bit masterpiece with modern fixes.', 'Try the Yoshi''s Island QoL Mod on the SNES.', 'A specialized 16-bit tweak. Removes Baby Mario''s crying sound, improves 16-bit SFX, and marks collected red coins for a better 16-bit experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-safari-europe', 'SNES', 'Yoshi''s Safari (Europe)', '1993', 'Shooter', 'Nintendo', '1', 'On-rails shooter', 'Light-gun shooting (Europe).', 'Stop King Koopa in this 16-bit first-person quest.', 'Play Yoshi''s Safari on the Super Nintendo.', 'Use the Super Scope to blast through 16-bit levels while riding Yoshi. Features 16-bit Mode 7 scrolling and various power-ups to collect.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-safari-joypad-version', 'SNES', 'Yoshi''s Safari (Joypad Version)', '1993', 'Shooter', 'Nintendo', '1', 'On-rails shooter', 'Light-gun shooter (Pad Hack).', 'Play the 16-bit Safari without a light gun.', 'Try Yoshi''s Safari (Joypad Version) on SNES.', 'A vital 16-bit modification. Patches the game to allow 16-bit controller support, making this unique Super Scope title playable for everyone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-safari-usa', 'SNES', 'Yoshi''s Safari (USA)', '1993', 'Shooter', 'Nintendo', '1', 'On-rails shooter', 'Light-gun shooter (USA release).', 'Rescue the jewelry land in 16-bit.', 'Experience Yoshi''s Safari for the Super Nintendo.', 'The official 16-bit rail shooter. Battle Bowser''s kids in 16-bit giant mechs and enjoy the unique first-person perspective of a 16-bit Mario game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yoshis-strange-quest-v13', 'SNES', 'Yoshi''s Strange Quest (V1.3)', '2019', 'Platformer', 'Homebrew', '1', 'Fan-made platformer', 'Fan-made total conversion (Strange Quest).', 'Solve the 16-bit mystery of the missing eggs.', 'Play Yoshi''s Strange Quest on the Super Nintendo.', 'A massive 16-bit ROM hack. Features a humorous story, entire new 16-bit mechanics, and extremely creative level design that pushes the SMW engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('youchien-senki-madara-japan', 'SNES', 'Youchien Senki Madara (Japan)', '1992', 'RPG', 'Konami', '1', 'Japanese role-playing', 'Top-down RPG (Madara).', 'Lead the young warrior Madara in this 16-bit quest.', 'Play Youchien Senki Madara on the Super Famicom.', 'A charming 16-bit RPG featuring stylized characters and a strategic combat system. Explore a detailed world based on the popular manga series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('youkai-buster---ruka-no-daibouken-japan', 'SNES', 'Youkai Buster - Ruka no Daibouken (Japan)', '1993', 'Action', 'Banpresto', '1', 'Anime action adventure', 'Side-scrolling action-platformer.', 'Defeat the 16-bit monsters in Ruka''s adventure.', 'Play Youkai Buster: Ruka no Daibouken on SNES.', 'A vibrant and fast-paced 16-bit platformer. Use unique monster-catching mechanics and diverse weapons to clear stages filled with Japanese folklore creatures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('young-merlin-europe', 'SNES', 'Young Merlin (Europe)', '1993', 'Action', 'Westwood Studios', '1', 'Action adventure', 'Action-adventure (Isometric).', 'Save the 16-bit kingdom from an ancient curse.', 'Play Young Merlin on the Super Nintendo.', 'A visually stunning 16-bit adventure. Use magic items and solve environmental puzzles in a seamless world, featuring impressive pre-rendered graphics for the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('young-merlin-usa', 'SNES', 'Young Merlin (USA)', '1993', 'Action', 'Westwood Studios', '1', 'Action adventure', 'Action-adventure (USA release).', 'Master the 16-bit magic of Young Merlin.', 'Experience Young Merlin for the Super Nintendo.', 'Combines exploration with real-time combat. Navigate through 16-bit forests and dungeons to defeat the Shadow King in this high-quality Westwood Studios title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ys-iii---wanderers-from-ys-japan', 'SNES', 'Ys III - Wanderers from Ys (Japan)', '1991', 'Action', 'Nihon Falcom', '1', 'Action role-playing', 'Side-scrolling action RPG (Ys III).', 'Journey to the 16-bit land of Felghana.', 'Play Ys III: Wanderers from Ys on Super Famicom.', 'A departure for the series featuring 16-bit side-scrolling action. Master Adol Christin''s swordplay and magic in a quest filled with legendary bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ys-iii---wanderers-from-ys-usa', 'SNES', 'Ys III - Wanderers from Ys (USA)', '1991', 'Action', 'Nihon Falcom', '1', 'Action role-playing', 'Side-scrolling action RPG (USA).', 'Experience Adol''s 16-bit side-scrolling epic.', 'Experience Ys III on the Super Nintendo.', 'Known for its incredible 16-bit soundtrack and fast combat. Battle through diverse environments to uncover the mystery of the Galbalan threat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ys-iv---mask-of-the-sun-japan', 'SNES', 'Ys IV - Mask of the Sun (Japan)', '1993', 'Action', 'Nihon Falcom', '1', 'Action role-playing', 'Top-down action RPG (Ys IV).', 'Explore the 16-bit land of Celceta as Adol.', 'Play Ys IV: Mask of the Sun on Super Famicom.', 'Returns to the classic top-down 16-bit "bump combat" system. Features a massive world, deep lore, and the series'' signature high-energy 16-bit music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ys-iv---mask-of-the-sun-japan-en-by-aeon-genesis-v20', 'SNES', 'Ys IV - Mask of the Sun (Japan) [En by Aeon Genesis v2.0]', '1993', 'Action', 'Nihon Falcom', '1', 'Action role-playing', 'Action RPG (English Translation).', 'Play the lost 16-bit Ys chapter in English.', 'Play Ys IV (English Translation) on the SNES.', 'The complete 16-bit fan translation by Aeon Genesis. Fully localizes the complex story of Celceta, making this 16-bit adventure accessible to Western fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ys-v---expert-japan', 'SNES', 'Ys V - Expert (Japan)', '1994', 'RPG', 'Nihon Falcom', '1', 'Japanese role-playing', 'Enhanced action RPG (Ys V).', 'Master the 16-bit alchemy system in the Expert version.', 'Play Ys V Expert on the Super Famicom.', 'An updated 16-bit version of the fifth entry. Features a higher difficulty level, new 16-bit dungeons, and refined combat mechanics for Ys veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ys-v---ushinawareta-suna-no-miyako-kefin-japan', 'SNES', 'Ys V - Ushinawareta Suna no Miyako Kefin (Japan)', '1995', 'RPG', 'Nihon Falcom', '1', 'Japanese role-playing', 'Action RPG (Lost City of Kefin).', 'Discover the 16-bit secrets of the sand city.', 'Experience Ys V on the Super Famicom.', 'Introduces 16-bit manual sword swinging and jumping to the series. Explore the desert kingdom and craft powerful 16-bit spells using the alchemy system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yume-maboroshi-no-gotoku-japan', 'SNES', 'Yume Maboroshi no Gotoku (Japan)', '1992', 'RPG', 'Namco', '1', 'Story-driven RPG', 'Historical strategy RPG.', 'Navigate the 16-bit Warring States period.', 'Play Yume Maboroshi no Gotoku on Super Famicom.', 'A deep 16-bit simulation of feudal Japan. Balance diplomacy, resource management, and tactical warfare to unify the 16-bit islands.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuu-yuu-hakusho---tokubetsu-hen-japan', 'SNES', 'Yuu Yuu Hakusho - Tokubetsu Hen (Japan)', '1994', 'Action', 'Tom Create', '1', 'Anime action', 'Cinematic fighting game (Yuu Yuu).', 'Relive the 16-bit Dark Tournament in the Special Edition.', 'Play Yuu Yuu Hakusho Tokubetsu Hen on SNES.', 'Features a unique 16-bit command-based combat system. Watch the anime-style action unfold in beautifully animated 16-bit cinematic sequences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuu-yuu-hakusho-japan', 'SNES', 'Yuu Yuu Hakusho (Japan)', '1993', 'Action', 'Toei Animation', '2', 'Anime action brawler', 'Cinematic fighting game (Original).', 'Master the 16-bit Spirit Gun as Yusuke.', 'Experience the original Yuu Yuu Hakusho on SNES.', 'Based on the hit anime. Use 16-bit tactical commands to execute powerful spirit attacks and defeat iconic villains in a cinematic format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuu-yuu-hakusho-2---kakutou-no-shou-japan', 'SNES', 'Yuu Yuu Hakusho 2 - Kakutou no Shou (Japan)', '1994', 'Fighting', 'Toei Animation', '2', 'Anime fighting', '2D fighting game (Part 2).', 'Win the 16-bit martial arts tournament.', 'Play Yuu Yuu Hakusho 2 on the Super Famicom.', 'A traditional 16-bit 2D fighter. Features a large roster of characters, each with specialized 16-bit special moves and high-quality spirit energy effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuu-yuu-hakusho-final---makai-saikyou-retsuden-japan', 'SNES', 'Yuu Yuu Hakusho Final - Makai Saikyou Retsuden (Japan)', '1995', 'Fighting', 'Toei Animation', '2', 'Competitive fighting', '2D fighting game (Final entry).', 'Determine the 16-bit king of the Demon World.', 'Play Yuu Yuu Hakusho Final on Super Famicom.', 'Widely considered the best 16-bit fighter in the series. Features fast gameplay, large sprites, and complex 16-bit combos for competitive play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuujin-janjuu-gakuen-japan', 'SNES', 'Yuujin Janjuu Gakuen (Japan)', '1994', 'Mahjong', 'Nichibutsu', '4', 'School-themed mahjong', 'Competitive Mahjong simulation.', 'Master the 16-bit tiles at Janjuu Gakuen.', 'Play Yuujin Janjuu Gakuen on the Super Famicom.', 'Features quirky 16-bit characters and a school-based setting. A solid 16-bit Mahjong experience with various difficulty levels and unlockable content.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuujin-janjuu-gakuen-2-japan', 'SNES', 'Yuujin Janjuu Gakuen 2 (Japan)', '1995', 'Mahjong', 'Nichibutsu', '4', 'School-themed mahjong', 'Mahjong simulation sequel.', 'Climb the 16-bit ranks in the Janjuu sequel.', 'Experience Yuujin Janjuu Gakuen 2 on SNES.', 'Refines the 16-bit Mahjong mechanics of the first game. Includes more character interactions and updated 16-bit graphics for the tile-matching matches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuujin-no-furi-furi-girls-japan', 'SNES', 'Yuujin no Furi Furi Girls (Japan)', '1994', 'Action', 'Naxat Soft', '2', 'Arcade-style action', 'Variety/Party game collection.', 'Win the 16-bit "Furi Furi" girls challenges.', 'Play Yuujin no Furi Furi Girls on Super Famicom.', 'Features a variety of 16-bit mini-games starring cute female characters. Test your 16-bit reflexes and luck in this colorful competitive collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yuuyu-no-quiz-de-go!-go!-japan', 'SNES', 'Yuuyu no Quiz de Go! Go! (Japan)', '1993', 'Quiz', 'Tom Create', '2', 'Quiz game', 'Quiz and trivia game.', 'Answer your way to 16-bit victory with Yuuyu.', 'Experience Yuuyu no Quiz de Go! Go! on SNES.', 'A Japanese 16-bit trivia challenge. Features thousands of questions across multiple categories, presented with a charming 16-bit game show aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zaitaku-touhyou-system---spat4-wide---minami-kantou-keibajou-denwa-touhyou-center-japan', 'SNES', 'Zaitaku Touhyou System - SPAT4-Wide - Minami Kantou Keibajou Denwa Touhyou Center (Japan)', '1994', 'Utility', 'Nintendo', '1', 'Broadcast service software', 'Horse racing betting system.', 'Manage 16-bit horse racing bets via SPAT4.', 'Check out the Zaitaku Touhyou System on SNES.', 'A specialized 16-bit utility for the Japanese market. Allowed users to track horse racing stats and manage 16-bit betting data via the modem peripheral.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zakuro-no-aji-japan', 'SNES', 'Zakuro no Aji (Japan)', '1995', 'Adventure', 'Imagineer', '1', 'Story-driven adventure', 'Sound-novel mystery (Zakuro).', 'Solve the 16-bit mystery of the pomegranate.', 'Play Zakuro no Aji on the Super Famicom.', 'An atmospheric 16-bit horror story. Navigate through a dark narrative with multiple endings based on your 16-bit choices and deductions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zan-ii-spirits-japan', 'SNES', 'Zan II Spirits (Japan)', '1991', 'Action', 'Wolf Team', '1', 'Action role-playing', 'Turn-based strategy (Zan II).', 'Command 16-bit samurai in a quest for dominance.', 'Play Zan II Spirits on the Super Famicom.', 'A deep 16-bit tactical simulation set in feudal Japan. Manage your clan''s resources and lead 16-bit armies in complex grid-based battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zan-iii-spirits-japan', 'SNES', 'Zan III Spirits (Japan)', '1992', 'Action', 'Wolf Team', '1', 'Action role-playing', 'Turn-based strategy sequel.', 'Expand your 16-bit empire in the third entry.', 'Experience Zan III Spirits on the Super Famicom.', 'Offers a more refined 16-bit interface and deeper diplomatic options. Master the art of 16-bit war and politics in ancient Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda-alttp---bs-x-mascot-edition---boy', 'SNES', 'Zelda ALttP - BS-X Mascot Edition - Boy', '1993', 'Action', 'Wolf Team', '1', 'Action role-playing', 'Action-adventure (Mascot Mod).', 'Explore 16-bit Hyrule as the BS-X Boy mascot.', 'Try the Zelda ALttP Mascot Edition (Boy) on SNES.', 'A creative 16-bit modification of Link to the Past. Replaces Link with the male Satellaview mascot, offering a fresh 16-bit visual experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda-alttp---bs-x-mascot-edition---girl', 'SNES', 'Zelda ALttP - BS-X Mascot Edition - Girl', '1997', 'Action', 'Nintendo', '1', 'Promotional adventure', 'Action-adventure (Mascot Mod).', 'Save 16-bit Hyrule as the BS-X Girl mascot.', 'Try the Zelda ALttP Mascot Edition (Girl) on SNES.', 'A 16-bit ROM hack that swaps the protagonist for the female Satellaview avatar, including updated 16-bit color palettes for the main character.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zelda-starring-zelda-2', 'SNES', 'Zelda starring Zelda 2', '1997', 'Action', 'Nintendo', '1', 'Promotional adventure', 'Action-adventure (Fan Hack).', 'Play as the princess in a 16-bit Hyrule quest.', 'Try Zelda starring Zelda 2 on the SNES.', 'An impressive 16-bit total conversion. Reimagines the classic 16-bit adventure with Zelda as the hero, featuring new 16-bit puzzles and dialogue.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zen-nihon-gt-senshuken-japan', 'SNES', 'Zen-Nihon GT Senshuken (Japan)', '2020', 'Adventure', 'Homebrew', '1', 'Fan-made adventure', 'GT racing simulation.', 'Win the 16-bit Japanese GT championship.', 'Play Zen-Nihon GT Senshuken on Super Famicom.', 'Features real-world 16-bit licensed cars and tracks. A technical racing title that focuses on realistic 16-bit handling and car physics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zen-nihon-pro-wrestling---fight-da-pon!-japan', 'SNES', 'Zen-Nihon Pro Wrestling - Fight da Pon! (Japan)', '1993', 'Sports', 'Human Entertainment', '2', 'Professional wrestling', 'Wrestling and RPG hybrid.', 'Win the 16-bit wrestling cup with a tactical twist.', 'Play Fight da Pon! on the Super Famicom.', 'Combines 16-bit professional wrestling with turn-based RPG elements. Use cards and commands to execute powerful 16-bit slams and holds.');
