INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zen-nihon-pro-wrestling-2---3-4-budoukan-japan', 'SNES', 'Zen-Nihon Pro Wrestling 2 - 3-4 Budoukan (Japan)', '1992', 'Sports', 'Human Entertainment', '2', 'Professional wrestling', 'Wrestling simulation sequel.', 'Dominate the 16-bit Budoukan arena.', 'Play Zen-Nihon Pro Wrestling 2 on Super Famicom.', 'Expands the 16-bit roster and improves the animation fluidity. Includes a robust 16-bit career mode and challenging tag-team mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zen-nihon-pro-wrestling---sekai-saikyou-tag-japan', 'SNES', 'Zen-Nihon Pro Wrestling'' - Sekai Saikyou Tag (Japan)', '1993', 'Sports', 'Human Entertainment', '4', 'Tag-team wrestling', 'Wrestling (World''s Strongest Tag).', 'Become the 16-bit world tag team champions.', 'Experience Zen-Nihon Pro Wrestling'' on SNES.', 'Focuses on the legendary tag team tournaments. Features complex 16-bit double-team moves and updated 16-bit rosters for wrestling fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zenkoku-juudan-ultra-shinri-game-japan', 'SNES', 'Zenkoku Juudan Ultra Shinri Game (Japan)', '1995', 'Psychological', 'Visco', '1', 'Personality quiz game', 'Psychological quiz game.', 'Test your 16-bit mind in the Ultra Shinri Game.', 'Play Zenkoku Juudan Ultra Shinri Game on SNES.', 'A unique 16-bit title focused on psychological testing and personality quizzes, presented with colorful 16-bit graphics and scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zenkoku-koukou-soccer-japan', 'SNES', 'Zenkoku Koukou Soccer (Japan)', '1993', 'Sports', 'Athena', '2', 'High school soccer', 'High school soccer simulation.', 'Lead your 16-bit team to the national finals.', 'Play Zenkoku Koukou Soccer on the Super Famicom.', 'Focuses on the intense world of Japanese high school soccer. Manage your 16-bit squad and win matches in this detailed sports sim.');
