INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zero-the-kamikaze-squirrel-europe', 'SNES', 'Zero the Kamikaze Squirrel (Europe)', '1994', 'Platformer', 'Scitron & Art', '2', 'Fast-paced platformer', 'Side-scrolling action-platformer.', 'Stop the evil tycoon in 16-bit style as Zero.', 'Play Zero the Kamikaze Squirrel on the SNES.', 'A high-speed 16-bit spin-off. Use Zero''s flight and combat skills to navigate challenging levels filled with 16-bit hazards and enemies.');
