INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zico-soccer-japan', 'SNES', 'Zico Soccer (Japan)', '1994', 'Sports', 'Electronic Arts', '2', 'Soccer simulation', 'Soccer management (Zico).', 'Manage your 16-bit team with the legend Zico.', 'Play Zico Soccer on the Super Famicom.', 'A specialized 16-bit simulation. Use the SNES Mouse to manage tactics and execute plays in this unique 16-bit managerial soccer game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zig-zag-cat---dachou-club-mo-oosawagi-da-japan', 'SNES', 'Zig Zag Cat - Dachou Club mo Oosawagi da (Japan)', '1994', 'Platformer', 'Nichibutsu', '2', 'Comedic platformer', 'Action-puzzle hybrid.', 'Guide the 16-bit cat through the obstacle course.', 'Play Zig Zag Cat on the Super Famicom.', 'Combines breakout-style gameplay with 16-bit platforming. Use the paddle to bounce the 16-bit cat and clear diverse puzzle stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zombies-europe', 'SNES', 'Zombies (Europe)', '1993', 'Action', 'Bitmap Brothers', '2', 'Run-and-gun action', 'Top-down action-comedy (Zombies).', 'Save the 16-bit neighborhood from the undead.', 'Play Zombies on the Super Nintendo (Europe).', 'The European title for Zombies Ate My Neighbors. Features frantic 16-bit action, dozens of B-movie monsters, and a great 2-player co-op mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zombies-europe-beta', 'SNES', 'Zombies (Europe) (Beta)', '1993', 'Action', 'Bitmap Brothers', '2', 'Run-and-gun action', 'Top-down action (Beta).', 'Test the early 16-bit zombie-slaying levels.', 'Check out the Zombies Beta on the Super Nintendo.', 'A rare 16-bit development look. Features prototype weapon balance and early versions of the iconic 16-bit level music and sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zombies-ate-my-neighbors-usa', 'SNES', 'Zombies Ate My Neighbors (USA)', '1993', 'Action', 'LucasArts', '2', 'Run-and-gun action', 'Top-down action (USA release).', 'Rescue the 16-bit cheerleaders from monsters.', 'Experience Zombies Ate My Neighbors for the SNES.', 'A 16-bit cult classic. Use an arsenal of wacky weapons like soda cans and water guns to survive 48 levels of 16-bit monster mayhem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zombies-ate-my-neighbors-usa-hack-by-frank-maggiore-v10-~ultimate-zombies-ate-my-neighbors', 'SNES', 'Zombies Ate My Neighbors (USA) [Hack by Frank Maggiore v1.0] (~Ultimate Zombies Ate My Neighbors)', '1994', 'Action', 'LucasArts', '2', 'Run-and-gun action', 'Action hack (Ultimate Zombies).', 'Survive the ultimate 16-bit zombie challenge.', 'Try Ultimate Zombies Ate My Neighbors on the SNES.', 'A massive 16-bit fan expansion. Includes new 16-bit levels, modified weapon behaviors, and a much higher difficulty for 16-bit veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool---ninja-of-the-nth-dimension-europe', 'SNES', 'Zool - Ninja of the Nth Dimension (Europe)', '1993', 'Platformer', 'Gremlin Graphics', '1', 'Speed-based platformer', 'Side-scrolling platformer (Nth Dimension).', 'Master the 16-bit ninja speed of Zool.', 'Play Zool on the Super Nintendo.', 'A fast-paced 16-bit platformer featuring a candy-themed world. Use 16-bit ninja skills and power-ups to clear levels at high speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool---ninja-of-the-nth-dimension-usa', 'SNES', 'Zool - Ninja of the Nth Dimension (USA)', '1993', 'Platformer', 'Gremlin Graphics', '1', 'Speed-based platformer', 'Action-platformer (USA release).', 'Defeat the 16-bit Chupa Chups alien threat.', 'Experience Zool for the Super Nintendo.', 'Known for its frantic 16-bit pace and colorful graphics. A challenging 16-bit title that tests your reflexes and platforming precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool-no-yume-bouken-japan', 'SNES', 'Zool no Yume Bouken (Japan)', '1994', 'Platformer', 'ASCII Corporation', '1', 'Japanese-exclusive platformer', 'Action-platformer (Japanese version).', 'Experience the 16-bit ninja Zool in Japan.', 'Experience Zool no Yume Bouken on Super Famicom.', 'The official 16-bit Japanese release. Features the same high-speed 16-bit action and imaginative level designs as the Western versions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoop-europe', 'SNES', 'Zoop (Europe)', '1995', 'Puzzle', 'Viacom New Media', '2', 'Abstract puzzle', 'Falling-object puzzle game.', 'Match the 16-bit shapes in the grid.', 'Play Zoop on the Super Nintendo.', 'A unique 16-bit puzzler. Clear the 16-bit screen by matching shapes of the same color before they reach the center in this fast-paced 16-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoop-usa', 'SNES', 'Zoop (USA)', '1995', 'Puzzle', 'Viacom New Media', '2', 'Abstract puzzle', 'Puzzle action (USA release).', 'Master the 16-bit logic of Zoop.', 'Experience Zoop for the Super Nintendo.', 'Features addictive 16-bit gameplay and a catchy soundtrack. A perfect 16-bit pick-up-and-play game for fans of abstract puzzle titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zootto-mahjong!-japan-np', 'SNES', 'Zootto Mahjong! (Japan) (NP)', '1994', 'Mahjong', 'Nintendo', '4', 'Traditional mahjong', 'Mahjong simulation (NP Edition).', 'Play 16-bit Mahjong forever in Zootto.', 'Play Zootto Mahjong! on the Super Famicom.', 'A comprehensive 16-bit Mahjong title released via the Nintendo Power service. Features multiple modes and clean 16-bit tile graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zzzunk___taiwan-16-mahjong-ii---horoscope-girls-edition-hong-kong-unl', 'SNES', 'ZZZUNK___Taiwan 16 Mahjong II - Horoscope Girls Edition (Hong Kong) (Unl)', '1995', 'Mahjong', 'Unlicensed', '4', 'Adult mahjong', 'Taiwanese Mahjong (Unlicensed).', 'Win the 16-bit tournament with the Horoscope Girls.', 'Play Taiwan 16 Mahjong II on the SNES.', 'An unlicensed 16-bit Mahjong title from Hong Kong. Features unique character art and 16-bit Taiwanese-style Mahjong rules for adult audiences.');